// The German of What's new, what each version changed (lib/whats-new.ts, app/whats-new.tsx) (i18n/de/index.ts).
export const whatsNew: Record<string, string> = {
  "**The day stands out in every chat**: over the first message of each day, groups and Chat with myself too, the day shows in bold between two lines: **Today**, **Yesterday**, the weekday within the last week, and before that the weekday and date. See [Chat through a relay](#relay).":
    "**Der Tag ist in jedem Chat gut zu sehen**: Über der ersten Nachricht jedes Tages, auch in Gruppen und im Chat mit mir selbst, steht der Tag fett zwischen zwei Linien: **Heute**, **Gestern**, in der letzten Woche der Wochentag und davor Wochentag und Datum. Siehe [Chat über ein Relay](#relay).",
  "**The microphone writes, if you like**: tap the microphone beside the message field and choose **Speak to write**, and from then on holding it writes what you say into the field, until you choose **Voice message** again. The choice stays for every chat. See [Chat through a relay](#relay).": "**Das Mikrofon schreibt, wenn du willst**: Tippe auf das Mikrofon neben dem Nachrichtenfeld und wähle **Sprechen statt tippen**, und von da an schreibt es, gedrückt gehalten, ins Feld, was du sagst, bis du wieder **Sprachnachricht** wählst. Die Wahl gilt für jeden Chat. Siehe [Chat über ein Relay](#relay).",
  "**Ways on home**: once a relay is set, the line under the top bar of home is **Ways**, with a dot for each way your messages go out by and how many of them wait; a tap opens **Ways**. See [How Erevos picks the path](#paths).": "**Wege auf der Startseite**: Sobald ein Relay gesetzt ist, ist die Zeile unter der oberen Leiste der Startseite **Wege**, mit einem Punkt für jeden Weg, auf dem deine Nachrichten hinausgehen, und wie viele davon warten; ein Tippen öffnet **Wege**. Siehe [Wie Erevos den Weg wählt](#paths).",
  "**LoRa makes up for lost pieces, and long texts go shorter**: a text sent by LoRa in several pieces now goes with spare pieces, one for each four, so it comes whole even when a piece or two are lost on the air; older Erevos reads it as before. And long texts are packed, with nothing lost, before they are encrypted, when that makes them go in fewer bytes, to contacts whose Erevos unpacks them. See [Over a LoRa radio](#lora).": "**LoRa ersetzt verlorene Teile, und lange Texte werden kürzer**: Ein Text, der über LoRa in mehreren Teilen geht, geht jetzt mit Ersatzteilen, einem für je vier, und kommt so ganz an, auch wenn ein oder zwei Teile in der Luft verloren gehen; ein älteres Erevos liest ihn wie bisher. Und lange Texte werden verlustfrei gepackt, bevor sie verschlüsselt werden, wenn sie so weniger Bytes brauchen, an Kontakte, deren Erevos sie entpackt. Siehe [Über LoRa-Funk](#lora).",
  "**Ways at a glance**: **Settings** → **Relay and networks** → **Ways** shows each way your messages go out by, the relay, Nostr, the phones nearby, LoRa, SMS and Tor, with how each is now and a line under it: full when it works, faint when it reaches no one now, dashed when it is off. Above them, how many of your messages wait to go, an orange dot for each. Only the space that is open shows, never hidden chats. See [How Erevos picks the path](#paths).": "**Wege auf einen Blick**: **Einstellungen** → **Relay und Netze** → **Wege** zeigt jeden Weg, über den deine Nachrichten hinausgehen, das Relay, Nostr, die Telefone in der Nähe, LoRa, SMS und Tor, mit dem Zustand jedes Wegs und einer Linie darunter: voll, wenn er funktioniert, blass, wenn er gerade niemanden erreicht, gestrichelt, wenn er aus ist. Darüber, wie viele deiner Nachrichten darauf warten, zu gehen, ein oranger Punkt für jede. Nur der offene Bereich zeigt sich, nie versteckte Chats. Siehe [Wie Erevos den Weg wählt](#paths).",
  "**Answer a hidden contact's call with no PIN**: where hidden chats receive while closed, **Answer** on the ringing screen takes their contact's call at once, on a call screen with no name and no face, and the hidden chats stay closed; the small sign and the PIN still open them. See [Hidden chats](#hidden).": "**Anruf eines versteckten Kontakts ohne PIN annehmen**: Wo versteckte Chats geschlossen empfangen, nimmt **Annehmen** auf dem Klingelbildschirm den Anruf sofort an, auf einem Bildschirm ohne Namen und ohne Gesicht, und die versteckten Chats bleiben geschlossen; das kleine Zeichen und die PIN öffnen sie weiterhin. Siehe [Versteckte Chats](#hidden).",
  "**See yourself in a video call**: once their picture comes, yours stays in a small window in the top corner, on both phones; before, it vanished, and each side saw only the other. See [Chat through a relay](#relay).": "**Sieh dich selbst im Videoanruf**: Sobald das Bild der anderen Seite kommt, bleibt deines in einem kleinen Fenster in der oberen Ecke, auf beiden Telefonen; vorher verschwand es, und jede Seite sah nur die andere. Siehe [Chat über ein Relay](#relay).",
  "**Phones nearby are off until you turn them on**: Erevos no longer looks for phones nearby by itself, with Bluetooth, Wi-Fi Aware or on the same Wi-Fi, as on the same Wi-Fi it held a call back for up to a minute before it rang. Turn on **Look for phones nearby** under **Nearby, with no internet**, on **New chat**, to chat and call with no internet. See [Chat with a nearby phone](#nearby).": "**Telefone in der Nähe sind aus, bis du sie einschaltest**: Erevos sucht nicht mehr von selbst nach Telefonen in der Nähe, per Bluetooth, Wi-Fi Aware oder im selben WLAN, da es im selben WLAN einen Anruf bis zu einer Minute aufhielt, bevor er klingelte. Schalte **Nach Telefonen in der Nähe suchen** unter **In der Nähe, ohne Internet** in **Neuer Chat** ein, um ohne Internet zu chatten und anzurufen. Siehe [Chat mit einem Telefon in der Nähe](#nearby).",
  "**Open a file with another app**: a file in a chat, a PDF say, has **Open** too, not only **Save**: the phone's app for it reads it from Erevos's memory, with no copy left on the phone. Erevos asks first, and never opens web pages, drawings or app packages that way. See [Chat through a relay](#relay).": "**Eine Datei mit einer anderen App öffnen**: Eine Datei im Chat, etwa ein PDF, hat auch **Öffnen**, nicht nur **Speichern**: Die App des Telefons liest sie aus dem Speicher von Erevos, ohne dass eine Kopie auf dem Telefon bleibt. Erevos fragt zuerst und öffnet Webseiten, Zeichnungen und App-Pakete nie so. Siehe [Chat über ein Relay](#relay).",
  "**Shared chats say how far they are, on both phones**: chats a contact shared from a relay your Erevos does not take from by itself show **Coming, 40%** once you tap them, and their phone says it is taking them; if they did not come, both phones say so and yours buzzes twice. See [Chat through a relay](#relay).": "**Geteilte Chats zeigen auf beiden Telefonen, wie weit sie sind**: Chats, die ein Kontakt von einem Relay geteilt hat, von dem dein Erevos nicht von selbst holt, zeigen **Kommt an, 40%**, sobald du darauf tippst, und sein Telefon sagt, dass du sie holst; kamen sie nicht, sagen es beide Telefone, und deines vibriert zweimal. Siehe [Chat über ein Relay](#relay).",
  "**Calls connect again**: a call that rang no longer stays at **Connecting** on both phones; each phone now waits for its own addresses before it calls or answers. See [Chat through a relay](#relay).": "**Anrufe verbinden wieder**: Ein Anruf, der geklingelt hat, bleibt nicht mehr auf beiden Telefonen bei **Verbindet…**; jedes Telefon wartet jetzt auf seine eigenen Adressen, bevor es anruft oder annimmt. Siehe [Chat über ein Relay](#relay).",
  "**A phone beside you brings your messages**: with no internet, an Erevos phone beside yours that has it, and carries for others, takes what waits for you on your relay and hands it over nearby, once you say yes to that phone. It learns your queue there, never what your messages say, and your phone moves to a new queue once it has internet again. Yours does the same for others while **Carry messages for others** is on, as it now is from the start. Never through Tor, and from another relay only once you say yes, warned it sees your address. See [Chat with a nearby phone](#nearby).": "**Ein Telefon neben dir holt deine Nachrichten**: Ohne Internet holt ein Erevos-Telefon neben deinem, das Internet hat und für andere mitnimmt, was auf deinem Relay für dich wartet, und gibt es dir in der Nähe, sobald du zu diesem Telefon Ja sagst. Es erfährt deine Warteschlange dort, nie, was deine Nachrichten sagen, und dein Telefon wechselt zu einer neuen, sobald es wieder Internet hat. Deins tut dasselbe für andere, solange **Nachrichten für andere mitnehmen** an ist, wie jetzt von Anfang an. Nie über Tor, und von einem anderen Relay nur, wenn du Ja sagst, gewarnt, dass es deine Adresse sieht. Siehe [Chat with a nearby phone](#nearby).",
  "**A Matrix chat read elsewhere is read here too**: an encrypted Matrix chat you read, or answered, in Element or on another device of yours no longer keeps its count of new messages here. See [Matrix](#matrix).": "**Ein anderswo gelesener Matrix-Chat ist auch hier gelesen**: ein verschlüsselter Matrix-Chat, den du in Element oder auf einem anderen deiner Geräte gelesen oder beantwortet hast, behält hier nicht mehr seine Zahl neuer Nachrichten. Siehe [Matrix](#matrix).",
  "**Matrix rooms with very long messages open**: a message with a very long run of names, dots or dashes, as some public Matrix rooms have, no longer closes Erevos+ as its chat shows it.":
    "**Matrix-Räume mit sehr langen Nachrichten öffnen sich**: Eine Nachricht mit einer sehr langen Folge von Namen, Punkten oder Bindestrichen, wie sie manche öffentlichen Matrix-Räume haben, schließt Erevos+ nicht mehr, wenn ihr Chat sie zeigt.",
  "**Messenger chats you read stay read**: a Messenger chat you marked read, or wrote in, no longer comes back as unread when Messenger sends it again, after Erevos+ reconnects or starts.":
    "**Gelesene Messenger-Chats bleiben gelesen**: Ein Messenger-Chat, den du als gelesen markiert oder in dem du geschrieben hast, ist nicht mehr wieder ungelesen, wenn Messenger ihn erneut sendet, nachdem Erevos+ sich neu verbindet oder startet.",
  "**Chats stay where you read**: in Telegram, Matrix, XMPP and Nostr chats, the chat no longer moves by itself to other messages as older ones load above it; it stays at the last message, or where you were reading.":
    "**Chats bleiben, wo du liest**: In Telegram-, Matrix-, XMPP- und Nostr-Chats springt der Chat nicht mehr von selbst zu anderen Nachrichten, während ältere darüber geladen werden; er bleibt bei der letzten Nachricht oder dort, wo du gelesen hast.",
  "**Erevos+ says its own name, with an icon of its own**: the app and its guide now say Erevos+ everywhere, and its icon is Erevos's mark on a purple tile. Where it speaks of the plain Erevos, it still says Erevos.":
    "**Erevos+ sagt seinen eigenen Namen, mit einem eigenen Symbol**: Die App und ihre Anleitung sagen jetzt überall Erevos+, und ihr Symbol ist das Zeichen von Erevos auf einer violetten Kachel. Wo es um das einfache Erevos geht, steht weiter Erevos.",
  "**Signal: one chat for each person, with their name**: in Erevos+, a Signal chat shows the person's name, what you send from the phone Erevos+ is linked to shows in the chat of the one you sent it to, and someone who first wrote to your phone number keeps one chat with you on their phone too.":
    "**Signal: ein Chat für jede Person, mit ihrem Namen**: In Erevos+ zeigt ein Signal-Chat den Namen der Person, was du vom Handy sendest, mit dem Erevos+ verknüpft ist, erscheint im Chat mit der Person, an die du es geschickt hast, und wer dir zuerst an deine Telefonnummer geschrieben hat, behält auch auf seinem Handy einen einzigen Chat mit dir.",
  "**A message's menu always opens**: holding a message, in a chat or a group, opens its menu every time; before, after you had been in another app, it could stop opening until Erevos was closed and opened again.": "**Das Menü einer Nachricht öffnet sich immer**: Wenn du eine Nachricht gedrückt hältst, im Chat oder in einer Gruppe, öffnet sich ihr Menü jedes Mal; vorher konnte es, nachdem du in einer anderen App warst, nicht mehr aufgehen, bis Erevos geschlossen und wieder geöffnet wurde.",
  "**New chat, made anew**: your QR code is on New chat as soon as it opens, with **Scan theirs** and **Share** under it; the field at the top finds a contact by name, or adds someone whose link you paste; and **No Erevos yet?** makes an invite, showing again one no one took yet instead of making another. On a new phone with no relay, New chat starts with **Start with an invite**. The small QR code is new each time and good once: the first to scan it is a contact at once, and anyone after, or with the link you share, writes a message request first. See [Chat through a relay](#relay).": "**Neuer Chat, ganz neu**: Dein QR-Code steht auf Neuer Chat, sobald er sich öffnet, mit **Ihren scannen** und **Teilen** darunter; das Feld oben findet einen Kontakt nach Namen oder fügt jemanden hinzu, dessen Link du einfügst; und **Noch kein Erevos?** erstellt eine Einladung und zeigt eine noch nicht genommene wieder, statt eine weitere zu erstellen. Auf einem neuen Handy ohne Relay beginnt Neuer Chat mit **Mit einer Einladung beginnen**. Der kleine QR-Code ist jedes Mal neu und gilt einmal: Wer ihn zuerst scannt, ist sofort ein Kontakt, und wer danach kommt oder den geteilten Link hat, schreibt zuerst eine Nachrichtenanfrage. Siehe [Chat through a relay](#relay).",
  "What's new": 'Was ist neu',
  'What each version changed': 'Was jede Version geändert hat',
  'What each version of Erevos changed, the newest first.': 'Was jede Version von Erevos geändert hat, die neueste zuerst.',
  'Not out yet': 'Noch nicht erschienen',
  'This version': 'Diese Version',
  'For you': 'Für dich',
  'Under the hood': 'Unter der Haube',
  "**Chats you have read stay read, on every network**: in Erevos+, Messenger, Signal, Session, Telegram, Matrix, XMPP and Nostr chats you have read no longer notify you again of messages already read, after a restart, a reconnect or when a chat opens. Signal's reads go both ways with the phone it is linked to, and a Nostr chat you answer from another app is read here too.": "**Gelesene Chats bleiben gelesen, in jedem Netz**: in Erevos+ melden sich Chats auf Messenger, Signal, Session, Telegram, Matrix, XMPP und Nostr, die du gelesen hast, nicht mehr mit schon gelesenen Nachrichten, nach einem Neustart, einer neuen Verbindung oder beim Öffnen eines Chats. Gelesenes bei Signal geht in beide Richtungen mit dem Telefon, mit dem es verknüpft ist, und ein Nostr-Chat, auf den du in einer anderen App antwortest, ist auch hier gelesen.",
  "**The guide tells of Messenger, Signal and Session**: in Erevos+, the user guide has a section for each, on signing in, chats, groups, calls, notifications, Tor and signing out. See [Messenger](#messenger), [Signal](#signal) and [Session](#session).": "**Die Anleitung erklärt Messenger, Signal und Session**: in Erevos+ hat die Anleitung für jedes einen Abschnitt, zu Anmelden, Chats, Gruppen, Anrufen, Benachrichtigungen, Tor und Abmelden. Siehe [Messenger](#messenger), [Signal](#signal) und [Session](#session).",
  // Not out yet.
  "**New chat asks whether they have Erevos**: over your QR code on **New chat**, choose **Has Erevos already** or **New to Erevos**. The first is your QR code as before, and says that it works only when both phones have a relay; the second shows an invite, which brings in someone new, or someone whose phone has no relay. New chat remembers your choice. See [Chat through a relay](#relay).":
    "**Neuer Chat fragt, ob sie Erevos haben**: Wähle über deinem QR-Code auf **Neuer Chat** **Hat Erevos schon** oder **Neu bei Erevos**. Das Erste ist dein QR-Code wie bisher und sagt, dass er nur klappt, wenn beide Telefone ein Relay haben; das Zweite zeigt eine Einladung, die jemand Neues hereinholt oder jemanden, dessen Telefon kein Relay hat. Neuer Chat merkt sich deine Wahl. Siehe [Chat über ein Relay](#relay).",
  "**The keypad lists the contacts it finds, and shows its letters**: on the Phone's **Keypad**, the contacts what you type finds are listed in the room over the number, all of them, not one at a time; and each key shows its letters in the app's language, ΑΒΓ in Greek, ABC in the others. See [Phone](#phone).":
    "**Die Wähltasten listen die gefundenen Kontakte und zeigen ihre Buchstaben**: Auf den **Wähltasten** des Telefons stehen die Kontakte, die deine Eingabe findet, in einer Liste im Platz über der Nummer, alle auf einmal statt einzeln; und jede Taste zeigt ihre Buchstaben in der Sprache der App, ΑΒΓ auf Griechisch, ABC in den anderen. Siehe [Telefon](#phone).",
  "**A phone beside you no longer slows Erevos**: with another Erevos phone near you on the same Wi-Fi, Erevos no longer links to it over Wi-Fi Aware too, which took your phone's Wi-Fi away for moments and slowed your messages and the relay, as if the other phone were far away; and a link to a phone nearby that stopped carrying anything is let go at once, not used on. See [Chat with a nearby phone](#nearby).":
    "**Ein Telefon neben dir bremst Erevos nicht mehr**: Ist ein anderes Telefon mit Erevos im selben WLAN in deiner Nähe, verbindet sich Erevos nicht mehr zusätzlich über Wi-Fi Aware mit ihm, was dem WLAN deines Telefons immer wieder kurz die Verbindung nahm und deine Nachrichten und das Relay bremste, als wäre das andere Telefon weit weg; und eine Verbindung zu einem Telefon in der Nähe, über die nichts mehr ankommt, wird sofort aufgegeben statt weiter genutzt. Siehe [Chat mit einem Telefon in der Nähe](#nearby).",
  "**Calls start sooner and sound steadier**: a call through the call relay no longer waits up to 5 seconds on each phone for every way to the relay, only for the first that works; while it goes on, Erevos looks for phones nearby less often, which took the phone's Wi-Fi away for moments and made gaps in the sound; and in a video call, their picture is no longer put aside when their sound came apart from it. See [Chat through a relay](#relay).":
    "**Anrufe beginnen schneller und klingen stabiler**: Ein Anruf über das Anruf-Relay wartet nicht mehr bis zu 5 Sekunden auf jedem Telefon auf jeden Weg zum Relay, nur auf den ersten, der geht; während er läuft, sucht Erevos seltener nach Telefonen in der Nähe, was dem Telefon kurz das WLAN nahm und Lücken im Ton machte; und in einem Videoanruf wird ihr Bild nicht mehr beiseitegelegt, wenn ihr Ton getrennt davon kam. Siehe [Chat through a relay](#relay).",
  "**Contacts as you dial**: on the Phone's **Keypad**, a contact whose number holds the digits you type, or whose name starts with them on the keys' letters (2 for ABC and ΑΒΓ), shows over the keys: tap it to call. See [Phone](#phone).":
    "**Kontakte beim Wählen**: Auf den **Wähltasten** des Telefons zeigt sich über den Tasten ein Kontakt, dessen Nummer die getippten Ziffern enthält oder dessen Name mit ihnen auf den Buchstaben der Tasten beginnt (2 für ABC und ΑΒΓ): Tippe ihn an, um anzurufen. Siehe [Telefon](#phone).",
  "**Chats open at once**: a chat no longer waits, showing your contact as encrypted, for Erevos to finish what it was doing with the relay in the background; it is ready to use as it opens, and holding a message opens its menu, at most a moment later while Erevos says it is still reading what came. See [Chat through a relay](#relay).":
    "**Chats öffnen sofort**: Ein Chat wartet nicht mehr, während er deinen Kontakt als verschlüsselt zeigt, bis Erevos fertig ist mit dem, was es im Hintergrund mit dem Relay tat; er ist beim Öffnen bereit, und langes Drücken auf eine Nachricht öffnet ihr Menü, höchstens einen Moment später, während Erevos sagt, dass es noch liest, was gekommen ist. Siehe [Chat über ein Relay](#relay).",
  "**Pair with a code with no relay yet**: on a phone with no relay yet, **New chat** now has **Pair with a code** too, under your QR code, and opens straight on **Start with an invite** without first showing the screen of a phone with a relay. See [Chat through a relay](#relay).":
    "**Mit einem Code koppeln, noch ohne Relay**: Auf einem Telefon ohne Relay hat **Neuer Chat** jetzt auch **Mit einem Code koppeln**, unter deinem QR-Code, und öffnet gleich mit **Mit einer Einladung beginnen**, ohne zuerst den Bildschirm eines Telefons mit Relay zu zeigen. Siehe [Chat through a relay](#relay).",
  "**The Public tab says why it shows no Nostr post**: whether the list of people you follow was not found, or they were found but no relay sent their posts, or their posts came but could not be shown, and how each relay answered. Before, it said only that no public posts were found. See [Chats with other Nostr apps](#nostr-chats).":
    "**Der Tab Öffentlich sagt, warum er keinen Nostr-Beitrag zeigt**: ob die Liste der Leute, denen du folgst, nicht gefunden wurde, ob sie gefunden wurden, aber kein Relay ihre Beiträge gesendet hat, oder ob ihre Beiträge kamen, sich aber nicht anzeigen ließen, und wie jedes Relay geantwortet hat. Vorher hieß es nur, dass keine öffentlichen Beiträge gefunden wurden. Siehe [Chats mit anderen Nostr-Apps](#nostr-chats).",
  "**A new computer links to the end**: a computer with no relay before linking now takes the phone's answer at once, so linking with the small code finishes by itself, and with the full code **They match** shows. Before, the phone waited for **They match** while the computer showed nothing more until Erevos started again. See [Linked devices](#devices).":
    "**Ein neuer Computer wird bis zum Ende verknüpft**: Ein Computer, der vor dem Verknüpfen kein Relay hatte, nimmt die Antwort des Telefons jetzt sofort an. So wird das Verknüpfen mit dem kleinen Code von selbst fertig, und mit dem vollständigen Code erscheint **Stimmen überein**. Vorher wartete das Telefon auf **Stimmen überein**, während der Computer nichts mehr zeigte, bis Erevos neu startete. Siehe [Verknüpfte Geräte](#devices).",
  "**Sharing into Erevos reaches every service**: **Send to** now lists the chats of your Matrix, XMPP and Nostr accounts too, beside Erevos chats, groups and SMS conversations. A photo or file shared from another app no longer goes missing when Erevos locks as it opens: after the password, **Send to** shows it again, where before it said that nothing came to send. See [Chat through a relay](#relay).":
    "**Teilen in Erevos erreicht jeden Dienst**: **Senden an** listet jetzt auch die Chats deiner Konten bei Matrix, XMPP und Nostr, neben Erevos-Chats, Gruppen und SMS-Unterhaltungen. Ein Foto oder eine Datei, die aus einer anderen App geteilt wird, geht nicht mehr verloren, wenn Erevos beim Öffnen sperrt: Nach dem Passwort zeigt **Senden an** sie wieder, wo es vorher sagte, dass nichts zum Senden kam. Siehe [Chat über ein Relay](#relay).",
  "**Search, media, days and export in Matrix, XMPP, Nostr and SMS**: these chats now have **Search in this chat**, **Media, links and files**, **Go to a day** and **Export chat**, as Erevos chats do, over what your phone keeps of them; an SMS conversation has them under **⋮**. Nothing you search for leaves your phone. See [Getting started](#start).":
    "**Suche, Medien, Tage und Export bei Matrix, XMPP, Nostr und SMS**: Diese Chats haben jetzt **In diesem Chat suchen**, **Medien, Links und Dateien**, **Zu einem Tag** und **Chat exportieren**, wie Erevos-Chats, über das, was dein Telefon von ihnen behält; eine SMS-Unterhaltung hat sie unter **⋮**. Nichts, wonach du suchst, verlässt dein Telefon. Siehe [Erste Schritte](#start).",
  "**Styles, cards and video in Matrix, XMPP and Nostr**: these chats now show bold, italic and the other marks for how words look, with tappable links, and send a contact card, a video without where it was filmed, or a photo from the camera at the quality you choose. In groups, @ offers the members; Nostr chats send your location, and a message you forward is marked as forwarded on your phone. See [Matrix](#matrix).":
    "**Stile, Karten und Video bei Matrix, XMPP und Nostr**: Diese Chats zeigen jetzt fett, kursiv und die anderen Zeichen dafür, wie Wörter aussehen, mit antippbaren Links, und senden eine Kontaktkarte, ein Video ohne den Ort, an dem es gefilmt wurde, oder ein Foto von der Kamera in der Qualität, die du wählst. In Gruppen zeigt @ die Mitglieder; Nostr-Chats senden deinen Standort, und eine Nachricht, die du weiterleitest, ist auf deinem Telefon als weitergeleitet markiert. Siehe [Matrix](#matrix).",
  "**Starred messages in every chat**: star a message in Matrix, XMPP, Nostr and SMS too, and find it again under **Starred messages**; save a photo, video, voice message or file that came there to the Collection, and keep a sticker or photo that came as one of your stickers. See [Chat through a relay](#relay).":
    "**Markierte Nachrichten in jedem Chat**: Markiere eine Nachricht auch bei Matrix, XMPP, Nostr und SMS mit einem Stern und finde sie unter **Markierte Nachrichten** wieder; speichere ein Foto, Video, eine Sprachnachricht oder Datei, die dort kam, in der Sammlung, und behalte einen Sticker oder ein Foto, das kam, als einen deiner Sticker. Siehe [Chat über ein Relay](#relay).",
  "**Pin and archive any chat**: hold any chat down on the home screen (an Erevos contact or group, Matrix, XMPP or Nostr) to **Pin to the top**, **Archive** or, on Android, mute it, as SMS conversations already could. Archived chats wait under **Archived** until a new message comes from them. Matrix favourites show pinned, and low-priority rooms come last. A Matrix row shows ✓✓✓ once everyone has read yours. Matrix rooms, XMPP contacts and group MMS can take a name of your own. See [Getting started](#start).":
    "**Jeden Chat anheften und archivieren**: Halte auf dem Startbildschirm einen beliebigen Chat gedrückt (einen Erevos-Kontakt oder eine Gruppe, Matrix, XMPP oder Nostr), um ihn **Oben anheften**, **Archivieren** oder, auf Android, stummzuschalten, wie es SMS-Unterhaltungen schon konnten. Archivierte Chats warten unter **Archiviert**, bis eine neue Nachricht von dort kommt. Matrix-Favoriten erscheinen angeheftet, und Räume mit niedriger Priorität kommen zuletzt. Eine Matrix-Zeile zeigt ✓✓✓, sobald alle deine gelesen haben. Matrix-Räume, XMPP-Kontakte und Gruppen-MMS können einen eigenen Namen bekommen. Siehe [Erste Schritte](#start).",
  "**Drafts, Send later and Remind me on Matrix, XMPP and Nostr**: what you type in a chat and do not send stays as its draft, also after Erevos closes, and shows on the chat's row. Hold **Send** down to send a message later from this phone. A Matrix or XMPP message that did not go has **Send again** in its menu, and **Remind me** on a message of any of these chats, SMS too, puts it in Chat with myself with a reminder. See [Matrix](#matrix).":
    "**Entwürfe, Später senden und Erinnern bei Matrix, XMPP und Nostr**: Was du in einem Chat tippst und nicht sendest, bleibt als sein Entwurf, auch nachdem Erevos geschlossen wird, und zeigt sich in der Zeile des Chats. Halte **Senden** gedrückt, um eine Nachricht später von diesem Telefon zu senden. Eine Matrix- oder XMPP-Nachricht, die nicht ging, hat **Erneut senden** in ihrem Menü, und **Erinnern** an einer Nachricht dieser Chats, auch bei SMS, legt sie mit einer Erinnerung in Chat mit mir selbst. Siehe [Matrix](#matrix).",
  "**A PIN and screenshots for Matrix, XMPP, Nostr and SMS chats**: lock a chat on Matrix, XMPP or Nostr, or an SMS conversation, with a PIN of its own and block its screenshots, as an Erevos chat; an SMS conversation can also have its own look, be muted, or have a sound of its own. See [Hidden chats](#hidden).":
    "**Eine PIN und Bildschirmfotos für Matrix-, XMPP-, Nostr- und SMS-Chats**: Sperre einen Chat bei Matrix, XMPP oder Nostr oder eine SMS-Unterhaltung mit einer eigenen PIN und blockiere seine Bildschirmfotos, wie bei einem Erevos-Chat; eine SMS-Unterhaltung kann außerdem ihr eigenes Aussehen haben, stummgeschaltet sein oder einen eigenen Ton haben. Siehe [Versteckte Chats](#hidden).",
  "**Chat rules on Matrix, XMPP, Nostr and SMS**: disappearing messages, a timer for the chat or **Disappear** for one message, each chat saying what the other side keeps; **Block** on Matrix and Nostr, with a list of whom you blocked on each service's screen; **Delete** asks **This phone** or **Everyone**; on XMPP, **Appear offline** to one contact; and **Check in person** by QR code on XMPP and Nostr. See [Matrix](#matrix).":
    "**Chat-Regeln bei Matrix, XMPP, Nostr und SMS**: verschwindende Nachrichten, eine Zeit für den Chat oder **Verschwinden** für eine Nachricht, wobei jeder Chat sagt, was die andere Seite behält; **Blockieren** bei Matrix und Nostr, mit einer Liste der Blockierten auf dem Bildschirm jedes Dienstes; **Löschen** fragt **Dieses Telefon** oder **Für alle**; bei XMPP **Offline erscheinen** für einen Kontakt; und **Persönlich prüfen** per QR-Code bei XMPP und Nostr. Siehe [Matrix](#matrix).",
  "**Choose where a call's sound goes**: with a Bluetooth or wired headset connected, **Speaker** in a call becomes **Audio output**, to choose the phone, the speaker or the headset, a Bluetooth one by its own name. A headset connected as a call starts, or during it, takes the sound, as in a phone call. On Android. See [Chat through a relay](#relay).":
    "**Wähle, wohin der Ton eines Anrufs geht**: Ist ein Bluetooth- oder Kabel-Headset verbunden, wird **Lautsprecher** im Anruf zu **Audioausgabe**, um das Telefon, den Lautsprecher oder das Headset zu wählen, ein Bluetooth-Headset mit seinem eigenen Namen. Ein Headset, das beim Start eines Anrufs oder währenddessen verbunden wird, übernimmt den Ton, wie bei einem Telefonanruf. Auf Android. Siehe [Chat über ein Relay](#relay).",
  "**Nothing goes through Tor unless you turn it on**: on Android, **Automatically from your relay** under **Home relay** is now off in a new space, so a space no longer takes its relay's paired relay as a home relay through Tor by itself; turn it on there if you want it. Turning it off now also lets go of the home relay it took, so Tor does not run for it. See [Home relay](#home-relay).":
    "**Nichts geht über Tor, solange du es nicht einschaltest**: Auf Android ist **Automatisch von deinem Relay** unter **Heim-Relay** in einem neuen Bereich jetzt aus, also nimmt ein Bereich das gepaarte Relay seines Relays nicht mehr von selbst über Tor als Heim-Relay; schalte es dort ein, wenn du es willst. Ausgeschaltet lässt es jetzt auch das Heim-Relay los, das es genommen hat, sodass Tor dafür nicht läuft. Siehe [Heim-Relay](#home-relay).",
  "**Your relays first, Nostr only after them**: a text to a contact who reads on Nostr now goes through your relay, then their home relays, then your home relay, and through the public Nostr relays only when none of them took it. Before, it went to the Nostr relays first and through your relay only when they were slow or did not take it. See [Through Nostr](#nostr).":
    "**Zuerst deine Relays, Nostr erst danach**: Ein Text an einen Kontakt, der auf Nostr liest, geht jetzt über dein Relay, dann über seine Heim-Relays, dann über dein Heim-Relay und über die öffentlichen Nostr-Relays nur, wenn keins davon ihn angenommen hat. Vorher ging er zuerst an die Nostr-Relays und über dein Relay nur, wenn diese langsam waren oder ihn nicht annahmen. Siehe [Über Nostr](#nostr).",
  "**One chat only through Tor**: on Android, **Through Tor** in an Erevos chat's **Details** sends that chat's messages and files only through Tor, on circuits of its own, whatever the space's Tor setting. It is off unless you turn it on, and calls do not go through Tor. See [Through Tor](#tor).":
    "**Ein Chat nur über Tor**: Auf Android schickt **Über Tor** in den **Details** eines Erevos-Chats die Nachrichten und Dateien dieses Chats nur über Tor, auf eigenen Verbindungen, egal was die Tor-Einstellung des Bereichs sagt. Es ist aus, solange du es nicht einschaltest, und Anrufe gehen nicht über Tor. Siehe [Über Tor](#tor).",
  "**One chat only through Tor reaches Nostr too**: a chat with **Through Tor** on in its **Details** now sends and reads its Nostr texts only through Tor, and its photos and files on Nostr file servers too, even when the space's Tor is **Nothing**; Tor is started for it, and what goes waits for it. Until your contact first writes to the chat's own queue, their first messages come to the space's own queue, which is read the space's way. Before, with the space's Tor off, such a chat's texts could reach the public Nostr relays straight, and they saw the phone's internet address. See [Through Tor](#tor).":
    "**Ein Chat nur über Tor erreicht auch Nostr**: Ein Chat mit eingeschaltetem **Über Tor** in seinen **Details** sendet und liest seine Nostr-Texte jetzt nur über Tor, und seine Fotos und Dateien auf Nostr-Dateiservern auch, selbst wenn Tor des Bereichs auf **Nichts** steht; Tor wird dafür gestartet, und was gesendet wird, wartet darauf. Bis dein Kontakt zum ersten Mal in die eigene Warteschlange des Chats schreibt, kommen seine ersten Nachrichten in die Warteschlange des Bereichs, die so gelesen wird, wie der Bereich es sagt. Vorher konnten die Texte eines solchen Chats bei ausgeschaltetem Tor des Bereichs direkt zu den öffentlichen Nostr-Relays gehen, und sie sahen die Internetadresse des Telefons. Siehe [Über Tor](#tor).",
  "**Through Tor on your linked devices too**: a chat's **Through Tor** switch, set in its **Details**, now reaches your linked devices (your computer, the web app and Jolla) and back: switched on or off on any of them, it is switched everywhere. On a linked device that chat's messages, files and send-later messages then go only through Tor too, on the chat's own circuits, never straight; so do the copies that go to your contact's other devices. The web app has no Tor: there a chat with the switch on sends nothing while it is on, and the switch is shown so it can be turned off. A device on an older version never turns it off anywhere; it learns a change made elsewhere at that contact's next change. Before, it was only on the phone where you set it. See [Through Tor](#tor).":
    "**Über Tor auch auf deinen verknüpften Geräten**: Der Schalter **Über Tor** eines Chats, gesetzt in seinen **Details**, erreicht jetzt deine verknüpften Geräte (deinen Computer, die Web-App und Jolla) und zurück: Auf einem davon ein- oder ausgeschaltet, ist er überall ein- oder ausgeschaltet. Auf einem verknüpften Gerät gehen die Nachrichten, Dateien und später gesendeten Nachrichten dieses Chats dann auch nur über Tor, auf den eigenen Verbindungen des Chats, nie direkt; ebenso die Kopien an die anderen Geräte deines Kontakts. Die Web-App hat kein Tor: Dort sendet ein Chat mit eingeschaltetem Schalter nichts, solange er eingeschaltet ist, und der Schalter wird angezeigt, damit man ihn ausschalten kann. Ein Gerät mit älterer Version schaltet ihn nirgends aus; es erfährt eine anderswo gemachte Änderung bei der nächsten Änderung dieses Kontakts. Vorher galt er nur auf dem Telefon, auf dem du ihn gesetzt hast. Siehe [Über Tor](#tor).",
  "**Nostr has its own Tor switch**: the **Nostr** screen now has **Nostr through Tor**, **On** or **Off**, off unless you turn it on. **On**, Erevos reaches the Nostr relays and the Nostr file servers only through Tor, and starts Tor for it even when the space's Tor is **Nothing**; a text that goes there waits while Tor starts. It only adds Tor: with the space's Tor on, or for a chat set to **Through Tor**, Nostr goes through Tor whatever it says. Before, Nostr only followed the space's Tor setting, and the screen only said whether it was on. See [Through Nostr](#nostr).":
    "**Nostr hat einen eigenen Tor-Schalter**: Der Bildschirm **Nostr** hat jetzt **Nostr über Tor**, **An** oder **Aus**, aus, solange du es nicht einschaltest. **An** erreicht Erevos die Nostr-Relays und die Nostr-Dateiserver nur über Tor und startet Tor dafür, auch wenn Tor des Bereichs auf **Nichts** steht; ein Text, der dorthin geht, wartet, während Tor startet. Es fügt nur Tor hinzu: Ist Tor des Bereichs an, oder bei einem Chat mit **Über Tor**, geht Nostr über Tor, was es auch sagt. Vorher folgte Nostr nur der Tor-Einstellung des Bereichs, und der Bildschirm sagte nur, ob sie an war. Siehe [Über Nostr](#nostr).",
  "**Erevos warns before your internet address can be seen**: once before the first message, voice message or file in an Erevos chat that can go without Tor, with **Through Tor for this chat** to fix it or **Go on**; before the first message in an Erevos group that can go without Tor; before a call, as calls never go through Tor, unless the contact is nearby on the same network; before fetching a file from a server your contact chose; and in every **Open this link?** question, where the site sees the address. Each has a **Guide** button. Before, Erevos did not say it. See [Who sees your internet address](#ip).":
    "**Erevos warnt, bevor deine Internetadresse gesehen werden kann**: einmal vor der ersten Nachricht, Sprachnachricht oder Datei in einem Erevos-Chat, die ohne Tor gehen kann, mit **Über Tor für diesen Chat** zum Beheben oder **Weiter**; vor der ersten Nachricht in einer Erevos-Gruppe, die ohne Tor gehen kann; vor einem Anruf, denn Anrufe gehen nie über Tor, außer der Kontakt ist im selben Netz in der Nähe; vor dem Holen einer Datei von einem Server, den dein Kontakt gewählt hat; und in jeder Frage **Diesen Link öffnen?**, wo die Seite die Adresse sieht. Jede hat einen Knopf **Anleitung**. Vorher sagte Erevos das nicht. Siehe [Wer deine Internetadresse sieht](#ip).",
  "**A Tor switch of their own**: backups to a server, the Collection's server copy, radio and TV lists, link previews and updates each have a **Through Tor** switch in their own screen, off unless you turn it on. On, that goes only through Tor, whatever the space's Tor setting, and waits while Tor starts; nothing goes straight. Off, it goes as before. It only adds Tor. For updates, the switch makes the daily new-version notice and **Check for updates** ask the web app's server instead of GitHub; a new version is told, but it does not download through Tor: to install it, turn the switch off for a moment. Playing a radio station or a TV channel always goes straight. Before, backups, the Collection and radio and TV followed only the space's Tor setting, and link previews and updates never went through Tor. See [Who sees your internet address](#ip).":
    "**Ein eigener Tor-Schalter**: Backups auf einen Server, die Serverkopie der Sammlung, Radio- und TV-Listen, Linkvorschauen und Updates haben je einen Schalter **Über Tor** in ihrem eigenen Bildschirm, aus, solange du ihn nicht einschaltest. An, geht das nur über Tor, was auch die Tor-Einstellung des Bereichs sagt, und wartet, während Tor startet; nichts geht direkt. Aus, geht es wie bisher. Es fügt nur Tor hinzu. Bei Updates lässt der Schalter die tägliche Mitteilung über eine neue Version und **Nach Updates suchen** den Server der Web-App fragen statt GitHub; eine neue Version wird gemeldet, aber nicht über Tor heruntergeladen: Schalte ihn zum Installieren kurz aus. Einen Radiosender oder TV-Kanal zu spielen geht immer direkt. Vorher folgten Backups, die Sammlung und Radio und TV nur der Tor-Einstellung des Bereichs, und Linkvorschauen und Updates gingen nie über Tor. Siehe [Wer deine Internetadresse sieht](#ip).",
  "**Bare web addresses open too**: t.me/name, example.org/page and the like are now tappable in every chat, as in Telegram and Signal, and show whole before they open; e-mail addresses and file names are not. See [Chat through a relay](#relay).":
    "**Auch bloße Webadressen öffnen sich**: t.me/name, example.org/page und Ähnliches sind jetzt in jedem Chat antippbar, wie in Telegram und Signal, und werden vollständig gezeigt, bevor sie sich öffnen; E-Mail-Adressen und Dateinamen nicht. Siehe [Chat über ein Relay](#relay).",
  "**Read marks no longer go missing**: when you read a message and put the phone away at once, the other person still learns that you read it, at Erevos's next look, also after Erevos was closed. Before, it could stay at ✓✓ for them for good.": "**Lesebestätigungen gehen nicht mehr verloren**: Liest du eine Nachricht und legst das Telefon gleich weg, erfährt die andere Person trotzdem, dass du sie gelesen hast, beim nächsten Blick von Erevos, auch nachdem Erevos geschlossen wurde. Vorher konnte sie für sie für immer bei ✓✓ bleiben.",
  "**Backups are checked**: after each automatic backup Erevos reads it back from the folder, opens it with its password, makes sure every part it names is there, of its size, and reads two of them through. On a server it looks at the listing only. **Check now** under Backups also downloads the server’s newest backup and ten of its parts; a part missing or damaged shows in red. **Full check of the folder** compares every part there with its SHA-256, on the phone. See [Backups](#backup).":
    "**Backups werden geprüft**: Nach jedem automatischen Backup liest Erevos es aus dem Ordner zurück, öffnet es mit seinem Passwort, stellt sicher, dass jeder Teil, den es nennt, da ist, in seiner Größe, und liest zwei davon ganz. Auf einem Server sieht es nur die Liste an. **Jetzt prüfen** unter Backups lädt außerdem das neueste Backup des Servers und zehn seiner Teile herunter; ein fehlender oder beschädigter Teil erscheint rot. **Ordner vollständig prüfen** vergleicht jeden Teil dort mit seinem SHA-256, auf dem Telefon. Siehe [Backups](#backup).",
  "**A new first start**: the first screen now says what you do not give, no phone number, email, user name or account, and asks for a name for your contacts, if you want one. After the modules comes a short screen for each, with how to begin with it and what Android should allow for it, **Allow all, one by one** among it; then the password lock and backups, then what is ready and what is missing. **I already have Erevos on another phone** goes straight to restoring a backup. See [Modules](#modules).":
    "**Ein neuer erster Start**: Der erste Bildschirm sagt jetzt, was du nicht hergibst, keine Telefonnummer, E-Mail, keinen Benutzernamen und kein Konto, und fragt nach einem Namen für deine Kontakte, wenn du einen möchtest. Nach den Modulen kommt für jedes ein kurzer Bildschirm, mit dem, wie du damit anfängst und was Android dafür erlauben soll, darunter **Alle erlauben, nacheinander**; dann die Passwortsperre und die Backups, dann was fertig ist und was fehlt. **Ich habe Erevos schon auf einem anderen Telefon** führt gleich zum Wiederherstellen eines Backups. Siehe [Module](#modules).",
  "**Leftovers**: photos and files that nothing names any more, as those of an import that stopped in its middle, can now be found and deleted, under Backups → **Leftovers**. Type the PIN of each of your hidden chats and the password of any other space, tap **Find leftovers**, and Erevos shows how much none of them names; **Delete them** deletes it once you say so. See [Backups](#backup).":
    "**Reste**: Fotos und Dateien, die nichts mehr nennt, etwa die eines mittendrin abgebrochenen Imports, lassen sich jetzt unter Backups → **Reste** finden und löschen. Gib die PIN jedes deiner versteckten Chats und das Passwort jedes anderen Bereichs ein, tippe auf **Reste suchen**, und Erevos zeigt, wie viel keiner davon nennt; **Sie löschen** löscht es, sobald du zustimmst. Siehe [Backups](#backup).",
  "**An import that stops leaves nothing behind**: when Erevos stops while it brings in the photos and files of a Telegram, WhatsApp or Viber export, as when Android closes it or the battery runs out, what it had written of them is deleted the next time it starts. Before, it stayed on the phone, and in every backup, for good. See [Imported chats](#import).":
    "**Ein abgebrochener Import hinterlässt nichts**: Hält Erevos an, während es die Fotos und Dateien eines Telegram-, WhatsApp- oder Viber-Exports übernimmt, etwa weil Android es schließt oder der Akku leer ist, wird beim nächsten Start gelöscht, was es davon schon geschrieben hatte. Vorher blieb es für immer auf dem Telefon und in jedem Backup. Siehe [Importierte Chats](#import).",
  // 7.0.0-rc.7
  "**What takes room**: Backups now have **What takes room**, which shows on Android how much room Erevos takes on the phone, by kind: the Collection with the chats' photos and files, voice messages, chat history, Tor, and what writes that did not end left over. Each automatic backup holds it all, so it tells why one is large. See [Backups](#backup).":
    "**Was Platz belegt**: Backups haben jetzt **Was Platz belegt**, das unter Android zeigt, wie viel Platz Erevos auf dem Telefon belegt, nach Art: die Sammlung mit den Fotos und Dateien der Chats, Sprachnachrichten, Chatverlauf, Tor und Reste unvollendeter Schreibvorgänge. Jedes automatische Backup enthält all das, so sieht man, warum eines groß ist. Siehe [Backups](#backup).",
  "**Backups to a server get there again**: a backup to your own server, such as a Nextcloud, no longer stops when the server misses one of its pieces for a moment, as when it closes for a few minutes at night. That piece goes again a little later and the backup carries on; before, it started over the next time, and a large backup could fail day after day. See [Backups](#backup).":
    '**Backups auf einen Server kommen wieder an**: Ein Backup auf deinen eigenen Server, etwa eine Nextcloud, bricht nicht mehr ab, wenn der Server eines seiner Teile kurz nicht annimmt, etwa wenn er nachts für ein paar Minuten schließt. Dieses Teil geht etwas später noch einmal, und das Backup läuft weiter; vorher fing es beim nächsten Mal von vorn an, und ein großes Backup konnte Tag für Tag scheitern. Siehe [Backups](#backup).',
  // 7.0.0-rc.6
  "**Photos and files from the Collection, straight from a chat**: **+** in a chat now has **Collection**, which opens the Collection of that chat's place, its photos and its other files. Tap what to send, then **Send**, and it goes in the chat. Before, **Photo** opened only the phone's own gallery. See [Collection](#collection).":
    "**Fotos und Dateien aus der Sammlung, direkt aus einem Chat**: **+** in einem Chat hat jetzt **Sammlung**, die die Sammlung des Ortes dieses Chats öffnet, mit ihren Fotos und anderen Dateien. Tippe an, was du senden willst, dann **Senden**, und es geht in den Chat. Vorher öffnete **Foto** nur die Galerie des Telefons. Siehe [Sammlung](#collection).",
  "**A chat opens at its last message again**: opened from the home screen or a notification, a chat could stop above its newest messages, often above the unread ones. Now it goes to its end at once, and once more as its messages come into view.":
    "**Ein Chat öffnet sich wieder bei seiner letzten Nachricht**: Vom Startbildschirm oder aus einer Benachrichtigung geöffnet, konnte ein Chat über seinen neuesten Nachrichten stehen bleiben, oft über den ungelesenen. Jetzt geht er sofort an sein Ende, und noch einmal, sobald seine Nachrichten zu sehen sind.",
  "**A new sign-in to a relay is no longer undone**: after you signed in to your relay again, a chat screen open from before could later write back the token from before, which the relay no longer lets in, and the relay then refused this phone. Now the new token is kept at once, and every chat screen open takes it. See [Chat through a relay](#relay).":
    "**Eine neue Anmeldung beim Relay wird nicht mehr rückgängig gemacht**: Nachdem du dich erneut bei deinem Relay angemeldet hattest, konnte ein schon vorher geöffneter Chat-Bildschirm später das alte Token zurückschreiben, das das Relay nicht mehr einlässt, und das Relay wies dieses Telefon dann ab. Jetzt wird das neue Token sofort gespeichert, und jeder offene Chat-Bildschirm übernimmt es. Siehe [Chat über ein Relay](#relay).",
  // 7.0.0-rc.5
  "**A message sent offline is no longer lost when you leave the chat**: what you sent while your chats were still opening, as they do for a while with no connection, was lost if you left the chat before it went. Now it waits, marked **Waiting**, and goes by itself once the relay or their phone nearby can take it, a voice message too. See [Chat through a relay](#relay).":
    "**Eine ohne Verbindung gesendete Nachricht geht nicht mehr verloren, wenn du den Chat verlässt**: Was du gesendet hast, während deine Chats noch geöffnet wurden, wie sie es ohne Verbindung eine Weile tun, ging verloren, wenn du den Chat verlassen hast, bevor es ging. Jetzt wartet es, als **Wartet** markiert, und geht von selbst, sobald das Relay oder das andere Telefon in der Nähe es annehmen kann, auch eine Sprachnachricht. Siehe [Chat über ein Relay](#relay).",
  // 7.0.0-rc.4
  "**No more freezing after a space opens**: while an automatic backup was made, the screen could stop answering for minutes. Now the backup's files are written, listed and deleted in their folder away from the screen, and its parts are checked natively, many times faster.":
    '**Kein Einfrieren mehr, wenn sich ein Bereich öffnet**: Während ein automatisches Backup gemacht wurde, konnte der Bildschirm minutenlang nicht mehr reagieren. Jetzt werden die Dateien des Backups in ihrem Ordner abseits des Bildschirms geschrieben, aufgelistet und gelöscht, und seine Teile werden nativ geprüft, um ein Vielfaches schneller.',
  // 7.0.0-rc.3
  "**Your SMS on your computer**: the phone's SMS can now show on this space's linked devices too, a computer, a browser or a tablet, end-to-end encrypted: read them there and answer, and the phone sends the answer. The latest 50 conversations go, each with its latest 50 messages; photos stay on the phone. Off until you turn it on, on the phone, under Settings → Phone and SMS → SMS → **On my linked devices too**. See [SMS](#sms).":
    "**Deine SMS auf dem Computer**: Die SMS des Telefons können jetzt auch auf den verknüpften Geräten dieses Bereichs erscheinen, einem Computer, einem Browser oder einem Tablet, Ende-zu-Ende-verschlüsselt: Lies sie dort und antworte, und das Telefon sendet die Antwort. Die letzten 50 Unterhaltungen gehen, jede mit ihren letzten 50 Nachrichten; Fotos bleiben auf dem Telefon. Aus, bis du es einschaltest, auf dem Telefon, unter Einstellungen → Telefon und SMS → SMS → **Auch auf meinen verknüpften Geräten**. Siehe [SMS](#sms).",
  "**TV in the Collection**: the Collection's new **TV** tab plays TV channels from IPTV lists (.m3u), by their link or from a file, or from iptv-org's public list of free channels, by country or whole, in their groups, with a search, on Android, on a computer and in a browser. There is no programme guide, logos show only if you turn them on, and a channel's name and link, or a radio station's, can be sent to a chat. See [Collection](#collection).":
    "**TV in der Sammlung**: der neue Tab **TV** der Sammlung spielt TV-Sender aus IPTV-Listen (.m3u), über ihren Link oder aus einer Datei, oder aus der öffentlichen Liste freier Sender von iptv-org, nach Land oder ganz, in ihren Gruppen, mit einer Suche, unter Android, auf dem Computer und im Browser. Einen Programmführer gibt es nicht, Logos erscheinen nur, wenn du sie einschaltest, und Name und Link eines Senders, oder eines Radiosenders, lassen sich an einen Chat senden. Siehe [Sammlung](#collection).",
  "**Radio that keeps playing**: when a station's server, or a proxy on the way, drops the stream, or the network goes for a moment, Erevos asks the station again by itself, a few seconds later, instead of stopping.":
    "**Radio, das weiterspielt**: Wenn der Server eines Senders oder ein Proxy dazwischen den Stream abbricht oder das Netz kurz weg ist, verbindet sich Erevos nach ein paar Sekunden von selbst neu, statt aufzuhören.",
  "**Radio playlists with many stations**: in the Collection's Radio, **Add a station** takes a playlist link (.m3u, .pls) that names many stations and adds each of them, and **Import a playlist file** adds the stations of a .m3u or .pls file from your device. Only stations with an https link are added, and Erevos says how many were left out.":
    "**Radio-Playlists mit vielen Sendern**: Im Radio der Sammlung nimmt **Sender hinzufügen** einen Playlist-Link (.m3u, .pls) mit vielen Sendern und fügt jeden davon hinzu, und **Playlist-Datei importieren** fügt die Sender einer .m3u- oder .pls-Datei von deinem Gerät hinzu. Nur Sender mit https-Link werden hinzugefügt, und Erevos sagt, wie viele ausgelassen wurden.",
  "**Block screenshots in a chat**: in a chat's details, **Block screenshots** keeps screenshots and screen recordings of it out on both phones, on Android, and either of you can turn it off again. Erevos on an iPhone, on a computer, in a browser or on Sailfish cannot block them, and says so. See [Chat through a relay](#relay).":
    "**Bildschirmfotos in einem Chat blockieren**: In den Details eines Chats hält **Bildschirmfotos blockieren** Bildschirmfotos und -aufnahmen davon auf beiden Telefonen fern, unter Android, und jeder von euch kann es wieder ausschalten. Erevos auf einem iPhone, auf einem Computer, im Browser oder unter Sailfish kann sie nicht blockieren und sagt es. Siehe [Chat über ein Relay](#relay).",
  "**Every chat in its own look**: groups, Chat with myself and chats on Matrix, XMPP and Nostr now have **Chat look** too, as a contact's chat had, for that chat only. See [Chat through a relay](#relay).":
    "**Jeder Chat mit eigenem Aussehen**: Gruppen, Chat mit mir selbst und Chats auf Matrix, XMPP und Nostr haben jetzt auch **Chat-Aussehen**, wie es der Chat eines Kontakts hatte, nur für diesen Chat. Siehe [Chat über ein Relay](#relay).",
  "**Letters and text size**: Settings → Appearance has **Letters** (the style's own, the phone's, serif or monospace) and the messages' **Text size**, for the whole app or, from **Chat look**, for one chat. See [Appearance](#appearance).":
    "**Schrift und Textgröße**: Einstellungen → Darstellung hat **Schrift** (die des Stils, die des Telefons, mit Serifen oder mit fester Breite) und die **Textgröße** der Nachrichten, für die ganze App oder, über **Chat-Aussehen**, für einen Chat. Siehe [Darstellung](#appearance).",
  "**Muting hidden Matrix, XMPP and Nostr chats**: a hidden place's own Matrix, XMPP and Nostr chats can now be muted, as hidden chats are, and then say nothing at all. See [Hidden chats](#hidden).":
    "**Versteckte Matrix-, XMPP- und Nostr-Chats stummschalten**: Die Chats der eigenen Matrix-, XMPP- und Nostr-Konten eines versteckten Ortes lassen sich jetzt stummschalten, wie versteckte Chats, und sagen dann gar nichts. Siehe [Versteckte Chats](#hidden).",
  "**Say when I open Erevos**: with **Last seen** on, opening Erevos now tells your contacts at once, without waiting for a message: only those you talked with in the last 30 days who show their own time too, each after a random wait of up to a minute, at most every 15 minutes. The relay can then tell when you open Erevos: turn it off under Settings → Privacy and security → Last seen, or in a chat's details. See [Chat through a relay](#relay).":
    "**Sagen, wenn ich Erevos öffne**: mit **Zuletzt online** an erfahren deine Kontakte jetzt sofort, wenn du Erevos öffnest, ohne auf eine Nachricht zu warten: nur die, mit denen du in den letzten 30 Tagen geschrieben hast und die ihre eigene Zeit auch zeigen, jeder nach einer zufälligen Wartezeit von bis zu einer Minute, höchstens alle 15 Minuten. Das Relay kann dann erkennen, wann du Erevos öffnest: schalte es unter Einstellungen → Datenschutz und Sicherheit → Zuletzt online aus, oder in den Details eines Chats. Siehe [Chat über ein Relay](#relay).",
  "**Moving to a new phone**: a new chapter of the guide takes you step by step from the old phone to the new one with one backup: what to get ready, what comes over, what to set again, and wiping the old one at the end. See [Moving to a new phone](#new-phone).":
    "**Auf ein neues Telefon umziehen**: Ein neues Kapitel der Anleitung führt dich Schritt für Schritt mit einem Backup vom alten Telefon auf das neue: was du vorbereitest, was mitkommt, was du neu einstellst und wie du am Ende das alte löschst. Siehe [Auf ein neues Telefon umziehen](#new-phone).",
  '**A lost phone**: if the phone a backup came from was lost or stolen and may still be on, **The old phone was lost** under Settings → Data and devices → Backups moves every space and its hidden chats to new relay queues, so that phone reads nothing more of yours there, and tells your contacts quietly. The contact links and QR codes you gave before work for 14 more days. See [Backups](#backup).':
    '**Ein verlorenes Telefon**: Wenn das Telefon, von dem ein Backup stammt, verloren ging oder gestohlen wurde und noch an sein kann, verschiebt **Das alte Telefon ist verloren** unter Einstellungen → Daten und Geräte → Backups jeden Bereich und seine versteckten Chats auf neue Relay-Warteschlangen, sodass dieses Telefon dort nichts mehr von dir liest, und sagt es deinen Kontakten leise. Die Kontaktlinks und QR-Codes, die du vorher gegeben hast, gelten noch 14 Tage. Siehe [Backups](#backup).',
  '**Restored chats go on by themselves**: after a backup is restored, a chat that went on after the backup was made starts a new conversation with the contact by itself, so you no longer give each other your links again, but with a contact on an older Erevos. See [Backups](#backup).':
    '**Wiederhergestellte Chats gehen von selbst weiter**: Nach dem Wiederherstellen eines Backups beginnt ein Chat, der nach dem Backup weiterging, von selbst eine neue Unterhaltung mit dem Kontakt, sodass ihr euch eure Links nicht mehr gegenseitig geben müsst, außer bei einem Kontakt mit einem älteren Erevos. Siehe [Backups](#backup).',
  '**Backups every 6 hours, and lighter**: automatic backups can now come every 6 hours too, made while Erevos is open and as it goes to the background. Each one writes and sends only the photos, files and voice messages that are new, and names again those of the backups before it: keep the whole backup folder together. See [Backups](#backup).':
    '**Backups alle 6 Stunden, und leichter**: Automatische Backups können jetzt auch alle 6 Stunden kommen, gemacht, solange Erevos offen ist und wenn es in den Hintergrund geht. Jedes schreibt und sendet nur die Fotos, Dateien und Sprachnachrichten, die neu sind, und nennt die der Backups davor wieder: Halte den ganzen Backup-Ordner zusammen. Siehe [Backups](#backup).',
  '**Linked devices after a restore**: the phone a backup was restored on can ask the computers and browsers the old phone had linked to link again: tap **Ask to link again** under Settings → Data and devices → Linked devices, then **Link again** on the device. It keeps its chats, with no code to scan. See [Backups](#backup).':
    '**Verknüpfte Geräte nach einer Wiederherstellung**: Das Telefon, auf dem ein Backup wiederhergestellt wurde, kann die Computer und Browser, die das alte Telefon verknüpft hatte, bitten, sich erneut zu verknüpfen: Tippe unter Einstellungen → Daten und Geräte → Verknüpfte Geräte auf **Um erneute Verknüpfung bitten**, dann auf dem Gerät auf **Erneut verknüpfen**. Es behält seine Chats, ohne Code zum Scannen. Siehe [Backups](#backup).',
  "**The phone's calls in backups**: on Android, **Put the calls in backups** under Backups adds the call history and Android's blocked numbers to your backups, and restoring adds back those the phone lacks. Off until you turn it on. See [Backups](#backup).":
    '**Die Anrufe des Telefons in Backups**: Auf Android fügt **Anrufe in Backups aufnehmen** unter Backups den Anrufverlauf und Androids gesperrte Nummern deinen Backups hinzu, und das Wiederherstellen fügt die zurück, die dem Telefon fehlen. Aus, bis du es einschaltest. Siehe [Backups](#backup).',
  "**Groups after a restore**: a member restored from a backup asks the group's admin to put it in again, which works while the group moved on only a little.":
    '**Gruppen nach einer Wiederherstellung**: Ein aus einem Backup wiederhergestelltes Mitglied bittet den Admin der Gruppe, es wieder aufzunehmen, was klappt, solange die Gruppe nur wenig weitergezogen ist.',
  "**The time of a message that waited**: a message that waited on the relay, as for a computer or for hidden chats that were closed, now shows when it was sent, not when it came. From an Erevos before this version it still shows when it came.":
    "**Die Zeit einer Nachricht, die gewartet hat**: Eine Nachricht, die auf dem Relay gewartet hat, etwa für einen Computer oder für geschlossene versteckte Chats, zeigt jetzt, wann sie gesendet wurde, nicht wann sie ankam. Von einem Erevos vor dieser Version zeigt sie weiterhin, wann sie ankam.",
  // 7.0.0-rc.2
  "**Find radio stations by name**: Add a station in the Collection's Radio tab searches Radio Browser, a free directory, sent only the words you type when you press Search. See [Collection](#collection).":
    "**Radiosender nach Namen finden**: Sender hinzufügen im Tab Radio der Sammlung sucht in Radio Browser, einem freien Verzeichnis, das nur die Wörter bekommt, die du tippst, wenn du Suchen drückst. Siehe [Sammlung](#collection).",
  "**Internet radio in the Collection**: a Radio tab with stations you add by their https link, kept encrypted with the Collection, played like the music, with the notice on the phone. The station sees your device's IP address. See [Collection](#collection).":
    "**Internetradio in der Sammlung**: ein Tab Radio mit Sendern, die du über ihren https-Link hinzufügst, verschlüsselt mit der Sammlung, gespielt wie die Musik, mit der Mitteilung auf dem Telefon. Der Sender sieht die IP-Adresse deines Geräts. Siehe [Sammlung](#collection).",
  "**Music and videos of any size in the desktop app's Collection**: they play and seek at once, read a piece at a time from their encrypted pieces, never held whole in memory. See [Collection](#collection).":
    "**Musik und Videos in jeder Größe in der Sammlung der Desktop-App**: Sie laufen und springen sofort, Stück für Stück aus ihren verschlüsselten Teilen gelesen, nie ganz im Speicher. Siehe [Sammlung](#collection).",
  "**Playlists in the Collection's Music**: songs in the order you choose, kept encrypted with the Collection, played in order or shuffled. Make one at the top of Music, and add songs from their menu or by holding them down. See [Collection](#collection).":
    "**Playlists in der Musik der Sammlung**: Lieder in der Reihenfolge, die du wählst, verschlüsselt mit der Sammlung, der Reihe nach oder zufällig gespielt. Lege oben unter Musik eine an und füge Lieder über ihr Menü hinzu oder indem du sie gedrückt hältst. Siehe [Sammlung](#collection).",
  "**Subtitles for the Collection's videos**: an .srt or .vtt file in the same folder with the video's name (film.srt, or film.en.srt) shows as its subtitles, and a tap at the top turns them off or on. See [Collection](#collection).":
    "**Untertitel für die Videos der Sammlung**: Eine .srt- oder .vtt-Datei im selben Ordner mit dem Namen des Videos (film.srt oder film.en.srt) wird als seine Untertitel gezeigt, und ein Tippen oben schaltet sie aus oder an. Siehe [Sammlung](#collection).",
  "**A player's screen for the Collection**: tap the bar of the music playing, or **Now playing**, for its cover, title, artist and album, a bar to move in it, previous and next, **Shuffle**, **Repeat** (all or one), the speed from 0.5× to 2×, and the list, to tap another. A video, or music of 10 minutes or more, starts where you left it. The notification shows the title and cover only with **Show the title in the notification** on. See [Collection](#collection).":
    "**Ein Player-Bildschirm für die Sammlung**: Tippe auf die Leiste der laufenden Musik oder auf **Läuft gerade** für Cover, Titel, Interpret und Album, eine Leiste zum Spulen, vorherigen und nächsten Titel, **Zufällig**, **Wiederholen** (alle oder einen), das Tempo von 0.5× bis 2× und die Liste, um einen anderen anzutippen. Ein Video oder Musik ab 10 Minuten beginnt dort, wo du aufgehört hast. Die Benachrichtigung zeigt Titel und Cover nur, wenn **Titel in der Benachrichtigung zeigen** an ist. Siehe [Sammlung](#collection).",
  "**Photos, Videos, Music and Files**: the Collection has a tab for each, each with the folders that hold any of its files above it. See [Collection](#collection).":
    "**Fotos, Videos, Musik und Dateien**: Die Sammlung hat für jedes einen Reiter, jeder mit den Ordnern darüber, die etwas von ihm enthalten. Siehe [Sammlung](#collection).",
  "**Music of the Collection goes on with the screen off**: on Android, music could stop a while after the screen went off. Now the player is kept in the foreground for as long as the list plays. See [Collection](#collection).":
    "**Musik der Sammlung spielt bei ausgeschaltetem Bildschirm weiter**: Auf Android konnte Musik eine Weile nach dem Ausschalten des Bildschirms aufhören. Jetzt bleibt der Player im Vordergrund, solange die Liste spielt. Siehe [Sammlung](#collection).",
  "**More music and video formats in the Collection**: on Android MP3, AAC, M4A, FLAC, Ogg, Opus, WAV, AMR, MP4, MKV, WebM and 3GP play, also a file that came with no type, known by its name's ending, and seeking works in an MP3 with no table of its seconds. See [Collection](#collection).":
    "**Mehr Musik- und Videoformate in der Sammlung**: Auf Android spielen MP3, AAC, M4A, FLAC, Ogg, Opus, WAV, AMR, MP4, MKV, WebM und 3GP, auch eine Datei, die ohne Typ kam, erkannt an der Endung ihres Namens, und Spulen geht auch in einer MP3 ohne Tabelle ihrer Sekunden. Siehe [Sammlung](#collection).",
  "**New modules on after an update**: where the modules were chosen before the Collection came, as on a phone or computer updated from 6, the Collection stayed off. Now it is on there, as is any module that comes later, until you turn it off in Settings → General → Modules. See [Modules](#modules).":
    "**Neue Module nach einem Update an**: Wo die Module gewählt wurden, bevor die Sammlung kam, wie auf einem Telefon oder Computer, der von 6 aktualisiert wurde, blieb die Sammlung aus. Jetzt ist sie dort an, wie jedes Modul, das später kommt, bis du sie unter Einstellungen → Allgemein → Module ausschaltest. Siehe [Module](#modules).",
  "**A home relay by itself**: on Android, when your relay names a relay paired with it, a space with no home relay takes that one, only through Tor, with its token from a coupon: nothing to type. **Automatically from your relay**, under Settings → Relay and networks → Home relay, turns it off. See [Home relay](#home-relay).":
    "**Ein Heim-Relay von selbst**: Auf Android nimmt ein Bereich ohne Heim-Relay das Relay, mit dem dein Relay gepaart ist, sobald dein Relay es nennt, nur über Tor, mit seinem Token aus einem Gutschein: nichts zu tippen. **Automatisch von deinem Relay** unter Einstellungen → Relay und Netze → Heim-Relay schaltet es aus. Siehe [Heim-Relay](#home-relay).",
  "**A chip for every part that is on**: above the chats, **SMS**, **Erevos**, **Matrix**, **XMPP** and **Nostr** each have their chip whenever they are on in Modules, also with no chat yet. Before, in a space with only SMS so far, choosing **All messages** after Erevos's icon opened its chats hid the chips, with no way back.":
    "**Ein Chip für jeden Teil, der an ist**: Über den Chats haben **SMS**, **Erevos**, **Matrix**, **XMPP** und **Nostr** jeweils ihren Chip, sobald sie in den Modulen an sind, auch noch ohne Chat. Vorher versteckte in einem Bereich mit bisher nur SMS **Alle**, nachdem das Symbol von Erevos seine Chats geöffnet hatte, die Chips, ohne Weg zurück.",
  "**Invite at one tap**: on the home screen, **Invite** beside the relay's line shows an invite's QR code at once, with nothing to type: who it is for and your name for them can be typed below it, or never. See [Chat through a relay](#relay).":
    "**Einladung mit einem Tipp**: Auf dem Startbildschirm zeigt **Einladen** neben der Zeile des Relays sofort den QR-Code einer Einladung, ohne etwas einzutippen: Für wen sie ist und dein Name für die Person können darunter eingegeben werden, oder nie. Siehe [Chat über ein Relay](#relay).",
  "**Sign in with LPHL without typing a code**: on Android, once you sign in on the page the browser opened, tap **Open Erevos** there, and Erevos finishes signing in by itself. The code to type is still on the page, in case nothing opens. It needs the relay updated. See [Chat through a relay](#relay).":
    "**Mit LPHL anmelden, ohne einen Code einzutippen**: Auf Android tippst du, nachdem du dich auf der vom Browser geöffneten Seite angemeldet hast, dort auf **Erevos öffnen**, und Erevos schließt die Anmeldung von selbst ab. Der Code zum Eintippen bleibt auf der Seite, falls sich nichts öffnet. Das Relay muss dafür aktualisiert sein. Siehe [Chat über ein Relay](#relay).",
  "**Invites and contact links by touch**: on an Android phone with NFC, while **Invite someone** or **My QR code** shows the small QR code, hold the back of their phone to the back of yours: their phone opens it by itself, in Erevos where it is installed. See [Chat through a relay](#relay).":
    "**Einladungen und Kontaktlinks per Berührung**: Auf einem Android-Telefon mit NFC halte, während **Jemanden einladen** oder **Mein QR-Code** den kleinen QR-Code zeigt, die Rückseite ihres Telefons an die Rückseite deines: Ihr Telefon öffnet ihn von selbst, in Erevos, wo es installiert ist. Siehe [Chat über ein Relay](#relay).",
  "**Smaller invite QR codes**: the QR code of **Invite someone** now holds about eight times less, so simpler and older cameras read it too, and its link is short enough for an SMS. It opens Erevos's page for invites, which offers Erevos and then opens the invite in it. Where your relay lets this phone make no invite, the long one is still made. See [Chat through a relay](#relay).":
    "**Kleinere QR-Codes für Einladungen**: Der QR-Code von **Jemanden einladen** enthält jetzt etwa achtmal weniger, sodass auch einfachere und ältere Kameras ihn lesen, und sein Link ist kurz genug für eine SMS. Er öffnet die Einladungsseite von Erevos, die Erevos anbietet und dann die Einladung darin öffnet. Wo dein Relay diesem Telefon keine Einladung erlaubt, wird weiterhin die lange erstellt. Siehe [Chat über ein Relay](#relay).",
  "**A small contact QR code**: **Show my QR code** now shows your contact link in short, so any camera reads it, and **Share my contact link** sends a link any app lets you tap. Whoever scans it while it shows is your contact at once; later, they write a message request first. **Large QR code, for no internet** shows the whole one, for near with no internet. See [Chat through a relay](#relay).":
    "**Ein kleiner Kontakt-QR-Code**: **Meinen QR-Code zeigen** zeigt deinen Kontaktlink jetzt in kurzer Form, sodass jede Kamera ihn liest, und **Meinen Kontaktlink teilen** sendet einen Link, den jede App antippbar macht. Wer ihn scannt, solange er zu sehen ist, ist sofort dein Kontakt; später schreibt die Person zuerst eine Nachrichtenanfrage. **Großer QR-Code, ohne Internet** zeigt den ganzen, für die Nähe ohne Internet. Siehe [Chat über ein Relay](#relay).",
  "**Links open Erevos**: on Android, an invite or contact link tapped in any app opens Erevos, which asks before it takes it, once the web server and a new Erevos are both out. See [Chat through a relay](#relay).":
    "**Links öffnen Erevos**: Auf Android öffnet ein Einladungs- oder Kontaktlink, der in irgendeiner App angetippt wird, Erevos, das fragt, bevor es ihn übernimmt, sobald der Webserver und ein neues Erevos beide erschienen sind. Siehe [Chat über ein Relay](#relay).",
  "**Home relay**: the screen no longer says that whoever runs a home relay sees this phone's address when it is set to **Only through Tor**.":
    "**Heim-Relay**: Der Bildschirm sagt nicht mehr, dass wer ein Heim-Relay betreibt, die Adresse dieses Telefons sieht, wenn es auf **Nur über Tor** steht.",
  "**An invite that opened Erevos for the first time** opens once the first start's setup is done, however long it took; before, after five minutes on the setup screens it was lost.":
    "**Eine Einladung, die Erevos zum ersten Mal geöffnet hat**, öffnet sich, sobald die Einrichtung des ersten Starts fertig ist, egal wie lange sie dauerte; vorher ging sie nach fünf Minuten auf den Einrichtungsbildschirmen verloren.",
  // 7.0.0-rc.1
  "**Linked devices on the same Wi-Fi**: the phone and a computer on the same Wi-Fi or hotspot give each other what changes straight there, with no internet too. See [Linked devices](#devices).":
    "**Verknüpfte Geräte im selben WLAN**: Telefon und Computer im selben WLAN oder Hotspot geben einander, was sich ändert, direkt dort, auch ohne Internet. Siehe [Verknüpfte Geräte](#devices).",
  "**Your Matrix, XMPP and Nostr accounts on every linked device**: each device linked gets them by itself, with no choice to make, and they follow as they change on the phone: one you sign out of there, or replace with another, goes from the devices too. See [Linked devices](#devices).":
    "**Deine Matrix-, XMPP- und Nostr-Konten auf jedem verknüpften Gerät**: Jedes verknüpfte Gerät bekommt sie von selbst, ohne Auswahl, und sie folgen den Änderungen auf dem Telefon: Eines, von dem du dich dort abmeldest oder das du durch ein anderes ersetzt, geht auch von den Geräten. Siehe [Verknüpfte Geräte](#devices).",
  "**Same settings on your linked devices**: the language, the look and Last seen changed on the phone or a computer change on the others too. A photo behind the screens, passwords, PINs and what is about one device alone stay on each. A device can keep its own: **Same settings on every device** in Linked devices. See [Linked devices](#devices).":
    "**Gleiche Einstellungen auf deinen verknüpften Geräten**: Sprache, Aussehen und Zuletzt online, auf dem Telefon oder einem Computer geändert, ändern sich auch auf den anderen. Ein Foto hinter den Bildschirmen, Passwörter, PINs und was nur ein Gerät betrifft, bleiben auf jedem. Ein Gerät kann seine eigenen behalten: **Gleiche Einstellungen auf allen Geräten** unter Verknüpfte Geräte. Siehe [Verknüpfte Geräte](#devices).",
  "**Last seen**: when a contact is not online, their chat says when they last had Erevos open, to the minute. It goes end-to-end encrypted, never to the relay. It is on, and both ways: turn it off in Settings → Privacy and security → Last seen, and no one sees yours, nor you theirs. Hidden chats have their own time and their own switch, in a chat's details there. See [Chat through a relay](#relay).":
    "**Zuletzt online**: Wenn ein Kontakt nicht online ist, sagt sein Chat, wann er Erevos zuletzt offen hatte, auf die Minute genau. Es geht Ende-zu-Ende-verschlüsselt, nie ans Relay. Es ist an, und in beide Richtungen: Schalte es unter Einstellungen → Datenschutz und Sicherheit → Zuletzt online aus, und niemand sieht deine, und du siehst auch nicht seine. Versteckte Chats haben ihre eigene Zeit und ihren eigenen Schalter, dort in den Details eines Chats. Siehe [Chat über ein Relay](#relay).",
  "**One Public feed**: the new **Public** chip on the home screen shows the public posts of the Nostr people you follow and the public Matrix rooms you are in as one feed, as in Amethyst, with photos inside the posts and a card for a link. Answer, share again, like, share and write new posts with photos; for Matrix, answer, react and share. **Photos** chooses whether photos come at once, only through Tor or on a tap. The **Nostr** chip shows only the Nostr chats again. See [Chats with other Nostr apps](#nostr-chats).":
    "**Ein öffentlicher Feed**: Der neue Chip **Öffentlich** auf dem Startbildschirm zeigt die öffentlichen Beiträge der Nostr-Menschen, denen du folgst, und die öffentlichen Matrix-Räume, in denen du bist, als einen Feed, wie in Amethyst, mit Fotos im Beitrag und einer Karte für einen Link. Antworte, teile erneut, like, teile und schreibe neue Beiträge mit Fotos; bei Matrix antworte, reagiere und teile. **Fotos** wählt, ob Fotos sofort, nur über Tor oder beim Antippen kommen. Der Chip **Nostr** zeigt wieder nur die Nostr-Chats. Siehe [Chats mit anderen Nostr-Apps](#nostr-chats).",
  "**Collection**: an encrypted place in every space and hidden place for photos, files and folders, with its icon next to the lock. Turn it on in Modules. See [Collection](#collection).":
    "**Sammlung**: ein verschlüsselter Ort in jedem Bereich und jedem versteckten Ort für Fotos, Dateien und Ordner, mit ihrem Symbol neben dem Schloss. Schalte sie in den Modulen ein. Siehe [Sammlung](#collection).",
  "**Music, videos and PDFs in the Collection**: music and videos play from their encrypted pieces, music on with the screen off and with play, pause, next and previous on the lock screen, and PDFs read page by page inside Erevos. **Open with another app** leaves no plain copy, and a photo or video picked from the gallery can be deleted there after importing. See [Collection](#collection).":
    "**Musik, Videos und PDFs in der Sammlung**: Musik und Videos spielen aus ihren verschlüsselten Stücken, Musik auch bei ausgeschaltetem Bildschirm, mit Abspielen, Pause, Weiter und Zurück auf dem Sperrbildschirm, und PDFs lesen sich Seite für Seite in Erevos. **Mit einer anderen App öffnen** hinterlässt keine unverschlüsselte Kopie, und ein Foto oder Video aus der Galerie kann nach dem Import dort gelöscht werden. Siehe [Sammlung](#collection).",
  "**The Collection on a computer**: in the desktop app for Linux, macOS and Windows the Collection keeps your photos and files encrypted too. Photos, PDFs, music and videos open in memory only, never as a plain copy on the disk, and close when the space locks. **Save to the computer** asks first. See [Collection](#collection).":
    "**Die Sammlung auf dem Computer**: in der Desktop-App für Linux, macOS und Windows hält die Sammlung deine Fotos und Dateien ebenfalls verschlüsselt. Fotos, PDFs, Musik und Videos öffnen sich nur im Speicher, nie als unverschlüsselte Kopie auf der Festplatte, und schließen sich, wenn der Bereich sperrt. **Auf dem Computer speichern** fragt vorher. Siehe [Sammlung](#collection).",
  "**Files up to 4 GB in the Collection**: on Android a file picked from the phone's files is encrypted as it is read, with no plain copy first, so it comes in faster and needs no room twice. In the desktop app music and videos up to 1 GB play. See [Collection](#collection).":
    "**Dateien bis 4 GB in der Sammlung**: auf Android wird eine aus den Dateien des Telefons gewählte Datei verschlüsselt, während sie gelesen wird, ohne unverschlüsselte Kopie vorher, so kommt sie schneller hinein und braucht keinen doppelten Platz. In der Desktop-App spielen Musik und Videos bis 1 GB. Siehe [Sammlung](#collection).",
  "**The Collection on a WebDAV server**: each space and hidden place can copy its Collection, still encrypted, to a folder on a server you choose, Nextcloud, ownCloud or any that speaks WebDAV, so big files are not only on the phone. Only what is new goes, and a phone that lacks a file fetches it from there. See [Collection](#collection).":
    "**Die Sammlung auf einem WebDAV-Server**: jeder Bereich und jeder versteckte Ort kann seine Sammlung, weiterhin verschlüsselt, in einen Ordner auf einem Server deiner Wahl kopieren, Nextcloud, ownCloud oder jeder, der WebDAV spricht, damit große Dateien nicht nur auf dem Telefon liegen. Es geht nur, was neu ist, und ein Telefon, dem eine Datei fehlt, holt sie von dort. Siehe [Sammlung](#collection).",
  "**The Collection on your linked devices**: turn on **On my linked devices too** in a Collection's settings and that Collection goes to the space's or hidden place's linked devices, changes and deletions with it. Small pictures come at once, a file itself on the same Wi-Fi or when you open it, a piece at a time, going on where it stopped after the network drops. See [Collection](#collection).":
    "**Die Sammlung auf deinen verknüpften Geräten**: schalte **Auch auf meinen verknüpften Geräten** in den Einstellungen einer Sammlung ein, und diese Sammlung geht auf die verknüpften Geräte des Bereichs oder versteckten Ortes, Änderungen und Löschungen mit. Kleine Bilder kommen sofort, die Datei selbst im selben WLAN oder wenn du sie öffnest, Stück für Stück, und nach einem Netzabbruch geht es dort weiter, wo es aufhörte. Siehe [Sammlung](#collection).",
  "**Groups stay on the device you choose**: on the phone, under Linked devices → Groups stay on, move the groups to a linked computer. Their keys go there, never copied, so the groups work there with the phone off and new ones can be made there; members see nothing new. See [Linked devices](#devices).":
    "**Gruppen bleiben auf dem Gerät deiner Wahl**: Zieh die Gruppen auf dem Telefon unter Verknüpfte Geräte → Gruppen bleiben auf auf einen verknüpften Computer um. Ihre Schlüssel gehen dorthin, nie kopiert, sodass die Gruppen dort auch bei ausgeschaltetem Telefon funktionieren und dort neue angelegt werden können; die Mitglieder sehen nichts Neues. Siehe [Verknüpfte Geräte](#devices).",
  "**Add someone new on a linked device without the phone**: a computer adds someone whose contact link is from this version by itself, with the phone off, and writes to them at once; they see your account as a request, with the same safety number, and the phone adds them too once it is on. See [Linked devices](#devices).":
    "**Jemanden Neuen auf einem verknüpften Gerät ohne das Telefon hinzufügen**: Ein Computer fügt jemanden, dessen Kontaktlink von dieser Version ist, selbst hinzu, bei ausgeschaltetem Telefon, und schreibt ihm sofort; die Person sieht dein Konto als Anfrage, mit derselben Sicherheitsnummer, und das Telefon fügt sie ebenfalls hinzu, sobald es an ist. Siehe [Verknüpfte Geräte](#devices).",
  "**Calls and Send later on your linked devices without the phone**: with a contact on this version, a computer calls and is called by itself and sends a message for later itself, with the phone off, and a copy goes to each of their devices too, held till its time. Every device of yours shows what is scheduled, and deleting it on any of them takes it back everywhere. See [Linked devices](#devices).":
    "**Anrufe und Später senden auf deinen verknüpften Geräten ohne das Telefon**: Mit einem Kontakt mit dieser Version ruft ein Computer selbst an, wird selbst angerufen und sendet eine Nachricht für später selbst, bei ausgeschaltetem Telefon, und eine Kopie geht auch an jedes seiner Geräte, bis zu ihrer Zeit aufbewahrt. Jedes deiner Geräte zeigt, was geplant ist, und auf einem davon gelöscht, wird es überall zurückgenommen. Siehe [Verknüpfte Geräte](#devices).",
  '**Support Erevos**: every way has its QR code now, Liberapay and PayPal too, and PayPal opens in the browser.':
    '**Erevos unterstützen**: Jeder Weg hat jetzt seinen QR-Code, auch Liberapay und PayPal, und PayPal öffnet sich im Browser.',
  '**Chats open at their end**: a long chat, or one with imported messages, could open at a message read long ago, often a photo, as it drew earlier messages on its way to the end. Now it opens at the newest message, and the arrow to where you left off is there when new ones came.':
    '**Chats öffnen sich an ihrem Ende**: Ein langer Chat oder einer mit importierten Nachrichten konnte sich bei einer Nachricht öffnen, die du vor langer Zeit gelesen hattest, oft ein Foto, weil er auf dem Weg zum Ende frühere Nachrichten lud. Jetzt öffnet er sich bei der neuesten Nachricht, und der Pfeil dorthin, wo du aufgehört hast, ist da, wenn neue gekommen sind.',
  "**Tor off unless you turn it on**: a new space sends nothing through Tor, so messages go fastest, and turning Tor on asks first, as it makes them slower. A space you already have keeps its choice, under Settings → Relay and networks → Tor. Texts through Nostr now go without Tor too: then the Nostr relays see your phone's internet address, never who wrote to whom. See [Through Tor](#tor).":
    "**Tor aus, bis du es einschaltest**: Ein neuer Bereich sendet nichts über Tor, daher gehen Nachrichten am schnellsten, und Tor einzuschalten fragt vorher, da es sie langsamer macht. Ein Bereich, den du schon hast, behält seine Wahl, unter Einstellungen → Relay und Netze → Tor. Texte über Nostr gehen jetzt auch ohne Tor: dann sehen die Nostr-Relays die Internetadresse deines Telefons, nie, wer wem geschrieben hat. Siehe [Über Tor](#tor).",
  "**Moving a chat to a space with no relay**: **Move to another space** stopped there, as that space had no relay of its own. Now it offers this space's relay, which that space then keeps, and it makes that space's relay queue when it has a relay but no queue yet. See [Second password](#second).":
    "**Einen Chat in einen Bereich ohne Relay verschieben**: **In einen anderen Bereich verschieben** hielt dort an, weil jener Bereich kein eigenes Relay hatte. Jetzt bietet es das Relay dieses Bereichs an, das jener Bereich dann behält, und legt die Relay-Warteschlange jenes Bereichs an, wenn er ein Relay, aber noch keine Warteschlange hat. Siehe [Zweites Passwort](#second).",
  "**Fixes from a review of all the code**: a message you were typing stays with its chat when you open another, and never shows in a PIN-locked chat's place; a locked chat under a locked group stays out of screenshots when the group closes; the Collection's catalogue goes into backups, so a restored phone opens its files; calls in a public group reach their members; a Matrix or XMPP account no longer stops for good at one bad message or an unreachable server; a message sent for later stays listed while its details are still coming; the computer app's Wi-Fi link refuses an impossible port; and the panic button lets the apps it tells start before it closes.":
    "**Korrekturen aus einer Prüfung des ganzen Codes**: eine Nachricht, die du gerade schreibst, bleibt bei ihrem Chat, wenn du einen anderen öffnest, und erscheint nie an der Stelle eines Chats mit PIN; ein gesperrter Chat unter einer gesperrten Gruppe bleibt aus Bildschirmfotos heraus, wenn die Gruppe schließt; der Katalog der Sammlung kommt in die Sicherungen, sodass ein wiederhergestelltes Telefon ihre Dateien öffnet; Anrufe in einer öffentlichen Gruppe erreichen ihre Mitglieder; ein Matrix- oder XMPP-Konto bleibt nicht mehr für immer an einer kaputten Nachricht oder einem unerreichbaren Server hängen; eine Nachricht für später bleibt aufgeführt, während ihre Angaben noch kommen; die WLAN-Verbindung der Computer-App lehnt einen unmöglichen Port ab; und der Panikknopf lässt die Apps, denen er Bescheid gibt, starten, bevor er schließt.",
  "**Safer in twelve more ways, from the review before 7**: a message the relay hands you is deleted there only once your phone has kept it, so a connection cut at that moment loses nothing (an older relay works as before); a relay keeps a bound on what it holds in all and for each phone; in a public group no one can have another member taken out by claiming to be them; with SMS invites off, no one becomes a contact from your number alone; searches that find nothing are forgotten after a quarter of an hour; a Matrix message is shown as its sender's only when the key came from their device, else as **Not verified**, and an XMPP or Matrix device that changes its key gets nothing until you accept it, while a new device is said in the chat; a photo or file from a server its sender chose is fetched by itself only through Tor, else on a tap; an old first packet replayed to you never takes over a chat; and your linked devices' log takes each device's changes only from that device, and forgets devices that are gone.":
    "**Auf zwölf weitere Arten sicherer, aus der Prüfung vor 7**: eine Nachricht, die dir das Relay gibt, wird dort erst gelöscht, wenn dein Telefon sie behalten hat, sodass eine in dem Moment getrennte Verbindung nichts verliert (ein älteres Relay arbeitet wie bisher); ein Relay hält eine Grenze für das, was es insgesamt und je Telefon aufbewahrt; in einer öffentlichen Gruppe kann niemand ein anderes Mitglied entfernen lassen, indem er sich als dieses ausgibt; bei ausgeschalteten SMS-Einladungen wird niemand allein über deine Nummer ein Kontakt; Suchen, die nichts finden, werden nach einer Viertelstunde vergessen; eine Matrix-Nachricht wird nur dann als die ihres Absenders gezeigt, wenn der Schlüssel von dessen Gerät kam, sonst als **Nicht verifiziert**, und ein XMPP- oder Matrix-Gerät, das seinen Schlüssel ändert, bekommt nichts, bis du es annimmst, während ein neues Gerät im Chat genannt wird; ein Foto oder eine Datei von einem Server, den der Absender gewählt hat, wird nur über Tor von selbst geholt, sonst mit einem Tipp; ein altes erstes Paket, das dir erneut zugespielt wird, übernimmt nie einen Chat; und das Protokoll deiner verknüpften Geräte nimmt die Änderungen jedes Geräts nur von diesem Gerät an und vergisst Geräte, die weg sind.",
  "**A home relay only through Tor**: switch a home relay to **Only through Tor** and it never sees your phone's address, whatever Tor is set to for the rest. With no token typed, it gives one for a coupon that your relay signs blind, so neither relay can tell whose it is, and two spaces can use each other's relays as home relays with nothing tying them together. The token comes within the hour, lasts 90 days, and Erevos renews it by itself. Needs Tor, on Android. See [Home relay](#home-relay).":
    '**Ein Heim-Relay nur über Tor**: Stelle ein Heim-Relay auf **Nur über Tor**, und es sieht nie die Adresse deines Telefons, egal was für den Rest bei Tor eingestellt ist. Ohne eingegebenes Token gibt es eines für einen Gutschein, den dein Relay blind signiert, sodass keines der beiden Relays erkennen kann, wem es gehört, und zwei Bereiche können die Relays des jeweils anderen als Heim-Relays nutzen, ohne dass etwas sie verbindet. Das Token kommt innerhalb einer Stunde, gilt 90 Tage, und Erevos erneuert es von selbst. Braucht Tor, auf Android. Siehe [Heim-Relay](#home-relay).',
  // 6.0.0-rc.2
  "**Home's buttons stay at the bottom**: after the password, home's **Remind me** and **New chat** could float halfway up the screen, over the chats, with the list ending above them, until Erevos went away and came back. Now the screen asks Android at once whether a keyboard is open. See [Password lock](#lock).":
    "**Die Knöpfe des Startbildschirms bleiben unten**: Nach dem Passwort konnten **Erinnern** und **Neuer Chat** auf halber Höhe über den Chats schweben, und die Liste endete darüber, bis Erevos verlassen und wieder geöffnet wurde. Jetzt fragt der Bildschirm Android sofort, ob eine Tastatur offen ist. Siehe [Passwortsperre](#lock).",
  "**The Nostr tab's posts come**: **Posts** could stay on **Looking…** for good through Tor. Each wait through Tor took one of the threads the whole app shares, and once all were taken, every look-up of the posts waited behind the others; a relay that answered and then could not be reached kept them waiting with no end. Now Tor's waits have threads of their own, a relay that cannot be reached is let be after 20 seconds, and the posts come within about two minutes at most, with what was found by then. See [Chats with other Nostr apps](#nostr-chats).":
    "**Die Beiträge im Nostr-Tab kommen**: **Beiträge** konnte über Tor für immer bei **Suche…** bleiben. Jedes Warten über Tor belegte einen der Threads, die sich die ganze App teilt, und waren alle belegt, wartete jede Abfrage der Beiträge hinter den anderen; ein Relay, das antwortete und danach nicht mehr erreichbar war, ließ sie ohne Ende warten. Jetzt hat das Warten über Tor eigene Threads, ein Relay, das nicht erreichbar ist, wird nach 20 Sekunden gelassen, und die Beiträge kommen nach höchstens etwa zwei Minuten, mit dem, was bis dahin gefunden wurde. Siehe [Chats mit anderen Nostr-Apps](#nostr-chats).",
  "**Linux, Windows and macOS again**: 6.0.0-rc.1 came out without them: the check that each build for computers opens did not know the setup of Erevos's very first start. Now it does.":
    "**Wieder Linux, Windows und macOS**: 6.0.0-rc.1 erschien ohne sie: Die Prüfung, ob jede Fassung für Computer startet, kannte die Einrichtung beim allerersten Start von Erevos nicht. Jetzt kennt sie sie.",
  // 6.0.0-rc.1
  "**Links open on Sailfish OS**: **Sign in with LPHL**, a donation page or a link in a chat opened nothing there. Now Sailfish OS opens them: a web page in the browser, a number in the phone or the messages, an address in the mail.":
    "**Links öffnen sich unter Sailfish OS**: **Mit LPHL anmelden**, eine Spendenseite oder ein Link in einem Chat öffneten dort nichts. Jetzt öffnet Sailfish OS sie: eine Webseite im Browser, eine Nummer im Telefon oder in den Nachrichten, eine Adresse in der Mail.",
  "**Matrix, and photos and files in XMPP and Nostr chats, on Sailfish OS**: Erevos there could not reach their servers over HTTPS, so Matrix could not sign in, photos and files neither came nor went, and links showed no preview. Now they work as on a computer.":
    "**Matrix sowie Fotos und Dateien in XMPP- und Nostr-Chats unter Sailfish OS**: Dort erreichte Erevos ihre Server nicht über HTTPS, sodass sich Matrix nicht anmelden konnte, Fotos und Dateien weder ankamen noch hinausgingen und Links keine Vorschau zeigten. Jetzt funktionieren sie wie auf einem Computer.",
  "**A phone call shows its screen**: with Erevos as the phone app, a call that came could ring with the phone's screen black, so it could not be answered, when Android's full-screen notifications for Erevos, Erevos's notices or its notices of incoming calls were off. Now the call screen comes up by itself, over the lock screen too, and turns the screen on. A call that Do Not Disturb holds back still comes quietly, with the screen off. See [Phone](#phone).":
    "**Ein Telefonanruf zeigt seinen Bildschirm**: Mit Erevos als Telefon-App konnte ein eingehender Anruf bei schwarzem Bildschirm klingeln und ließ sich nicht annehmen, wenn die Vollbild-Benachrichtigungen von Android für Erevos, die Benachrichtigungen von Erevos oder seine Benachrichtigungen für eingehende Anrufe aus waren. Jetzt erscheint der Anrufbildschirm von selbst, auch über dem Sperrbildschirm, und schaltet den Bildschirm ein. Ein Anruf, den „Bitte nicht stören“ zurückhält, kommt weiterhin still, bei ausgeschaltetem Bildschirm. Siehe [Telefon](#phone).",
  "**The calculator shows a long result from its start**: upright, a result with many decimals hid its first digits, which showed only with the phone turned sideways. Now a long number gets smaller to fit, its first digits always in sight.":
    "**Der Taschenrechner zeigt ein langes Ergebnis von vorn**: Im Hochformat verbarg ein Ergebnis mit vielen Nachkommastellen seine ersten Ziffern, die nur im Querformat zu sehen waren. Jetzt wird eine lange Zahl kleiner, bis sie passt, und ihre ersten Ziffern bleiben immer sichtbar.",
  "**Pick the recipient of a new SMS from your contacts**: **New SMS** has a **Contacts** button that opens your contacts with a search, and typing a name or number suggests the contacts that match. A contact with several numbers shows a line for each, and for a group MMS each one you pick is added. With only the SMS open, only the phone's contacts show. See [SMS](#sms).":
    "**Den Empfänger einer neuen SMS aus den Kontakten wählen**: **Neue SMS** hat eine Schaltfläche **Kontakte**, die deine Kontakte mit Suche öffnet, und beim Tippen eines Namens oder einer Nummer erscheinen die passenden Kontakte. Ein Kontakt mit mehreren Nummern zeigt für jede eine Zeile, und bei einer Gruppen-MMS wird jede Wahl hinzugefügt. Ist nur die SMS-Ansicht offen, erscheinen nur die Kontakte des Telefons. Siehe [SMS](#sms).",
  "**More for a number in the Phone**: on the keypad, **⋯** beside a typed number offers **Add to contacts**, **Add to an existing contact**, **Send an SMS** and **Copy the number**. **Recents** and **Favourites** offer **Copy the number** and **Open the contact**; **Favourites** also **Send an SMS**, and **Recents** adds an unknown number to an existing contact. With Erevos locked, the Phone still only calls. See [Phone](#phone).":
    "**Mehr zu einer Nummer im Telefon**: Auf der Wähltastatur bietet **⋯** neben einer getippten Nummer **Zu Kontakten hinzufügen**, **Zu bestehendem Kontakt hinzufügen**, **SMS senden** und **Nummer kopieren**. Die **Anrufliste** und die **Favoriten** bieten **Nummer kopieren** und **Kontakt öffnen**; die **Favoriten** auch **SMS senden**, und die **Anrufliste** fügt eine unbekannte Nummer einem bestehenden Kontakt hinzu. Bei gesperrtem Erevos ruft das Telefon weiterhin nur an. Siehe [Telefon](#phone).",
  "**A short buzz on touch**: the keys of the keypad, **Call**, **End**, Send, the keyboard's Enter, switches and menus that open give a short buzz. **Settings** → **Appearance** → **Vibrate on touch** turns it off. See [Appearance](#appearance).":
    "**Ein kurzes Vibrieren bei Berührung**: Die Tasten des Wähltastenfelds, **Anrufen**, **Beenden**, Senden, die Enter-Taste der Tastatur, Schalter und Menüs, die sich öffnen, vibrieren kurz. Unter **Einstellungen** → **Darstellung** → **Vibration bei Berührung** schaltest du es aus. Siehe [Darstellung](#appearance).",
  "**A number on each icon, on Huawei and Honor**: their launchers now show a number on each of Erevos's icons apart, with **Number on the icon** on: on Erevos's own the messages, on SMS's the SMS not read, on Phone's the missed calls, on Contacts's a birthday today. Most other launchers, such as those of Pixel and GrapheneOS, Samsung's and Kvaesitso, give a notice's dot or number to all of an app's icons alike, and Erevos cannot change that there. See [Appearance](#appearance).":
    "**Eine Zahl auf jedem Symbol, bei Huawei und Honor**: Ihre Launcher zeigen jetzt auf jedem Symbol von Erevos eine eigene Zahl, mit **Zahl auf dem Symbol** an: auf dem von Erevos selbst die Nachrichten, auf dem von SMS die ungelesenen SMS, auf dem von Telefon die verpassten Anrufe, auf dem von Kontakte einen Geburtstag heute. Die meisten anderen Launcher, etwa die von Pixel und GrapheneOS, der von Samsung und Kvaesitso, geben den Punkt oder die Zahl einer Meldung allen Symbolen einer App gleich, und dort kann Erevos das nicht ändern. Siehe [Darstellung](#appearance).",
  "**Choose the parts of Erevos you use**: Erevos's own chats, the Phone, the SMS, and the chats with Nostr, Matrix and XMPP apps are modules now, any of them on, Erevos's own too, at least one. One that is off does not start and shows nowhere, and the Phone's and the SMS's icons leave the phone's apps: Erevos is lighter, opens faster and uses less battery. Nothing of it is deleted: it is all there again when it is back on. Erevos's very first start sets it up as an installer does, its language, the modules and what Android should allow for them; a module turned on later asks for its permissions again. After this update every module stays on until you change them in **Settings** → **General** → **Modules**. See [Modules](#modules).":
    "**Wähle die Teile von Erevos, die du nutzt**: Die eigenen Chats von Erevos, das Telefon, die SMS und die Chats mit Nostr-, Matrix- und XMPP-Apps sind jetzt Module, jedes davon kann eingeschaltet sein, auch die eigenen von Erevos, mindestens eines. Ein ausgeschaltetes Modul startet nicht und erscheint nirgends, und die Symbole von Telefon und SMS verschwinden aus den Apps des Telefons: Erevos wird leichter, öffnet schneller und braucht weniger Akku. Nichts davon wird gelöscht: Alles ist wieder da, wenn es wieder an ist. Der allererste Start von Erevos richtet es ein wie ein Installer, seine Sprache, die Module und was Android dafür erlauben soll; ein später eingeschaltetes Modul fragt erneut nach seinen Berechtigungen. Nach diesem Update bleibt jedes Modul an, bis du sie unter **Einstellungen** → **Allgemein** → **Module** änderst. Siehe [Module](#modules).",
  "**Public posts in the Nostr tab**: on the home screen, the Nostr tab shows first **Posts**, the public posts of the people your Nostr key follows and what they shared again, newest first, as in Amethyst or a Telegram channel, with **Chats** one tap away. Older ones come as you scroll to the end, the newest when you pull the list down; tap who wrote a post for their posts or to write to them. Read only, looked up through Tor as the space says and not kept, and no pictures or links are opened. See [Chats with other Nostr apps](#nostr-chats).":
    "**Öffentliche Beiträge im Nostr-Tab**: Auf dem Startbildschirm zeigt der Nostr-Tab zuerst **Beiträge**, die öffentlichen Beiträge der Menschen, denen dein Nostr-Schlüssel folgt, und was sie weitergeteilt haben, das Neueste zuerst, wie in Amethyst oder einem Telegram-Kanal, mit **Chats** nur einen Tipp entfernt. Ältere kommen, wenn du bis zum Ende scrollst, das Neueste, wenn du die Liste nach unten ziehst; tippe an, wer einen Beitrag geschrieben hat, für die Beiträge dieser Person oder um ihr zu schreiben. Nur zum Lesen, über Tor abgefragt, wie es der Bereich sagt, und nicht gespeichert, und Bilder oder Links werden nicht geöffnet. Siehe [Chats mit anderen Nostr-Apps](#nostr-chats).",
  "**Hidden chats on your linked devices**: each place of hidden chats now links on its own, from inside it, to the same place on a computer or in a browser, with **Linked devices** under its list. Its chats, messages, groups, calls, Chat with myself and its own Matrix, XMPP and Nostr accounts go there, and its contacts write to it there directly. Nothing of it shows in the space or on the space's linked devices. The link runs while the place is open, and while it is closed too with **Receive while closed** on. See [Linked devices](#devices).":
    "**Versteckte Chats auf deinen verknüpften Geräten**: Jeder Platz versteckter Chats verknüpft sich jetzt für sich, von innen, mit demselben Platz auf einem Computer oder im Browser, mit **Verknüpfte Geräte** unter seiner Liste. Seine Chats, Nachrichten, Gruppen, Anrufe, sein Chat mit mir selbst und seine eigenen Matrix-, XMPP- und Nostr-Konten gehen dorthin, und seine Kontakte schreiben ihm dort direkt. Nichts davon zeigt sich im Bereich oder auf den verknüpften Geräten des Bereichs. Die Verknüpfung läuft, solange der Platz offen ist, und auch geschlossen, wenn **Empfangen, wenn geschlossen** an ist. Siehe [Verknüpfte Geräte](#devices).",
  "**Move a chat to another space**: in a chat's **Details**, **Move to another space** takes it, with its messages, name, picture, look and imported chats, into the space whose password you type, as a move into hidden chats does: the safety number stays the same, and their phone is told at once to write there. That space stays closed, and the row shows in every space. A chat never takes the place of one that space, or hidden chats, already have with the same person. See [Second password](#second).":
    "**Einen Chat in einen anderen Bereich verschieben**: In den **Details** eines Chats bringt **In einen anderen Bereich verschieben** ihn mit seinen Nachrichten, seinem Namen, Bild und Aussehen und den importierten Chats in den Bereich, dessen Passwort du eingibst, wie ein Verschieben in versteckte Chats: Die Sicherheitsnummer bleibt gleich, und das Telefon des Kontakts erfährt sofort, dass es dorthin schreiben soll. Jener Bereich bleibt geschlossen, und die Zeile zeigt sich in jedem Bereich. Ein Chat nimmt nie den Platz eines Chats ein, den jener Bereich oder versteckte Chats schon mit derselben Person haben. Siehe [Zweites Passwort](#second).",
  // 4.0.0-rc.10
  "**Erevos no longer stops when only the SMS or the Contacts are open**: from them, a contact's chat, an SMS, another icon or a screen that asks for the password again could make Erevos say it could not open (Maximum call stack size exceeded). Now the password opens all of Erevos, then that screen. And when Erevos cannot open, **Try again** starts it again. See [Password lock](#lock).":
    "**Erevos hält nicht mehr an, wenn nur die SMS oder die Kontakte offen sind**: Von dort aus konnten der Chat eines Kontakts, eine SMS, ein anderes Symbol oder ein Bildschirm, der wieder nach dem Passwort fragt, Erevos sagen lassen, dass es sich nicht öffnen ließ (Maximum call stack size exceeded). Jetzt öffnet das Passwort ganz Erevos und dann diesen Bildschirm. Und wenn sich Erevos nicht öffnen lässt, startet **Erneut versuchen** es neu. Siehe [Passwortsperre](#lock).",
  "**Each icon opens what it names**: after Erevos was opened by the SMS icon, or from the recent apps, another icon, the widget or a notice could sometimes show the SMS instead. Now each opens what it names. With only the SMS or the Contacts open, another icon asks for the password as when Erevos is locked, then opens its own part: the Contacts icon only the contacts, Erevos's own icon all of it. And Back on Erevos's first screen now puts it behind, as Home does, whatever opened it. See [Password lock](#lock).":
    "**Jedes Symbol öffnet das, wofür es steht**: Nachdem Erevos über das SMS-Symbol oder aus den letzten Apps geöffnet worden war, konnten ein anderes Symbol, das Widget oder eine Benachrichtigung manchmal stattdessen die SMS zeigen. Jetzt öffnet jedes das, wofür es steht. Sind nur die SMS oder die Kontakte offen, fragt ein anderes Symbol nach dem Passwort wie bei gesperrtem Erevos und öffnet dann seinen eigenen Teil: das Kontakte-Symbol nur die Kontakte, das Symbol von Erevos selbst ganz Erevos. Und „Zurück“ auf dem ersten Bildschirm von Erevos schickt es jetzt in den Hintergrund, wie die Home-Taste, egal, was es geöffnet hat. Siehe [Passwortsperre](#lock).",
  // 4.0.0-rc.9
  "**Only the Contacts**: with Erevos locked, the Contacts icon, the widget's Contacts button and the notice of a birthday ask for the password, then open only the contacts. A chat, an SMS, Settings, and the orange padlock **Unlock everything**, ask for it again, then open all of Erevos. See [Password lock](#lock).":
    "**Nur die Kontakte**: Bei gesperrtem Erevos fragen das Kontakte-Symbol, die Kontakte-Taste des Widgets und die Benachrichtigung über einen Geburtstag nach dem Passwort und öffnen dann nur die Kontakte. Ein Chat, eine SMS, die Einstellungen und das orange Schloss **Alles entsperren** fragen erneut danach und öffnen dann ganz Erevos. Siehe [Passwortsperre](#lock).",
  "**Old private messages in Nostr chats**: Erevos also reads private messages sent the older way (NIP-04), which Damus, Primal and many apps still send and keep, past and new, in the same chats. The relays see who wrote such a message to whom; Erevos itself still sends only the NIP-17 way. See [Chats with other Nostr apps](#nostr-chats).":
    "**Alte private Nachrichten in Nostr-Chats**: Erevos liest auch private Nachrichten, die auf die ältere Art (NIP-04) gesendet wurden, wie Damus, Primal und viele Apps sie noch senden und behalten: alte und neue, in denselben Chats. Die Relays sehen, wer eine solche Nachricht an wen geschrieben hat; Erevos selbst sendet weiterhin nur auf die Art von NIP-17. Siehe [Chats mit anderen Nostr-Apps](#nostr-chats).",
  "**Public posts in Nostr chats**: in a chat with one person, **Public posts** shows what they post for everyone, newest first, read only. It is looked up through Tor as the space says and not kept, and no pictures or links are opened. See [Chats with other Nostr apps](#nostr-chats).":
    "**Öffentliche Beiträge in Nostr-Chats**: In einem Chat mit einer Person zeigt **Öffentliche Beiträge**, was sie für alle veröffentlicht, das Neueste zuerst, nur zum Lesen. Es wird über Tor abgefragt, so wie der Bereich es sagt, und nicht gespeichert, und Bilder oder Links werden nicht geöffnet. Siehe [Chats mit anderen Nostr-Apps](#nostr-chats).",
  // 4.0.0-rc.8
  // 4.0.0-rc.7
  "**Licence**: Settings → General → Licence says under which licence Erevos is free software, AGPL-3.0-or-later, its three additional terms, that it comes with no warranty, and who made it. See [Licence](#licence).":
    "**Lizenz**: Einstellungen → Allgemein → Lizenz sagt, unter welcher Lizenz Erevos freie Software ist, AGPL-3.0-or-later, nennt ihre drei zusätzlichen Bedingungen, dass es ohne jede Garantie kommt, und wer es gemacht hat. Siehe [Lizenz](#licence).",
  "**Contact**: Settings → General → Contact adds the maker of Erevos as a contact, to write to in Erevos itself, end-to-end encrypted, with no phone number and no email. See [What Erevos is](#about).":
    "**Kontakt**: Einstellungen → Allgemein → Kontakt fügt die Person hinter Erevos als Kontakt hinzu, um ihr in Erevos selbst zu schreiben, Ende-zu-Ende-verschlüsselt, ohne Telefonnummer und ohne E-Mail. Siehe [Was Erevos ist](#about).",
  "**A new sticker set, Angry Eyes**: 24 faces of big yellow eyes on a black disc, drawn by the maintainer, each with the moves he gave it.":
    "**Ein neues Sticker-Set, Angry Eyes**: 24 Gesichter aus großen gelben Augen auf einer schwarzen Scheibe, gezeichnet von der Person hinter Erevos, jedes mit den Bewegungen, die sie ihm gegeben hat.",
  "**The calculator opens again**: in 4.0.0-rc.6 it closed as soon as it was tapped.":
    "**Der Taschenrechner öffnet sich wieder**: in 4.0.0-rc.6 schloss er sich, sobald du ihn angetippt hast.",
  "**People you follow on Nostr are looked for on more relays**: **Show the people you follow** also asks relays that gather follow lists and more of the relays your key writes on, and waits longer for them; when it finds no one, it says why and how each relay answered. See [Chats with other Nostr apps](#nostr-chats).":
    "**Menschen, denen du auf Nostr folgst, werden auf mehr Relays gesucht**: **Menschen zeigen, denen du folgst** fragt auch Relays, die Folgelisten sammeln, und mehr von den Relays, auf denen dein Schlüssel schreibt, und wartet länger auf sie; findet es niemanden, sagt es, warum und wie jedes Relay geantwortet hat. Siehe [Chats mit anderen Nostr-Apps](#nostr-chats).",
  // 4.0.0-rc.6
  "**Panic password**: with the password lock on, **Set the panic password** under the Panic button sets a password of its own that, typed on the lock screen, wipes Erevos as **Wipe everything now** does, while the screen shows **Wrong password**. Nothing shows whether one is set. See [Panic button](#panic).":
    "**Panik-Passwort**: Bei eingeschalteter Passwortsperre legt **Panik-Passwort festlegen** unter „Panikknopf“ ein eigenes Passwort fest, das, auf dem Sperrbildschirm eingegeben, Erevos löscht wie **Jetzt alles löschen**, während der Bildschirm **Falsches Passwort** zeigt. Nichts zeigt, ob eines festgelegt ist. Siehe [Panikknopf](#panic).",
  "**Calculator in place of Erevos**: on Android, under Launcher icons, a calculator that works can take the place of Erevos's icon; your code, then **=**, opens Erevos, which asks for its password as always. See [Appearance](#appearance).":
    "**Taschenrechner anstelle von Erevos**: Auf Android kann unter „Startbildschirm-Symbole“ ein Taschenrechner, der funktioniert, den Platz des Symbols von Erevos einnehmen; dein Code, dann **=**, öffnet Erevos, das wie immer nach seinem Passwort fragt. Siehe [Darstellung](#appearance).",
  "**Chat with myself on your linked devices too**: notes, photos, files, voice messages and reminders written on one device go to the others, as do a reminder changed or seen and a note deleted. Those from before go once, both ways. See [Linked devices](#devices).":
    "**Chat mit mir selbst auch auf deinen verknüpften Geräten**: Notizen, Fotos, Dateien, Sprachnachrichten und Erinnerungen, die auf einem Gerät geschrieben werden, gehen an die anderen, ebenso eine geänderte oder gesehene Erinnerung und eine gelöschte Notiz. Die von früher gehen einmal, in beide Richtungen. Siehe [Verknüpfte Geräte](#devices).",
  "**Start when the phone turns on**: on Android, under In the background, Erevos can start by itself after the phone turns on, so the spaces set to say a message came while closed already say \"New message\", never which space or what. Off unless you choose it. See [Chat through a relay](#relay).":
    "**Starten, wenn das Telefon eingeschaltet wird**: Auf Android kann Erevos unter „Im Hintergrund“ nach dem Einschalten des Telefons von selbst starten, sodass die Bereiche, die melden sollen, dass eine Nachricht kam, solange sie geschlossen sind, schon „New message“ sagen, nie welcher Bereich oder was. Aus, solange du es nicht wählst. Siehe [Chat über ein Relay](#relay).",
  "**Moving the clock no longer ends the wait after wrong passwords**: it goes by the phone's own time since it started, which no one can set; after a restart it starts again from its beginning. See [Password lock](#lock).":
    "**Die Uhr zu verstellen beendet das Warten nach falschen Passwörtern nicht mehr**: Es richtet sich nach der eigenen Zeit des Telefons seit seinem Start, die niemand einstellen kann; nach einem Neustart beginnt es wieder von vorn. Siehe [Passwortsperre](#lock).",
  "**People you follow on Nostr, found where your other app keeps them**: with a key brought from another Nostr app, **Show the people you follow** also looks on the relays your key writes on, and says so when no relay answered. See [Chats with other Nostr apps](#nostr-chats).":
    "**Menschen, denen du auf Nostr folgst, dort gefunden, wo deine andere App sie hält**: Mit einem Schlüssel aus einer anderen Nostr-App sucht **Menschen zeigen, denen du folgst** auch auf den Relays, auf denen dein Schlüssel schreibt, und sagt es, wenn kein Relay geantwortet hat. Siehe [Chats mit anderen Nostr-Apps](#nostr-chats).",
  "**Your Nostr name keeps the rest of your profile**: saving **Your name** changes only the name in your profile; a picture or words that another app of your key put there stay. Before, they could be wiped. See [Chats with other Nostr apps](#nostr-chats).":
    "**Dein Nostr-Name behält den Rest deines Profils**: Speichern unter **Dein Name** ändert nur den Namen in deinem Profil; ein Bild oder Worte, die eine andere App deines Schlüssels dort gesetzt hat, bleiben. Vorher konnten sie gelöscht werden. Siehe [Chats mit anderen Nostr-Apps](#nostr-chats).",
  "**Screens come down when no keyboard is open, in every case**: the home screen's list and buttons, or a chat, could still stay up as if a keyboard were open after it had gone. Now Erevos asks Android itself whether a keyboard is shown, and with none they come down within a second.":
    "**Bildschirme gehen ohne offene Tastatur nach unten, in jedem Fall**: Die Liste und die Knöpfe des Startbildschirms oder ein Chat konnten noch oben bleiben, als wäre eine Tastatur offen, nachdem sie weg war. Jetzt fragt Erevos Android selbst, ob eine Tastatur angezeigt wird, und ohne Tastatur gehen sie innerhalb einer Sekunde nach unten.",
  // 4.0.0-rc.5
  "**New chat opens hidden chats sooner**: hold **New chat** down for a moment, not a whole second, and the field for a PIN of hidden chats opens; on Android the phone buzzes once as it opens. See [Hidden chats](#hidden).":
    "**Neuer Chat öffnet versteckte Chats schneller**: Halte **Neuer Chat** einen Moment gedrückt, nicht mehr eine ganze Sekunde, und das Feld für eine PIN versteckter Chats öffnet sich; auf Android vibriert das Telefon dabei einmal. Siehe [Versteckte Chats](#hidden).",
  "**People you follow on Nostr**: under New chat in Nostr chats, **Show the people you follow** lists the people your Nostr key follows, with their names; tap one to write to them. See [Chats with other Nostr apps](#nostr-chats).":
    "**Menschen, denen du auf Nostr folgst**: In den Nostr-Chats listet **Menschen zeigen, denen du folgst**, unter Neuer Chat, die Menschen auf, denen dein Nostr-Schlüssel folgt, mit ihren Namen; tippe eine Person an, um ihr zu schreiben. Siehe [Chats mit anderen Nostr-Apps](#nostr-chats).",
  "**Who makes Erevos, and its licence**: About Erevos now names its maker, and every file of Erevos's source code says whose it is and under which licence; the AGPL-3.0 licence has three added terms (keep the maker's name, mark a changed version, give it another name). See [What Erevos is](#about).":
    "**Wer Erevos macht, und seine Lizenz**: Über Erevos nennt jetzt, wer es macht, und jede Datei des Quellcodes sagt, wem sie gehört und unter welcher Lizenz; die Lizenz AGPL-3.0 hat drei zusätzliche Bedingungen (den Namen des Urhebers behalten, eine geänderte Fassung als geändert kennzeichnen, ihr einen anderen Namen geben). Siehe [Was Erevos ist](#about).",
  // 4.0.0-rc.4
  "**Numbers on the home chips**: each chip above the chats (All messages, SMS, Erevos, Matrix, XMPP, Nostr) shows how many messages are not read in it, as a small number after its name; muted chats and groups are not counted. See [Getting started](#start).":
    "**Zahlen auf den Chips des Startbildschirms**: Jeder Chip über den Chats (Alle, SMS, Erevos, Matrix, XMPP, Nostr) zeigt als kleine Zahl hinter seinem Namen, wie viele Nachrichten darin ungelesen sind; stumme Chats und Gruppen zählen nicht mit. Siehe [Erste Schritte](#start).",
  "**Open a photo full screen in Matrix, XMPP and Nostr chats**: tap a photo shown in a Matrix, XMPP or Nostr chat to see it on the whole screen, with zoom, turning with the phone and Save, as in a chat with a contact. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Foto im Vollbild in Matrix-, XMPP- und Nostr-Chats**: Tippe in einem Matrix-, XMPP- oder Nostr-Chat auf ein gezeigtes Foto, um es auf dem ganzen Bildschirm zu sehen, mit Zoom, Drehen mit dem Telefon und Speichern wie im Chat mit einem Kontakt. Siehe [Matrix](#matrix), [XMPP](#xmpp) und [Chats mit anderen Nostr-Apps](#nostr-chats).",
  "**Who got and who read your messages in groups**: in a group that is not public, your messages show ✓, then ✓✓ once they reached the phone of every member, and ✓✓✓ once every one read them. Hold one and choose **Who read it** to see who read it and when, whose phone it reached and when, and who has neither yet. A member whose Erevos is older says nothing. A linked computer shows the same marks. See [Chat through a relay](#relay) and [Group chats](#groups).":
    "**Wer deine Nachrichten in Gruppen bekommen und gelesen hat**: In einer Gruppe, die nicht öffentlich ist, zeigen deine Nachrichten ✓, dann ✓✓, sobald sie auf dem Telefon jedes Mitglieds angekommen sind, und ✓✓✓, sobald alle sie gelesen haben. Halte eine gedrückt und wähle **Wer hat es gelesen**, um zu sehen, wer sie gelesen hat und wann, auf wessen Telefon sie angekommen ist und wann, und wer beides noch nicht getan hat. Ein Mitglied mit älterem Erevos sagt nichts. Ein verknüpfter Computer zeigt dieselben Markierungen. Siehe [Chat über ein Relay](#relay) und [Gruppenchats](#groups).",
  "**Who read your messages in Matrix**: your messages in a Matrix chat show ✓ once the Matrix server took them and ✓✓✓ once every other member read them, as their Matrix apps tell their servers; **Who read it**, on a message held down, lists who read it and when, and who has not. Matrix has no mark for a message that reached a phone, so there is no ✓✓. See [Matrix](#matrix).":
    "**Wer deine Nachrichten in Matrix gelesen hat**: Deine Nachrichten in einem Matrix-Chat zeigen ✓, sobald der Matrix-Server sie angenommen hat, und ✓✓✓, sobald alle anderen Mitglieder sie gelesen haben, so wie ihre Matrix-Apps es ihren Servern melden; **Wer hat es gelesen**, bei einer gedrückt gehaltenen Nachricht, listet auf, wer sie gelesen hat und wann und wer nicht. Matrix hat keine Markierung für eine Nachricht, die auf einem Telefon angekommen ist, also gibt es kein ✓✓. Siehe [Matrix](#matrix).",
  "**Quiet group messages for the marks**: the group message that says a message came or was read goes only to the senders concerned, and batched; after 300 such messages to some members only, the next goes to all, so no member falls behind in the phone's MLS keys (they accept a jump of 1000 at most). Groups let go of as their space closes send nothing more. See [Group chats](#groups).":
    "**Stille Gruppennachrichten für die Markierungen**: Die Gruppennachricht, die sagt, dass eine Nachricht angekommen ist oder gelesen wurde, geht nur an die betroffenen Absender und gebündelt; nach 300 solcher Nachrichten nur an einige Mitglieder geht die nächste an alle, damit kein Mitglied bei den MLS-Schlüsseln des Telefons zurückfällt (sie verkraften einen Sprung von höchstens 1000). Gruppen, die beim Schließen ihres Bereichs losgelassen werden, senden nichts mehr. Siehe [Gruppenchats](#groups).",
  // 4.0.0-rc.3
  "**Bold, italic, code and hidden words**: in chats and groups, words typed between * become bold, between _ italic, between ~ struck through, between ` code, and between || hidden behind a grey bar until tapped. See [Chat through a relay](#relay).":
    "**Fett, kursiv, Code und versteckte Worte**: In Chats und Gruppen werden Worte zwischen * fett, zwischen _ kursiv, zwischen ~ durchgestrichen, zwischen ` als Code und zwischen || hinter einem grauen Balken versteckt, bis du tippst. Siehe [Chat über ein Relay](#relay).",
  "**Hidden photo**: under + in a chat or a group, a photo that shows blurred until it is tapped. See [Chat through a relay](#relay).":
    "**Verstecktes Foto**: unter + in einem Chat oder einer Gruppe ein Foto, das verschwommen bleibt, bis du es antippst. Siehe [Chat über ein Relay](#relay).",
  "**Safety message**: under + in a chat, words to a contact that the relay sends by itself if you do not open Erevos for 6 hours to a week; each time you open it, they move on again. See [Chat through a relay](#relay).":
    "**Sicherheitsnachricht**: Unter + in einem Chat, Worte an einen Kontakt, die das Relay von selbst sendet, wenn du Erevos 6 Stunden bis eine Woche lang nicht öffnest; jedes Mal, wenn du es öffnest, werden sie wieder verschoben. Siehe [Chat über ein Relay](#relay).",
  "**Name a member in a group with @**: type @ and pick a member; they are told of the message even if they muted the group. See [Group chats](#groups).":
    "**Ein Mitglied in einer Gruppe mit @ nennen**: Tippe @ und wähle ein Mitglied; es erfährt von der Nachricht, auch wenn es die Gruppe stummgeschaltet hat. Siehe [Gruppenchats](#groups).",
  "**Reply, change, react and delete in XMPP chats**: hold a message in an XMPP chat or group to answer it, change your words, delete it for everyone or react with an emoji, as Conversations, Dino, Gajim, Monal and Kaidan do; and **typing…** shows while the other person writes. See [XMPP](#xmpp).":
    "**Antworten, ändern, reagieren und löschen in XMPP-Chats**: Halte eine Nachricht in einem XMPP-Chat oder einer Gruppe gedrückt, um sie zu beantworten, deinen Text zu ändern, sie für alle zu löschen oder mit einem Emoji zu reagieren, wie Conversations, Dino, Gajim, Monal und Kaidan es tun; und **schreibt…** erscheint, während die andere Person schreibt. Siehe [XMPP](#xmpp).",
  "**See who is writing in a Matrix chat**: **typing…** shows under a Matrix chat while someone writes in it, as the Matrix server says. It shows of you too only if you turn on **Say when I am writing** on the Matrix or XMPP screen: off at first, as it goes through the server not encrypted. See [Matrix](#matrix).":
    "**Sieh, wer in einem Matrix-Chat schreibt**: **schreibt…** steht unter einem Matrix-Chat, während jemand darin schreibt, wie der Matrix-Server es sagt. Von dir sehen es die anderen nur, wenn du **Sagen, wenn ich schreibe** auf dem Matrix- oder XMPP-Bildschirm einschaltest: anfangs aus, da es unverschlüsselt über den Server geht. Siehe [Matrix](#matrix).",
  "**Block someone on XMPP**: Block, at the bottom of an XMPP chat, keeps that person's messages, calls and requests from every app of your XMPP account; Unblock lets them through again. See [XMPP](#xmpp).":
    "**Jemanden bei XMPP blockieren**: Blockieren, unten in einem XMPP-Chat, hält Nachrichten, Anrufe und Anfragen dieser Person von jeder App deines XMPP-Kontos fern; Blockierung aufheben lässt sie wieder durch. Siehe [XMPP](#xmpp).",
  "**Voice messages in XMPP chats**: hold the microphone under an XMPP chat's message box to record, and let go to send; it goes encrypted as the chat is, as Conversations sends one. See [XMPP](#xmpp).":
    "**Sprachnachrichten in XMPP-Chats**: Halte das Mikrofon unter dem Nachrichtenfeld eines XMPP-Chats gedrückt, um aufzunehmen, und lass los, um zu senden; sie geht verschlüsselt wie der Chat, so wie Conversations sie sendet. Siehe [XMPP](#xmpp).",
  "**Matrix groups from Erevos**: New group, on the Matrix screen, makes an encrypted group with a name and the people you invite; Join a group joins one by its address; Invite, in a group, asks someone else in; typing @ in a group names a member, who is told of it. See [Matrix](#matrix).":
    "**Matrix-Gruppen aus Erevos**: Neue Gruppe, auf dem Matrix-Bildschirm, erstellt eine verschlüsselte Gruppe mit Namen und den Eingeladenen; Einer Gruppe beitreten tritt einer über ihre Adresse bei; Einladen, in einer Gruppe, holt jemand anderen dazu; mit @ nennst du in einer Gruppe ein Mitglied, das es erfährt. Siehe [Matrix](#matrix).",
  "**The panic button on a computer and on Sailfish OS**: Settings → Privacy and security → Panic button now wipes Erevos there too, with its automatic backups if you choose; on a computer it then starts again as new. See [Panic button](#panic).":
    "**Der Panikknopf auf einem Computer und unter Sailfish OS**: Einstellungen → Datenschutz und Sicherheit → Panikknopf löscht Erevos jetzt auch dort, auf Wunsch mit seinen automatischen Backups; auf einem Computer startet es danach wie neu. Siehe [Panikknopf](#panic).",
  "**Every chat opens at its latest message**: chats with contacts, groups and SMS, and the Matrix, XMPP and Nostr chats, all open at the last message with the message bar under it, and have round arrows to the start, to where you left off (the first message that was new when you opened it) and to the end. See [Getting started](#start).":
    "**Jeder Chat öffnet sich bei seiner letzten Nachricht**: Chats mit Kontakten, Gruppen und SMS sowie die Chats mit Matrix, XMPP und Nostr öffnen sich alle bei der letzten Nachricht, mit der Nachrichtenleiste darunter, und haben runde Pfeile zum Anfang, dorthin, wo du aufgehört hast (die erste Nachricht, die beim Öffnen neu war), und zum Ende. Siehe [Erste Schritte](#start).",
  "**The panic button says when it refused**: when your panic app asked to wipe Erevos while the switch was off, or signed with another key, the panic screen now says so, with the time. An app that moves to a new key the way Android allows stays trusted; otherwise you can trust it again as it is now. See [Panic button](#panic).":
    "**Der Panikknopf sagt, wann er abgelehnt hat**: Wenn deine Panik-App Erevos löschen wollte, während der Schalter aus war oder sie mit einem anderen Schlüssel signiert war, sagt die Panik-Seite es jetzt, mit der Uhrzeit. Eine App, die auf einen neuen Schlüssel wechselt, wie Android es erlaubt, bleibt vertrauenswürdig; sonst kannst du ihr erneut vertrauen, so wie sie jetzt ist. Siehe [Panikknopf](#panic).",
  "**The home screen's chips stay on one line**: with a Nostr, Matrix or XMPP chip as well, **Names** went to a line of its own and the chips moved. Now they stay on one line that slides to the side, and the chosen one is always in sight.":
    "**Die Chips des Startbildschirms bleiben in einer Zeile**: Mit einem Chip für Nostr, Matrix oder XMPP dazu rutschte **Namen** in eine eigene Zeile, und die Chips verschoben sich. Jetzt bleiben sie in einer Zeile, die sich zur Seite schieben lässt, und der gewählte ist immer zu sehen.",
  "**Screens come down when the keyboard is gone**: back from another app that had its keyboard open, the home screen's buttons (or a chat's field) could stay up where the keyboard had been, until a keyboard opened again. Now they come down within a second.":
    "**Bildschirme gehen nach unten, wenn die Tastatur weg ist**: Zurück aus einer anderen App mit offener Tastatur konnten die Knöpfe des Startbildschirms (oder das Feld eines Chats) oben bleiben, wo die Tastatur gewesen war, bis wieder eine Tastatur aufging. Jetzt gehen sie innerhalb einer Sekunde nach unten.",
  // 4.0.0-rc.2
  "**See what you type in a password or a PIN**: every field for a password, a PIN or a token has an eye at its end: tap it to see what you type, and again to hide it. It is hidden again the next time. See [Password lock](#lock).":
    "**Sieh, was du in ein Passwort oder eine PIN tippst**: Jedes Feld für ein Passwort, eine PIN oder ein Token hat am Ende ein Auge: Tippe darauf, um zu sehen, was du eingibst, und noch einmal, um es zu verbergen. Beim nächsten Mal ist es wieder verborgen. Siehe [Passwortsperre](#lock).",
  "**A chat read as it opens stays read**: messages read while their chat was still opening, as Erevos ended a look at the relay, showed as unread on the home screen once you went back. Now they are marked read as soon as they show.":
    "**Ein beim Öffnen gelesener Chat bleibt gelesen**: Nachrichten, die du gelesen hast, während sich ihr Chat noch öffnete, weil Erevos gerade beim Relay nachsah, standen auf dem Startbildschirm als ungelesen, sobald du zurückgingst. Jetzt gelten sie als gelesen, sobald sie zu sehen sind.",
  "**Link for a website**: under New chat → Your contact link, a link to put on a web page, such as your contact page. It opens a page that offers Erevos to whoever has none yet, then adds you; what they send comes as a message request. See [Chat through a relay](#relay).":
    "**Link für eine Website**: unter Neuer Chat → Dein Kontaktlink, ein Link für eine Webseite, etwa deine Kontaktseite. Er öffnet eine Seite, die Erevos jedem anbietet, der es noch nicht hat, und fügt dich dann hinzu; was jemand schickt, kommt als Nachrichtenanfrage. Siehe [Chat über ein Relay](#relay).",
  "**An update's download that stalls is tried again**: when the connection brings nothing for a while, Erevos starts the download again by itself, three times in all, and then says so in its own words. See [Updates](#updates).":
    "**Ein Update-Download, der hängen bleibt, wird neu versucht**: Bringt die Verbindung eine Weile nichts, beginnt Erevos den Download von selbst neu, insgesamt dreimal, und sagt es danach mit eigenen Worten. Siehe [Updates](#updates).",
  // 4.0.0-rc.1
  "**Pieces of photos through Nostr stay with their chats**: while a photo that comes through Nostr waits for the rest of its pieces, they are now kept encrypted with the space or the hidden chats they came for, no longer apart where they could be counted, so nothing outside a hidden chats' password says that a photo is on its way to them. Pieces kept before go to the first chats whose photo they are, or after four days. See [Through Nostr](#nostr).":
    "**Stücke von Fotos über Nostr bleiben bei ihren Chats**: Während ein Foto, das über Nostr kommt, auf seine übrigen Stücke wartet, werden sie jetzt verschlüsselt mit dem Bereich oder den versteckten Chats behalten, für die sie kamen, nicht mehr getrennt, wo man sie zählen könnte, sodass nichts außerhalb des Passworts versteckter Chats verrät, dass ein Foto zu ihnen unterwegs ist. Früher behaltene Stücke gehen zu den ersten Chats, deren Foto sie sind, oder nach vier Tagen. Siehe [Über Nostr](#nostr).",
  "**Encrypted SMS when nothing else works, if you choose**: on Android, when the relay, Nostr, the phones nearby and LoRa all fail, a text to an Erevos contact whose number is linked can go by SMS, end-to-end encrypted, hidden from their SMS app. Off until you turn it on, for all such contacts under Settings → Phone and SMS → SMS, or for one in a chat's Details. It costs SMS (3 for a short text, up to 10 for a longer one), and the phone company sees who wrote to whom, and when. Both phones need Erevos as the SMS app. See [SMS](#sms).":
    "**Verschlüsselte SMS, wenn sonst nichts geht, wenn du willst**: Auf Android kann ein Text an einen Erevos-Kontakt mit verknüpfter Nummer per SMS gehen, Ende-zu-Ende-verschlüsselt und vor seiner SMS-App verborgen, wenn Relay, Nostr, die Telefone in der Nähe und LoRa alle versagen. Aus, bis du es einschaltest: für alle solchen Kontakte unter Einstellungen → Telefon und SMS → SMS, oder für einen in den Details eines Chats. Es kostet SMS (3 für einen kurzen Text, bis zu 10 für einen längeren), und der Mobilfunkanbieter sieht, wer wem geschrieben hat, und wann. Beide Telefone brauchen Erevos als SMS-App. Siehe [SMS](#sms).",
  "**Answer a hidden call with Answer**: on the \"Incoming call\" screen with no name that a call to your hidden chats brings, **Answer** now asks for the PIN, as the small sign does, and the right PIN answers the call; before, it could not connect, and only the small sign could. See [Hidden chats](#hidden).":
    "**Einen versteckten Anruf mit Annehmen annehmen**: Auf dem Bildschirm „Eingehender Anruf“ ohne Namen, den ein Anruf an deine versteckten Chats bringt, fragt **Annehmen** jetzt nach der PIN, wie das kleine Zeichen, und die richtige PIN nimmt den Anruf an; vorher konnte es nicht verbinden, und nur das kleine Zeichen konnte es. Siehe [Versteckte Chats](#hidden).",
  "**Spam SMS come quietly**: on Android, an SMS that the spam filter's own words catch, a link with words that try to fool from a number that is no contact and that you never answered, still goes to Spam but no longer shows a notice or makes a sound. Spam by your own words and rules still shows one, as they stay encrypted in the space; with the Spam filter off, every SMS does. See [SMS](#sms).":
    "**Spam-SMS kommen still**: Auf Android geht eine SMS, die die eigenen Worte des Spamfilters fangen, ein Link mit Worten, die täuschen wollen, von einer Nummer, die kein Kontakt ist und der du nie geantwortet hast, weiter in Spam, zeigt aber keine Benachrichtigung mehr und macht keinen Ton. Spam durch deine eigenen Wörter und Regeln zeigt weiter eine, da sie verschlüsselt im Bereich bleiben; mit ausgeschaltetem Spamfilter zeigt jede SMS eine. Siehe [SMS](#sms).",
  '**What\'s new in two parts**: each version says first what changes for you, then what changed under the hood: fixes, speed, battery and security inside. See [Updates](#updates).':
    '**Was ist neu, in zwei Teilen**: Jede Version sagt zuerst, was sich für dich ändert, dann, was sich unter der Haube geändert hat: Korrekturen, Tempo, Akku und Sicherheit im Inneren. Siehe [Updates](#updates).',
  '**A contact\'s SMS no longer stay counted as new**: opening their chat reads all of them, the earlier ones too, not only those that show.':
    '**Die SMS eines Kontakts zählen nicht mehr weiter als neu**: sein Chat liest beim Öffnen alle, auch die früheren, nicht nur die angezeigten.',
  '**A message no longer waits when Tor cannot reach the relay**: with Tor for messages, it goes straight at once, as the Tor settings say. See [Through Tor](#tor).':
    '**Eine Nachricht wartet nicht mehr, wenn Tor das Relay nicht erreicht**: mit Tor für Nachrichten geht sie sofort direkt, wie es die Tor-Einstellungen sagen. Siehe [Über Tor](#tor).',
  '**Background notices no longer stop after a network change**: when the connection of a wait at the relay died on the way (Wi-Fi to mobile data, the relay restarting), Erevos took the relay for one from before, which cannot wait, for the whole run: contacts\' messages then came up to ten minutes late, and hidden chats, closed spaces and hidden rings said nothing until Erevos was restarted. See [Chat through a relay](#relay).':
    '**Hinweise im Hintergrund hören nach einem Netzwechsel nicht mehr auf**: starb die Verbindung eines Wartens am Relay unterwegs (von WLAN zu mobilen Daten, Neustart des Relays), hielt Erevos das Relay für den ganzen Lauf für ein altes, das nicht warten kann: Nachrichten von Kontakten kamen bis zu zehn Minuten später, und versteckte Chats, geschlossene Räume und versteckte Anrufe meldeten nichts mehr, bis Erevos neu gestartet wurde. Siehe [Chat über ein Relay](#relay).',
  '**A call hung up at once no longer rings**: when the hang-up came in the same look as the call, the phone rang 45 seconds for a call nobody was on; the same for a group call its starter left at once. See [Chat through a relay](#relay).':
    '**Ein sofort aufgelegter Anruf klingelt nicht mehr**: kam das Auflegen im selben Blick wie der Anruf, klingelte das Telefon 45 Sekunden für einen Anruf, in dem niemand war; ebenso bei einem Gruppenanruf, den sein Starter sofort verließ. Siehe [Chat über ein Relay](#relay).',
  '**A hidden call rings once**: a place with Receive while closed and a ring queue rang twice for one call, and a call taken while hidden chats were open rang again as they closed. See [Hidden chats](#hidden).':
    '**Ein versteckter Anruf klingelt einmal**: ein Ort mit Empfangen, wenn geschlossen und einer Klingel-Warteschlange klingelte zweimal für einen Anruf, und ein Anruf, der bei offenen versteckten Chats angenommen wurde, klingelte beim Schließen erneut. Siehe [Versteckte Chats](#hidden).',
  '**A member\'s contact link no longer says New message**: the answer to an ask from a group only adds the contact, with no notice. See [Group chats](#groups).':
    '**Der Kontaktlink eines Mitglieds meldet keine Neue Nachricht mehr**: die Antwort auf eine Bitte aus einer Gruppe fügt nur den Kontakt hinzu, ohne Hinweis. Siehe [Gruppenchats](#groups).',
  '**The birthday notice and the phone\'s incoming call no longer replace each other**: they had the same notice number. See [Contacts](#contacts).':
    '**Der Geburtstagshinweis und der eingehende Anruf des Telefons ersetzen einander nicht mehr**: sie hatten dieselbe Hinweisnummer. Siehe [Kontakte](#contacts).',
  '**A closed space tells of its contacts\' messages too**: since each contact writes to a queue of their own, a space that says a message came while another is open told only of group messages and first messages from new contacts. It now asks about its contacts\' queues too, up to 64. See [Chat through a relay](#relay).':
    '**Ein geschlossener Bereich meldet auch die Nachrichten seiner Kontakte**: Da jeder Kontakt in eine eigene Warteschlange schreibt, meldete ein Bereich, der sagt, dass eine Nachricht kam, während ein anderer offen ist, nur Gruppennachrichten und erste Nachrichten neuer Kontakte. Jetzt fragt er auch nach den Warteschlangen seiner Kontakte, bis zu 64. Siehe [Chat über ein Relay](#relay).',
  '**The user guide is in every language of the app**: it shows in the one you chose, and names the buttons as the app shows them. See [Language](#start).':
    '**Die Anleitung gibt es in jeder Sprache der App**: Sie erscheint in der, die du gewählt hast, und nennt die Tasten so, wie die App sie zeigt. Siehe [Sprache](#start).',
  '**Location finds where you are, indoors too**: the phone looks by satellite and by its network at once, a sheet says it is looking, and when nothing is found it says why, with Try again. See [Chat through a relay](#relay).':
    '**Standort findet dich, auch in Gebäuden**: das Telefon sucht per Satellit und über sein Netzwerk zugleich, ein Blatt sagt, dass es sucht, und wird nichts gefunden, sagt es warum, mit Erneut versuchen. Siehe [Chat über ein Relay](#relay).',
  '**The web app\'s icon counts what is not read**: on an iPhone, with notifications on for the space, Erevos\'s icon on the home screen shows how many messages are not read, never a hidden chat\'s, unless turned off under Settings → Notifications → Number on the icon. See [On an iPhone](#iphone).':
    '**Das Symbol der Web-App zählt, was ungelesen ist**: auf einem iPhone, mit eingeschalteten Benachrichtigungen für den Bereich, zeigt das Symbol von Erevos auf dem Home-Bildschirm, wie viele Nachrichten ungelesen sind, nie die eines versteckten Chats, außer du schaltest es unter Einstellungen → Benachrichtigungen → Zahl auf dem Symbol aus. Siehe [Auf einem iPhone](#iphone).',
  "**Notifications for each chat**: on Android, mute a chat or a group for 8 hours, a week or always, and give its messages and its calls a sound of their own, or none. See [Chat through a relay](#relay).":
    "**Benachrichtigungen für jeden Chat**: Auf Android schalte einen Chat oder eine Gruppe für 8 Stunden, eine Woche oder immer stumm, und gib seinen Nachrichten und Anrufen einen eigenen Ton, oder keinen. Siehe [Chat über ein Relay](#relay).",
  "**A chat locked with its own PIN stays locked**: when its contact's Erevos started a new conversation, as it does about once a month, the chat lost its PIN, and a public group joined again lost its own. See [Hidden chats](#hidden).":
    "**Ein Chat mit eigener PIN bleibt gesperrt**: Begann das Erevos des Kontakts eine neue Unterhaltung, wie es etwa einmal im Monat geschieht, verlor der Chat seine PIN, und eine öffentliche Gruppe, der du wieder beigetreten bist, verlor ihre. Siehe [Versteckte Chats](#hidden).",
  "**Erevos's icon keeps the number of messages not read, on Android**: leaving Erevos with messages not read, a notice without sound keeps how many until you read them, and the launcher shows it on the icon, as a number or a dot. Settings → Notifications → Number on the icon turns it off. See [Chat through a relay](#relay).":
    "**Das Symbol von Erevos behält die Zahl ungelesener Nachrichten, auf Android**: Verlässt du Erevos mit ungelesenen Nachrichten, hält eine Meldung ohne Ton fest, wie viele es sind, bis du sie liest, und der Launcher zeigt sie am Symbol, als Zahl oder Punkt. Einstellungen → Benachrichtigungen → Zahl auf dem Symbol schaltet das aus. Siehe [Chat über ein Relay](#relay).",
  "**The web app's notifications, more dependable**: no New message over Erevos while it is open, and a push held back while the phone was offline no longer counts messages you already read (both with your relay updated), every notice sounds in Chrome, Firefox and Edge, they come back by themselves when the browser changes its push address, and Notifications while closed says when the browser blocks them or your relay was not told yet that they are off. See [On an iPhone](#iphone).":
    "**Die Benachrichtigungen der Web-App, verlässlicher**: keine „Neue Nachricht“ über dem offenen Erevos, und ein Push, der zurückgehalten wurde, während das Telefon offline war, zählt keine Nachrichten mehr, die du schon gelesen hast (beides mit aktualisiertem Relay), jeder Hinweis macht in Chrome, Firefox und Edge einen Ton, sie kommen von selbst zurück, wenn der Browser seine Push-Adresse ändert, und „Benachrichtigungen, wenn geschlossen“ sagt, wenn der Browser sie blockiert oder dein Relay noch nicht erfahren hat, dass sie aus sind. Siehe [Auf einem iPhone](#iphone).",
  "**Calls ring in the web app, on the computer and on Sailfish OS**: a call that comes while Erevos is open now rings, where only its screen showed, and vibrates where the phone can. On an iPhone it rings once you have touched Erevos, and not on silent. See [On an iPhone](#iphone).":
    "**Anrufe klingeln in der Web-App, auf dem Computer und auf Sailfish OS**: Ein Anruf, der kommt, während Erevos offen ist, klingelt jetzt, wo bisher nur sein Bildschirm erschien, und vibriert, wo das Telefon es kann. Auf einem iPhone klingelt er, sobald du Erevos berührt hast, und nicht im Stummmodus. Siehe [Auf einem iPhone](#iphone).",
  '**Erevos on a computer keeps running with its window closed**: in the system tray (on a Mac, in the Dock) it goes on receiving, a call rings and brings the window back, and a notification says how many messages are not read, never who or what. Turn it off under Settings → Notifications → In the background. See [On a computer](#desktop).':
    '**Erevos auf dem Computer läuft mit geschlossenem Fenster weiter**: Im Infobereich (auf einem Mac im Dock) empfängt es weiter, ein Anruf klingelt und holt das Fenster zurück, und eine Benachrichtigung sagt, wie viele Nachrichten ungelesen sind, nie von wem oder was. Abschalten unter Einstellungen → Benachrichtigungen → Im Hintergrund. Siehe [Auf einem Computer](#desktop).',
  "**Erevos on Sailfish OS tells of messages and calls while it is closed**: while it is out of sight or closed, a small helper waits at the relay for the open space, a notification says how many messages came, never who or what, and a call rings with the phone's ringtone. See [On Sailfish OS](#sailfish).":
    "**Erevos unter Sailfish OS meldet Nachrichten und Anrufe, während es geschlossen ist**: Solange es nicht zu sehen oder geschlossen ist, wartet ein kleiner Helfer auf dem Relay für den offenen Raum, eine Mitteilung sagt, wie viele Nachrichten kamen, nie von wem oder was, und ein Anruf klingelt mit dem Klingelton des Telefons. Siehe [Unter Sailfish OS](#sailfish).",
  "**The relay's pushes to the web app, sturdier**: a push the push service could not take just then is sent again, a call goes before the messages waiting their turn, and whoever runs the relay can allow another push service. Your relay needs an update for it.":
    "**Die Pushes des Relays an die Web-App, robuster**: Ein Push, den der Push-Dienst gerade nicht annehmen konnte, wird erneut gesendet, ein Anruf geht vor den Nachrichten, die warten, bis sie an der Reihe sind, und wer das Relay betreibt, kann einen anderen Push-Dienst zulassen. Dein Relay braucht dafür ein Update.",
  "**Permissions checks every notice Erevos uses**: on Android, the message notice without sound or with a chat's own sound, and the reminders', turned off, now show there, with a button to each. See [Chat through a relay](#relay).":
    "**Berechtigungen prüft jede Benachrichtigung, die Erevos nutzt**: Auf Android erscheinen dort jetzt die Nachrichten-Benachrichtigung ohne Ton oder mit dem eigenen Ton eines Chats und die der Erinnerungen, wenn sie ausgeschaltet sind, jeweils mit einer Taste dorthin. Siehe [Chat über ein Relay](#relay).",
  '**Hidden chats say what their switches need**: Say when a message comes and Ring calls when closed say so when Settings → Notifications → In the background lets them do nothing. See [Hidden chats](#hidden).':
    '**Versteckte Chats sagen, was ihre Schalter brauchen**: „Melden, wenn eine Nachricht kommt“ und „Klingeln bei Anrufen, wenn geschlossen“ sagen es, wenn Einstellungen → Benachrichtigungen → Im Hintergrund sie nichts tun lässt. Siehe [Versteckte Chats](#hidden).',
  "**Truer words about notices**: Settings and the guide give the notices' own words and say what each one needs. See [Chat through a relay](#relay).":
    "**Genauere Worte über Benachrichtigungen**: Die Einstellungen und die Anleitung geben den eigenen Wortlaut der Benachrichtigungen wieder und sagen, was jede braucht. Siehe [Chat über ein Relay](#relay).",
  "**Calls ring as they should**: with Do Not Disturb only when their notice may break through, with a phone's clock off too once the relay is updated, and to the end on Android 7 and 8; a second call is told busy, and a ring stops only for its own call. See [Chat through a relay](#relay).":
    "**Anrufe klingeln, wie sie sollen**: bei Nicht stören nur, wenn ihre Benachrichtigung durchdringen darf, auch bei falsch gehender Uhr eines Telefons, sobald das Relay aktualisiert ist, und bis zum Ende auf Android 7 und 8; ein zweiter Anruf bekommt „besetzt“, und ein Klingeln endet nur für seinen eigenen Anruf. Siehe [Chat über ein Relay](#relay).",
  '**Hidden calls**: one turned down no longer leaves Erevos over the lock screen, one that comes while the password screen shows comes over it, and none rings twice. See [Hidden chats](#hidden).':
    '**Versteckte Anrufe**: Ein abgelehnter lässt Erevos nicht mehr über dem Sperrbildschirm zurück, einer, der kommt, während der Passwortbildschirm zu sehen ist, erscheint darüber, und keiner klingelt zweimal. Siehe [Versteckte Chats](#hidden).',
  '**Notices come again at once after a change of network**, and receiving starts again as Erevos shows when Android refused it. See [Chat through a relay](#relay).':
    '**Benachrichtigungen kommen nach einem Netzwechsel sofort wieder**, und das Empfangen startet wieder, sobald Erevos sichtbar ist, wenn Android es verweigert hatte. Siehe [Chat über ein Relay](#relay).',
  "**Hidden chats' notices tell each message once**: what came since a place last looked is told as it closes, a call that rang is not told again as a message, and a place whose queue the relay lost keeps its switch on. See [Hidden chats](#hidden).":
    "**Die Benachrichtigungen versteckter Chats melden jede Nachricht einmal**: Was kam, seit ein Platz zuletzt nachgesehen hat, wird gemeldet, wenn er sich schließt, ein Anruf, der geklingelt hat, wird nicht noch einmal als Nachricht gemeldet, und ein Platz, dessen Warteschlange das Relay verloren hat, behält seinen Schalter an. Siehe [Versteckte Chats](#hidden).",
  '**Hidden chats close while Erevos is away**, after 30 seconds, so a call to them meanwhile rings with their PIN to answer. See [Hidden chats](#hidden).':
    '**Versteckte Chats schließen sich, während Erevos weg ist**, nach 30 Sekunden, sodass ein Anruf an sie in der Zwischenzeit klingelt und mit ihrer PIN angenommen wird. Siehe [Versteckte Chats](#hidden).',
  '**A voice message counts once**, on its last part, also when it goes again whole.':
    '**Eine Sprachnachricht zählt einmal**, bei ihrem letzten Teil, auch wenn sie noch einmal ganz geht.',
  '**The number on the icon counts only what is still there**: a message deleted for everyone, or read on a linked computer, no longer counts. See [Chat through a relay](#relay).':
    '**Die Zahl auf dem Symbol zählt nur, was noch da ist**: Eine Nachricht, die für alle gelöscht oder auf einem verknüpften Computer gelesen wurde, zählt nicht mehr. Siehe [Chat über ein Relay](#relay).',
  '**Messages sent for later** tell of themselves only while their space is open, without sound if sent so.':
    '**Für später gesendete Nachrichten** melden sich nur, solange ihr Bereich offen ist, ohne Ton, wenn sie so gesendet wurden.',
  '**SMS**: one to the chat on screen only sounds there, they are marked read only while their screen shows, and Android names their notices SMS. See [SMS](#sms).':
    '**SMS**: Eine an den Chat auf dem Bildschirm gibt nur dort einen Ton, sie werden nur als gelesen markiert, solange ihr Bildschirm sichtbar ist, und Android nennt ihre Benachrichtigungen SMS. Siehe [SMS](#sms).',
  "**Reminders**: one seen in Chat with myself goes from the notice, a hidden place's go with a new PIN, and birthdays come at 9:00. See [Getting started](#start).":
    "**Erinnerungen**: Eine, die im Chat mit mir selbst gesehen wurde, verschwindet aus der Benachrichtigung, die eines versteckten Platzes gehen mit einer neuen PIN, und Geburtstage kommen um 9:00. Siehe [Erste Schritte](#start).",
  '**Nostr reads as soon as Tor is ready.** See [Through Nostr](#nostr).':
    '**Nostr liest, sobald Tor bereit ist.** Siehe [Über Nostr](#nostr).',
  "**Erevos's notices show its mark** in the status bar.":
    "**Die Benachrichtigungen von Erevos zeigen sein Zeichen** in der Statusleiste.",
  '**Notices are asked for with receiving off too**, when Say a message came is on.':
    '**Die Erlaubnis für Benachrichtigungen wird auch bei ausgeschaltetem Empfangen erbeten**, wenn „Neue Nachrichten melden“ an ist.',
  "**Photos open on the whole screen**: tap one to see it edge to edge, zoom in with two fingers or a double tap, and tap again to hide or show what is around it; big photos open as small ones do. Erevos also turns with the phone while the phone's Auto-rotate is on, and a photo shown on its own even when it is off. See [Chat through a relay](#relay).":
    '**Fotos öffnen sich auf dem ganzen Bildschirm**: Tippe auf eines, um es randlos zu sehen, zoome mit zwei Fingern oder zweimal Tippen hinein, und tippe noch einmal, um aus- oder einzublenden, was darum ist; große Fotos öffnen sich wie kleine. Erevos dreht sich auch mit dem Telefon, solange dort Automatisch drehen an ist, und ein allein gezeigtes Foto auch, wenn es aus ist. Siehe [Chat über ein Relay](#relay).',
  "**Matrix accounts in Erevos**: sign a space in to Matrix and chat with people who use Element or another Matrix app, end-to-end encrypted, under Settings → Relay and networks → Matrix. These chats are not anonymous, and say so: the Matrix server sees who talks with whom. Text, photos and files. See [Matrix](#matrix).":
    "**Matrix-Konten in Erevos**: Melde einen Bereich bei Matrix an und chatte Ende-zu-Ende-verschlüsselt mit Menschen, die Element oder eine andere Matrix-App nutzen, unter Einstellungen → Relay und Netze → Matrix. Diese Chats sind nicht anonym und sagen es: Der Matrix-Server sieht, wer mit wem spricht. Text, Fotos und Dateien. Siehe [Matrix](#matrix).",
  "**Every network's chats on the home screen**: once you sign in to Matrix, its chats are in the list with the Erevos chats and the SMS, newest first, each marked Matrix, and the Matrix chip shows them alone, as SMS and Erevos do. See [Matrix](#matrix).":
    "**Die Chats aller Netze auf dem Startbildschirm**: Sobald du dich bei Matrix anmeldest, stehen seine Chats mit den Erevos-Chats und den SMS in der Liste, die neuesten zuerst, jeder mit Matrix markiert, und der Chip Matrix zeigt nur sie, wie SMS und Erevos. Siehe [Matrix](#matrix).",
  '**Test versions before a release**: Erevos reads a version such as 4.0.0-rc.1, a test version that comes before 4.0.0, when it looks for updates, tells of a new version and shows what is new. See [Updates](#updates).':
    '**Testversionen vor einer Version**: Erevos liest eine Version wie 4.0.0-rc.1, eine Testversion, die vor 4.0.0 kommt, wenn es nach Updates sucht, eine neue Version meldet und zeigt, was neu ist. Siehe [Updates](#updates).',
  "**Check Matrix devices by emoji**: in a chat with one person on Matrix, Check by emoji shows you both seven pictures; if they match, nobody sits in between, and Element sees the check too. Check this device with another of yours makes your own Element trust Erevos. See [Matrix](#matrix).":
    "**Matrix-Geräte per Emoji prüfen**: In einem Chat mit einer Person auf Matrix zeigt Per Emoji prüfen euch beiden sieben Bilder; stimmen sie überein, sitzt niemand dazwischen, und auch Element sieht die Prüfung. Dieses Gerät mit einem anderen von dir prüfen lässt dein eigenes Element Erevos vertrauen. Siehe [Matrix](#matrix).",
  "**Automatic backups to your own server too**: on Android, each automatic backup can also go to a folder on a server you choose, such as your Nextcloud, over WebDAV. Off until you add one. The server gets random bytes under a random name and cannot open them; it still sees your account, your address and when. See [Backups](#backup).":
    "**Automatische Backups auch auf deinen eigenen Server**: Auf Android kann jedes automatische Backup auch in einen Ordner auf einem Server deiner Wahl gehen, etwa deiner Nextcloud, über WebDAV. Aus, bis du einen hinzufügst. Der Server bekommt zufällige Bytes unter einem zufälligen Namen und kann sie nicht öffnen; er sieht aber dein Konto, deine Adresse und wann. Siehe [Backups](#backup).",
  "**Matrix Security Key and key backup**: enter the Security Key Element made, under Settings → Relay and networks → Matrix, and earlier messages open, new keys are backed up, and your other devices trust Erevos. An account with none can set one up there. See [Matrix](#matrix).":
    "**Matrix-Sicherheitsschlüssel und Schlüsselsicherung**: Gib den Sicherheitsschlüssel, den Element erstellt hat, unter Einstellungen → Relay und Netze → Matrix ein, und frühere Nachrichten öffnen sich, neue Schlüssel werden gesichert, und deine anderen Geräte vertrauen Erevos. Ein Konto ohne kann dort einen einrichten. Siehe [Matrix](#matrix).",
  "**Matrix through Tor**: on Android, a space's Matrix account follows its choice under Settings → Relay and networks → Tor, so the Matrix server no longer sees where you are; the Matrix screen says when it goes through Tor. See [Matrix](#matrix).":
    "**Matrix über Tor**: Auf Android folgt das Matrix-Konto eines Bereichs dessen Wahl unter Einstellungen → Relay und Netze → Tor, sodass der Matrix-Server nicht mehr sieht, wo du bist; der Matrix-Bildschirm sagt, wann es über Tor geht. Siehe [Matrix](#matrix).",
  "**XMPP accounts in Erevos**: sign a space in to XMPP, under Settings → Relay and networks → XMPP, and chat with people who use Conversations, Monal, Gajim, Dino or another XMPP app, encrypted with OMEMO. These chats are not anonymous, and say so: the XMPP server sees who talks with whom. Text with delivery and read marks, photos and files, in the home list under an XMPP chip of its own, and through Tor on Android as you chose. See [XMPP](#xmpp).":
    "**XMPP-Konten in Erevos**: Melde einen Bereich bei XMPP an, unter Einstellungen → Relay und Netze → XMPP, und chatte mit Menschen, die Conversations, Monal, Gajim, Dino oder eine andere XMPP-App nutzen, verschlüsselt mit OMEMO. Diese Chats sind nicht anonym und sagen es: Der XMPP-Server sieht, wer mit wem spricht. Text mit Zustell- und Lesemarkierungen, Fotos und Dateien, in der Liste auf dem Startbildschirm unter einem eigenen XMPP-Chip, und auf Android über Tor, wie du es gewählt hast. Siehe [XMPP](#xmpp).",
  "**Voice and video calls with people on XMPP**: the two tiles at the top of an XMPP chat call the person, and their calls ring on the same screen as Erevos's own, with apps that call as Conversations does. The call goes through your call relay or the XMPP server's, so they do not learn your address; the key that proves it passes through the XMPP servers, which could put themselves in between. See [XMPP](#xmpp).":
    "**Sprach- und Videoanrufe mit Menschen auf XMPP**: Die zwei Kacheln oben in einem XMPP-Chat rufen die Person an, und ihre Anrufe klingeln auf demselben Bildschirm wie Erevos' eigene, mit Apps, die so anrufen wie Conversations. Der Anruf geht über dein Anruf-Relay oder das des XMPP-Servers, sodass sie deine Adresse nicht erfährt; der Schlüssel, der ihn belegt, geht über die XMPP-Server, die sich dazwischenschalten könnten. Siehe [XMPP](#xmpp).",
  "**Voice and video calls with people on Matrix**: on Android, the two tiles at the top of a Matrix chat call with Element Call, the call app of Element and Element X, which opens inside Erevos in a window of its own, and their calls ring here as Erevos's own do. Sound and picture are end-to-end encrypted and go through the media server your Matrix server names, never through Tor. See [Matrix](#matrix).":
    "**Sprach- und Videoanrufe mit Menschen auf Matrix**: Auf Android rufen die zwei Kacheln oben in einem Matrix-Chat mit Element Call an, der Anruf-App von Element und Element X, die sich in Erevos in einem eigenen Fenster öffnet, und ihre Anrufe klingeln hier wie Erevos' eigene. Ton und Bild sind Ende-zu-Ende-verschlüsselt und gehen über den Medienserver, den dein Matrix-Server nennt, nie über Tor. Siehe [Matrix](#matrix).",
  "**Voice and video calls with people on Matrix, in the web app and on a computer**: the two tiles at the top of a Matrix chat call with Element Call there too, as on Android, over the app; its back arrow makes it small in a corner, so you can keep using Erevos during the call. Element Call runs apart from Erevos and can read nothing of it. See [Matrix](#matrix).":
    "**Sprach- und Videoanrufe mit Menschen auf Matrix, in der Web-App und auf einem Computer**: Die zwei Kacheln oben in einem Matrix-Chat rufen auch dort mit Element Call an, wie auf Android, in einem Fenster über der App; der Zurück-Pfeil darin verkleinert es in eine Ecke, sodass du Erevos während des Anrufs weiter benutzen kannst. Element Call läuft getrennt von Erevos und kann nichts davon lesen. Siehe [Matrix](#matrix).",
  "**Chats with people on other Nostr apps**: give a space a Nostr key of its own, under Settings → Relay and networks → Nostr chats, and chat with people who use Damus, Amethyst, Primal, 0xchat or another Nostr app, one to one or in groups, encrypted as NIP-17 asks: the relays see whom a message is for, not who wrote it. These chats are not anonymous, and say so: your key is the same to everyone you write to. Text, photos, files and reactions, in the home list under a Nostr chip of its own, and through Tor on Android as you chose. See [Chats with other Nostr apps](#nostr-chats).":
    "**Chats mit Menschen in anderen Nostr-Apps**: Gib einem Bereich einen eigenen Nostr-Schlüssel, unter Einstellungen → Relay und Netze → Nostr-Chats, und chatte mit Menschen, die Damus, Amethyst, Primal, 0xchat oder eine andere Nostr-App nutzen, zu zweit oder in Gruppen, verschlüsselt nach NIP-17: Die Relays sehen, für wen eine Nachricht ist, nicht wer sie schrieb. Diese Chats sind nicht anonym und sagen es: Dein Schlüssel ist für alle gleich, denen du schreibst. Text, Fotos, Dateien und Reaktionen, in der Liste des Startbildschirms unter einem eigenen Nostr-Chip, und auf Android über Tor, wie du es gewählt hast. Siehe [Chats mit anderen Nostr-Apps](#nostr-chats).",
  "**Notices for Matrix, XMPP and Nostr messages**: a message in a chat on Matrix, XMPP or Nostr shows a notice and counts in the number on Erevos's icon, as in Erevos's own chats. On Android, Notifications at the bottom of such a chat mutes it or gives it a sound of its own, and an XMPP or Matrix call rings with its chat's ringtone. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Mitteilungen für Nachrichten auf Matrix, XMPP und Nostr**: Eine Nachricht in einem Chat auf Matrix, XMPP oder Nostr zeigt eine Mitteilung und zählt zur Zahl auf dem Symbol von Erevos, wie in Erevos’ eigenen Chats. Auf Android schaltet Benachrichtigungen unten in so einem Chat ihn stumm oder gibt ihm einen eigenen Ton, und ein XMPP- oder Matrix-Anruf klingelt mit dem Klingelton seines Chats. Siehe [Matrix](#matrix), [XMPP](#xmpp) und [Chats mit anderen Nostr-Apps](#nostr-chats).",
  "**A closed space tells of Matrix messages**: on Android, Say a message came under While this space is closed, on the Matrix screen, has a closed space say \"New message\" when something comes on Matrix while another space is open, never what, from whom or in which chat. Off until you choose it. The Matrix server then tells the space's relay of each message, with no words in it: it learns the relay's address, and the relay when messages come. See [Matrix](#matrix).":
    "**Ein geschlossener Bereich meldet Matrix-Nachrichten**: Auf Android lässt „Neue Nachrichten melden“ unter „Solange dieser Bereich geschlossen ist“ auf dem Matrix-Bildschirm einen geschlossenen Bereich „Neue Nachricht“ sagen, wenn auf Matrix etwas kommt, während ein anderer Bereich offen ist, nie was, von wem oder in welchem Chat. Aus, bis du es wählst. Der Matrix-Server meldet dann dem Relay des Bereichs jede Nachricht, ohne ein Wort daraus: Er erfährt die Adresse des Relays, und das Relay, wann Nachrichten kommen. Siehe [Matrix](#matrix).",
  "**Made with others' open source**: About Erevos, and the guide, now name the open-source projects Erevos is built on, with their makers and their licences. See [What Erevos is](#about).":
    "**Mit der Open-Source-Arbeit anderer gebaut**: Unter „Über Erevos“ und in der Anleitung stehen jetzt die Open-Source-Projekte, auf denen Erevos aufbaut, mit ihren Machern und ihren Lizenzen. Siehe [Was Erevos ist](#about).",
  "**Groups on XMPP**: under Settings → Relay and networks → XMPP, make a private group with your contacts, encrypted with OMEMO for every member as Conversations' private groups are, or join a group by its address, and answer invitations to groups. A group that is not private, a channel, is not encrypted, and says so. Your groups follow your account's other XMPP apps, and a channel tells only of messages that name you. See [XMPP](#xmpp).":
    "**Gruppen auf XMPP**: Unter Einstellungen → Relay und Netze → XMPP erstellst du eine private Gruppe mit deinen Kontakten, für jedes Mitglied mit OMEMO verschlüsselt wie die privaten Gruppen von Conversations, oder trittst einer Gruppe über ihre Adresse bei und beantwortest Einladungen in Gruppen. Eine Gruppe, die nicht privat ist, ein Kanal, ist nicht verschlüsselt und sagt das. Deine Gruppen folgen den anderen XMPP-Apps deines Kontos, und ein Kanal meldet nur Nachrichten, die deinen Namen nennen. Siehe [XMPP](#xmpp).",
  "**More in Matrix chats**: hold a message to react to it, reply to it, copy it and, if it is yours, edit it or delete it for everyone. Load earlier messages brings in older ones, and the microphone under the message box sends voice messages that Element plays too. Reactions are not encrypted, as Element sends them. See [Matrix](#matrix).":
    "**Mehr in Matrix-Chats**: Halte eine Nachricht gedrückt, um auf sie zu reagieren, ihr zu antworten, sie zu kopieren und, wenn sie von dir ist, sie zu bearbeiten oder für alle zu löschen. „Frühere Nachrichten laden“ holt ältere herein, und das Mikrofon unter dem Nachrichtenfeld sendet Sprachnachrichten, die auch Element abspielt. Reaktionen sind nicht verschlüsselt, wie Element sie sendet. Siehe [Matrix](#matrix).",
  "**Video added to an XMPP call**: in a voice call with someone on XMPP, either of you can turn on video with Add video; the other is asked first and can say Not now. It works with apps that add video to a call as Conversations does. See [XMPP](#xmpp).":
    "**Video in einem XMPP-Anruf dazuschalten**: In einem Sprachanruf mit jemandem auf XMPP kann jeder von euch mit „Video dazu“ Video einschalten; die andere Person wird zuerst gefragt und kann „Nicht jetzt“ sagen. Es funktioniert mit Apps, die Video zu einem Anruf hinzufügen wie Conversations. Siehe [XMPP](#xmpp).",
  "**Voice messages and replies in Nostr chats**: hold the microphone under the message box to send a voice message, which plays with Play; hold a message to reply to it, and the answer shows the message it is to, here and in other Nostr apps. See [Chats with other Nostr apps](#nostr-chats).":
    "**Sprachnachrichten und Antworten in Nostr-Chats**: Halte das Mikrofon unter dem Nachrichtenfeld gedrückt, um eine Sprachnachricht zu senden, die mit „Abspielen“ läuft; halte eine Nachricht gedrückt, um ihr zu antworten, und die Antwort zeigt die Nachricht, auf die sie antwortet, hier und in anderen Nostr-Apps. Siehe [Chats mit anderen Nostr-Apps](#nostr-chats).",
  "**OMEMO 2 in XMPP chats**: a message to someone whose app speaks OMEMO 2, as Kaidan does, now goes with OMEMO 2 to that app and with OMEMO 0.3 to their others, as before. The XMPP screen shows this device's key both ways, to compare with what each app shows. See [XMPP](#xmpp).":
    "**OMEMO 2 in XMPP-Chats**: Eine Nachricht an jemanden, dessen App OMEMO 2 spricht, wie Kaidan, geht jetzt mit OMEMO 2 an diese App und mit OMEMO 0.3 an die anderen Apps der Person, wie bisher. Der XMPP-Bildschirm zeigt den Schlüssel dieses Geräts auf beide Arten, zum Vergleich mit dem, was jede App zeigt. Siehe [XMPP](#xmpp).",
  "**Hidden chats can have their own Matrix, XMPP and Nostr accounts**: under the list of a place of hidden chats, Matrix, XMPP and Nostr open an account of that place alone, apart from the space's, kept encrypted with the hidden chats' key. Its chats show among the hidden chats only. It connects while they are open, and while they are closed too if Receive while closed is on, as the hidden chats do: then a message says only \"New message\", and a call rings with no name and is answered with the PIN. See [Hidden chats](#hidden).":
    "**Versteckte Chats können eigene Matrix-, XMPP- und Nostr-Konten haben**: Unter der Liste eines Platzes mit versteckten Chats öffnen Matrix, XMPP und Nostr ein Konto nur dieses Platzes, getrennt von dem des Bereichs und mit dem Schlüssel der versteckten Chats verschlüsselt aufbewahrt. Seine Chats stehen nur unter den versteckten Chats. Es verbindet sich, solange diese offen sind, und auch, solange sie geschlossen sind, wenn „Empfangen, wenn geschlossen“ eingeschaltet ist, wie es die versteckten Chats selbst tun: Dann sagt eine Nachricht nur „Neue Nachricht“, und ein Anruf klingelt ohne Namen und wird mit der PIN angenommen. Siehe [Versteckte Chats](#hidden).",
  "**Matrix, XMPP and Nostr in backups**: a backup now holds the Matrix, XMPP and Nostr accounts of every space and of its hidden chats. After a restore, a Nostr key comes back with its chats as they were; an XMPP account goes on as a new device of the account, with its contacts and chats; a Matrix account is let go of on this phone, and the space signs in again as a new device; its Security Key opens the messages from before. See [Backups](#backup).":
    "**Matrix, XMPP und Nostr in Backups**: Ein Backup enthält jetzt die Matrix-, XMPP- und Nostr-Konten jedes Bereichs und seiner versteckten Chats. Nach einer Wiederherstellung kommt ein Nostr-Schlüssel mit seinen Chats zurück, so wie er war; ein XMPP-Konto geht als neues Gerät des Kontos weiter, mit seinen Kontakten und Chats; ein Matrix-Konto wird auf diesem Telefon aufgegeben, und der Bereich meldet sich als neues Gerät neu an; sein Sicherheitsschlüssel öffnet die Nachrichten von früher. Siehe [Backups](#backup).",
  "**Matrix voice messages show their waveform, and Nostr answers can be photos**: a voice message sent in a Matrix chat carries its waveform, which Element draws, and one that comes with a waveform shows it under Play; in a Nostr chat, a photo, file or voice message sent while a message shows over the message box answers it. See [Matrix](#matrix) and [Chats with other Nostr apps](#nostr-chats).":
    "**Matrix-Sprachnachrichten zeigen ihre Wellenform, und Nostr-Antworten können Fotos sein**: Eine Sprachnachricht, die du in einem Matrix-Chat sendest, trägt ihre Wellenform, die Element zeichnet, und eine, die mit Wellenform ankommt, zeigt sie unter Abspielen; in einem Nostr-Chat beantwortet ein Foto, eine Datei oder eine Sprachnachricht die Nachricht, die gerade über dem Nachrichtenfeld steht. Siehe [Matrix](#matrix) und [Chats mit anderen Nostr-Apps](#nostr-chats).",
  "**Group calls in XMPP groups**: in a private XMPP group, start a voice or video call, answer one that rings, or join one going on, together with people who use Dino. See [XMPP](#xmpp).":
    "**Gruppenanrufe in XMPP-Gruppen**: Starte in einer privaten XMPP-Gruppe einen Sprach- oder Videoanruf, nimm einen an, der klingelt, oder tritt einem laufenden bei, zusammen mit Menschen, die Dino nutzen. Siehe [XMPP](#xmpp).",
  '**A call to a slow phone rings in full**: the caller now waits up to a minute and a quarter for the other phone to say it rings, and then 45 seconds from then, so a call that reached it late no longer rings there only to stop at once; and the phone called reads a call before anything it has to send, and waits for calls again at once after its network changes. See [Chat through a relay](#relay).':
    '**Ein Anruf bei einem langsamen Telefon klingelt voll**: Wer anruft, wartet jetzt bis zu eineinviertel Minuten, bis das andere Telefon sagt, dass es klingelt, und dann 45 Sekunden ab da, sodass ein Anruf, der spät dort ankam, nicht mehr klingelt, nur um sofort aufzuhören; und das angerufene Telefon liest einen Anruf vor allem, was es zu senden hat, und wartet nach einem Netzwechsel sofort wieder auf Anrufe. Siehe [Chat über ein Relay](#relay).',
  "**The web app and the computer reach Matrix, XMPP and Nostr servers over HTTPS**: their page policy allowed only WebSocket connections, so Matrix sign-in, XMPP server discovery and file sharing, and Nostr files and name lookups failed there. They work now. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Die Web-App und der Computer erreichen Matrix-, XMPP- und Nostr-Server über HTTPS**: Die Sicherheitsrichtlinie ihrer Seite erlaubte nur WebSocket-Verbindungen, darum gingen dort die Matrix-Anmeldung, die Erkennung des XMPP-Servers und das Teilen von Dateien sowie Nostr-Dateien und Namensabfragen nicht. Jetzt funktionieren sie. Siehe [Matrix](#matrix), [XMPP](#xmpp) und [Chats mit anderen Nostr-Apps](#nostr-chats).",
  // 3.4.2
  '**A message sent as a chat opens waits for it**, marked Sending…, and goes as soon as the chat is open, never saying that Erevos cannot encrypt.':
    '**Eine Nachricht, die du sendest, während sich ein Chat öffnet, wartet auf ihn**, markiert mit Wird gesendet…, und geht, sobald er offen ist, ohne zu sagen, dass Erevos nicht verschlüsseln kann.',
  '**What you read as a chat opens stays read**: the home screen no longer counts it as new.':
    '**Was du liest, während sich ein Chat öffnet, bleibt gelesen**: Der Startbildschirm zählt es nicht mehr als neu.',
  '**No question from Samsung about its sharing**: on a Samsung phone, Wi-Fi Aware and the Wi-Fi with phones nearby stay off until you turn them on. See [Chat with a nearby phone](#nearby).':
    '**Keine Frage von Samsung nach seiner Freigabe**: Auf einem Samsung-Telefon bleiben Wi-Fi Aware und das WLAN mit Telefonen in der Nähe aus, bis du sie einschaltest. Siehe [Chat mit einem Telefon in der Nähe](#nearby).',
  '**The SMS field keeps its width on a small screen**: Photo and Send beside it are round buttons, as in a chat.':
    '**Das SMS-Feld behält seine Breite auf einem kleinen Bildschirm**: Foto und Senden daneben sind runde Knöpfe, wie in einem Chat.',
  // 3.4.1
  '**Send answers at once**: a short buzz as you press it, the field empties and the message shows, marked Sending…, so it never goes twice.':
    '**Senden reagiert sofort**: ein kurzes Vibrieren beim Tippen, das Feld leert sich und die Nachricht erscheint mit „Wird gesendet…“, sodass sie nie zweimal geht.',
  '**The screen no longer stays pushed up** after the keyboard closed behind a sheet, a dialog or another app.':
    '**Der Bildschirm bleibt nicht mehr hochgeschoben**, nachdem sich die Tastatur hinter einem Fenster, einem Dialog oder einer anderen App geschlossen hat.',
  '**Importing a chat with its photos no longer freezes Erevos**: the screen moves while the files come in, says what share of them is in, and **Cancel** stops it. A chat moved into hidden chats takes the chats imported into it along. See [Imported chats](#import).':
    '**Einen Chat mit seinen Fotos zu importieren friert Erevos nicht mehr ein**: Der Bildschirm bleibt bedienbar, während die Dateien kommen, zeigt, welcher Anteil schon da ist, und **Abbrechen** hält es an. Ein in versteckte Chats verschobener Chat nimmt die in ihn importierten Chats mit. Siehe [Importierte Chats](#import).',
  // 3.4.0
  '**Your relay proves its own key**: every connection to it starts with a check only the relay holding that key can pass, so no one in between can pass for it. Once it has, Erevos never reaches it without the check. Your relay needs an update for it.':
    '**Dein Relay beweist seinen eigenen Schlüssel**: Jede Verbindung dorthin beginnt mit einer Prüfung, die nur das Relay mit diesem Schlüssel bestehen kann, so kann sich niemand dazwischen als es ausgeben. Hat es sie einmal bestanden, verbindet sich Erevos nie mehr ohne die Prüfung damit. Dein Relay braucht dafür ein Update.',
  '[Transparency](#transparency), a new part of the guide: what the server behind Erevos keeps and for how long, what it does not keep, and who else sees something.':
    '[Transparenz](#transparency), ein neuer Teil der Anleitung: was der Server hinter Erevos speichert und wie lange, was er nicht speichert und wer sonst etwas sieht.',
  "**What's new**: this list, in Settings → General, by version.": '**Was ist neu**: diese Liste, unter „Einstellungen → Allgemein“, nach Versionen.',
  "**Nothing shows behind a chat's PIN**: none of the messages of a chat locked with a PIN is drawn until its PIN is typed, and with glass, a wallpaper or a style's own scene, the PIN screen is a dense frost that lets nothing through.":
    "**Hinter der PIN eines Chats ist nichts zu sehen**: Von einem mit einer PIN gesperrten Chat wird keine Nachricht gezeigt, bevor seine PIN eingegeben ist, und bei Glas, einem Hintergrund oder einem Stil mit eigener Szene ist der PIN-Bildschirm dichtes Milchglas, durch das nichts zu sehen ist.",
  "**A group video call from the top of the group**: a blue camera beside the green handset, as in a contact's chat.":
    "**Ein Gruppen-Videoanruf oben in der Gruppe**: eine blaue Kamera neben dem grünen Hörer, wie im Chat mit einem Kontakt.",
  "**A relay queue for each contact**: each contact writes to a queue only they know, so the relay cannot tell that two contacts write to the same phone, and deleting or blocking someone deletes only theirs. Your relay needs an update for it.":
    "**Eine Relay-Warteschlange für jeden Kontakt**: Jeder Kontakt schreibt in eine Warteschlange, die nur er kennt. So kann das Relay nicht erkennen, dass zwei Kontakte an dasselbe Telefon schreiben, und Löschen oder Blockieren entfernt nur dessen eigene. Dein Relay braucht dafür ein Update.",
  "**Hidden chats, more like the others**: they close after 30 seconds in the background, not at once, and never during a call or while you pick a photo or a file; while open, a message plays its sound, and link previews have a switch of their own there. See [Hidden chats](#hidden).":
    "**Versteckte Chats, mehr wie die anderen**: Sie schließen sich nach 30 Sekunden im Hintergrund, nicht sofort, und nie während eines Anrufs oder während du ein Foto oder eine Datei auswählst; solange sie offen sind, spielt eine Nachricht ihren Ton, und Linkvorschauen haben dort einen eigenen Schalter. Siehe [Versteckte Chats](#hidden).",
  "**Hidden chats that receive while closed**: a switch at the top of each place, on for new places, has them receive as your other chats do: their contacts see at once that a message came, a notice says only \"New message\", and a call rings with no name. See [Hidden chats](#hidden).":
    "**Versteckte Chats, die geschlossen empfangen**: Ein Schalter oben an jedem Platz, bei neuen Plätzen an, lässt sie wie deine anderen Chats empfangen: Ihre Kontakte sehen sofort, dass eine Nachricht angekommen ist, eine Mitteilung sagt nur „Neue Nachricht“, und ein Anruf klingelt ohne Namen. Siehe [Versteckte Chats](#hidden).",
  "**Hidden chats wait and import too**: what cannot go now waits, marked Waiting, and goes by itself through their relay; Send later works there as in your other chats; and a chat from Telegram, WhatsApp or Viber can be imported into a hidden chat, kept only there. See [Hidden chats](#hidden).":
    "**Versteckte Chats warten und importieren auch**: Was jetzt nicht gehen kann, wartet, markiert mit „Wartet“, und geht von selbst über ihr Relay; „Später senden“ funktioniert dort wie in deinen anderen Chats; und ein Chat aus Telegram, WhatsApp oder Viber kann in einen versteckten Chat importiert werden und bleibt nur dort. Siehe [Versteckte Chats](#hidden).",
  "**Hidden chats listed like your chats**: they open on a list as the home screen's, with what was said last and how many are not read, and each place has a Chat with myself of its own at its top. See [Hidden chats](#hidden).":
    "**Versteckte Chats als Liste wie deine Chats**: Sie öffnen sich in einer Liste wie auf dem Startbildschirm, mit dem zuletzt Gesagten und wie viele ungelesen sind, und jeder Platz hat oben seinen eigenen Chat mit mir selbst. Siehe [Versteckte Chats](#hidden).",
  "**More in hidden chats**: with Receive while closed on, what comes to them through Nostr is read while they are closed too; and there a contact can be added from a photo of their QR code, and a hidden contact given a photo. See [Hidden chats](#hidden).":
    "**Mehr in versteckten Chats**: Mit „Empfangen, wenn geschlossen“ wird auch gelesen, was über Nostr zu ihnen kommt, während sie geschlossen sind; und dort kann ein Kontakt über ein Foto seines QR-Codes hinzugefügt und einem versteckten Kontakt ein Foto gegeben werden. Siehe [Versteckte Chats](#hidden).",
  "**Hidden chats with no relay**: as your other chats, they can begin through Nostr only: their contact link and QR code say where they read there, and texts and reactions go there. See [Hidden chats](#hidden).":
    "**Versteckte Chats ohne Relay**: Wie deine anderen Chats können sie nur über Nostr beginnen: Ihr Kontaktlink und QR-Code sagen, wo sie dort lesen, und Texte und Reaktionen gehen dorthin. Siehe [Versteckte Chats](#hidden).",
  "**Groups in hidden chats**: under their list, New group makes a group with their contacts; it lists among their chats, goes through their relay only, and is read while they are closed if Receive while closed is on. See [Hidden chats](#hidden).":
    "**Gruppen in versteckten Chats**: Unter ihrer Liste macht Neue Gruppe eine Gruppe mit ihren Kontakten; sie steht unter ihren Chats, geht nur über ihr Relay und wird gelesen, während sie geschlossen sind, wenn Empfangen, wenn geschlossen an ist. Siehe [Versteckte Chats](#hidden).",
  "**No test version line**: the home screen no longer ends saying this is a test version. The guide still says exactly what is protected, and that nothing has been audited yet. See [What is protected today](#privacy).":
    "**Kein Hinweis auf eine Testversion mehr**: Der Startbildschirm endet nicht mehr mit der Zeile, dies sei eine Testversion. Die Anleitung sagt weiter genau, was geschützt ist, und dass noch nichts geprüft wurde. Siehe [Was heute geschützt ist](#privacy).",
  "**The contacts menu in hidden chats**: their Contacts has a menu again, with what is theirs only: a .vcf file imported into them, their contacts saved as a .vcf file, and a contact's QR code read from a photo. An Erevos ID typed there adds them to the hidden chats. See [Contacts](#contacts).":
    "**Das Kontaktmenü in versteckten Chats**: Ihre Kontakte haben wieder ein Menü, nur mit dem, was ihnen gehört: eine .vcf-Datei in sie importieren, ihre Kontakte als .vcf-Datei speichern und den QR-Code eines Kontakts aus einem Foto lesen. Eine dort eingegebene Erevos-ID fügt die Person den versteckten Chats hinzu. Siehe [Kontakte](#contacts).",
  // 3.3.2
  '**The plain call button for more contacts**: the orange keypad at the top of a contact’s chat also takes the number of a contact you connected them to (**Connect to one of my contacts**), the mobile number first.':
    '**Die Taste für normale Anrufe bei mehr Kontakten**: Das orangefarbene Tastenfeld oben im Chat eines Kontakts nimmt auch die Nummer des Kontakts, mit dem du ihn verknüpft hast (**Mit einem meiner Kontakte verknüpfen**), zuerst die Mobilnummer.',
  // 3.3.1
  '**Viber chats can be imported**: from the HTML file of the Android app Backup Text for Viber, words only.':
    '**Viber-Chats lassen sich importieren**: aus der HTML-Datei der Android-App Backup Text for Viber, nur der Text.',
  // 3.3.0
  '**Start without a relay, through Nostr**: **Start without a relay** on New chat. Texts, stickers, reactions, edits and the delivered and read marks go through Nostr over Tor. Photos, voice messages, files and calls still need a relay or a phone nearby.':
    '**Ohne Relay anfangen, über Nostr**: **Ohne Relay anfangen** unter „Neuer Chat“. Texte, Sticker, Reaktionen, Bearbeitungen und die Zeichen für zugestellt und gelesen gehen über Nostr, über Tor. Fotos, Sprachnachrichten, Dateien und Anrufe brauchen weiterhin ein Relay oder ein Telefon in der Nähe.',
  '**The relay comes by itself**: whoever has a relay that invites sends a contact with no relay an invite once, inside the chat, and the other phone takes it by itself.':
    '**Das Relay kommt von selbst**: Wer ein Relay hat, das Einladungen erlaubt, schickt einem Kontakt ohne Relay einmal eine Einladung, im Chat, und das andere Telefon nimmt sie von selbst an.',
  '**Told when a new version is out** (Android): once a day Erevos asks LPHL’s server, then shows a pinned Erevos row and a notice, only for a version the release computer signed. It turns off in Settings → General → Updates.':
    '**Hinweis, wenn eine neue Version da ist** (Android): Einmal am Tag fragt Erevos den Server von LPHL und zeigt dann eine angeheftete Erevos-Zeile und eine Mitteilung, nur für eine Version, die der Release-Computer signiert hat. Abschalten lässt es sich unter „Einstellungen → Allgemein → Updates“.',
  '**Lock a chat with a PIN**: Details → Lock with a PIN, for chats and groups. Nothing of it shows in search, starred messages or imports. In hidden chats it asks for no PIN.':
    '**Einen Chat mit einer PIN sperren**: „Details → Mit PIN sperren“, für Chats und Gruppen. Nichts davon erscheint in der Suche, in markierten Nachrichten oder in Importen. In versteckten Chats wird keine PIN abgefragt.',
  '**A new handset** on the green tiles: Phone, and the call in a chat.': '**Ein neuer Hörer** auf den grünen Kacheln: Telefon und der Anruf im Chat.',
  '**A new New chat screen**: How you connect now at the top, three large cards for a phone without a relay (I have an invite, Sign in with LPHL, Start without a relay), and the technical part under For advanced users.':
    '**Ein neuer Bildschirm „Neuer Chat“**: „So bist du jetzt verbunden“ ganz oben, drei große Karten für ein Telefon ohne Relay („Ich habe eine Einladung“, „Mit LPHL anmelden“, „Ohne Relay anfangen“) und das Technische unter „Für Fortgeschrittene“.',
  '**Nostr steadier through Tor**: each Nostr relay has its own way through Tor, and after a failure it tries a new exit. A clearer error on the Nostr screen.':
    '**Nostr stabiler über Tor**: Jedes Nostr-Relay hat seinen eigenen Weg durch Tor und versucht nach einem Fehler einen neuen Exit-Knoten. Eine klarere Fehlermeldung auf dem Nostr-Bildschirm.',
  '**When the connection to the relay drops** while Erevos waits on it, Erevos notices and connects again, where it stayed stuck before.':
    '**Wenn die Verbindung zum Relay abbricht**, während Erevos darauf wartet, merkt Erevos das und verbindet sich neu, wo es vorher hängen blieb.',
  '**Invite by SMS** (Android): on a phone contact’s card, for one person, for 2 days. The link opens a page that offers Erevos (the APK for Android, the web app for an iPhone or a computer), then opens the invite. The QR code and Share the invite stay as they were.':
    '**Per SMS einladen** (Android): auf der Karte eines Telefonkontakts, für eine Person, für 2 Tage. Der Link öffnet eine Seite, die Erevos anbietet (das APK für Android, die Web-App für ein iPhone oder einen Computer), und öffnet dann die Einladung. Der QR-Code und „Einladung teilen“ bleiben, wie sie waren.',
  '**Fixes to the SMS invite**: a link copied as /i/#… works too, an older web app opens the invite as well, and on iOS 26 it says Share is under •••.':
    '**Korrekturen an der SMS-Einladung**: Auch ein als /i/#… kopierter Link funktioniert, eine ältere Web-App öffnet die Einladung ebenfalls, und in iOS 26 steht dabei, dass „Teilen“ unter ••• liegt.',
  '**A phone call button** in Erevos chats and SMS chats.': '**Eine Taste für Telefonanrufe** in Erevos-Chats und SMS-Chats.',
  // 3.2.1
  '**Edit a message** you sent, up to a day after: to contacts, groups and linked devices, with Edited beside the time.':
    '**Eine gesendete Nachricht bearbeiten**, bis zu einem Tag danach: bei Kontakten, in Gruppen und auf verknüpften Geräten, mit „Bearbeitet“ neben der Uhrzeit.',
  '**Nostr says what it did**: Sent through Nostr, and on the Nostr screen what each relay did last.':
    '**Nostr sagt, was es getan hat**: „Über Nostr gesendet“, und auf dem Nostr-Bildschirm, was jedes Relay zuletzt tat.',
  '**Coloured call buttons** at the top of a chat: video blue, voice green.': '**Farbige Anruftasten** oben im Chat: Videoanruf blau, Sprachanruf grün.',
  // 3.2.0
  'Arrows to the start and the end of a chat; earlier messages come by themselves as you scroll.':
    'Pfeile zum Anfang und zum Ende eines Chats; ältere Nachrichten laden von selbst, während du scrollst.',
  'Chats imported from Telegram and WhatsApp look like Erevos messages: bubbles, days, photos, voice messages, search.':
    'Aus Telegram und WhatsApp importierte Chats sehen aus wie Erevos-Nachrichten: Sprechblasen, Tage, Fotos, Sprachnachrichten, Suche.',
  'Dogs instead of cats in the stickers.': 'Hunde statt Katzen in den Stickern.',
  'Screenshots: a switch in Settings → Privacy and security.': 'Bildschirmfotos: ein Schalter unter „Einstellungen → Datenschutz und Sicherheit“.',
  'Hidden chats from New chat: hold it for a second.': 'Versteckte Chats über „Neuer Chat“: eine Sekunde lang gedrückt halten.',
  'Coloured tiles on the home screen: Phone green, Contacts violet, the lock orange.': 'Farbige Kacheln auf dem Startbildschirm: Telefon grün, Kontakte violett, das Schloss orange.',
  '**Chat with myself**, always first, and **Remind me**, the orange bell.': '**Chat mit mir selbst**, immer ganz oben, und **Erinnern**, die orangefarbene Glocke.',
  '**Media, links and files** in a chat’s Details, with a calendar and Go to a day.':
    '**Medien, Links und Dateien** in den Details eines Chats, mit einem Kalender und „Zu einem Tag“.',
  'Import a chat from inside the chat: Details → Imported chats.': 'Einen Chat direkt im Chat importieren: „Details → Importierte Chats“.',
  'A closed space can say that a message came while another space is open.': 'Ein geschlossener Bereich kann melden, dass eine Nachricht kam, während ein anderer Bereich offen ist.',
  'The message menu says when a message went or came through Nostr.': 'Das Nachrichtenmenü zeigt, wenn eine Nachricht über Nostr gesendet wurde oder kam.',
  '**Support Erevos**: Liberapay, PayPal, Monero, Bitcoin.': '**Erevos unterstützen**: Liberapay, PayPal, Monero, Bitcoin.',
  'Who makes Erevos and why, in About Erevos; the guide says why everywhere.': 'Wer Erevos macht und warum, unter „Über Erevos“; die Anleitung sagt überall, warum.',
  // 3.1.2
  '**Settings in 8 groups**, with a search: General, Appearance, Notifications, Privacy and security, Relay and networks, Phone and SMS, Data and devices, For testing. The home screen’s ⋯ keeps only the places, and Settings last.':
    '**Einstellungen in 8 Gruppen**, mit einer Suche: Allgemein, Darstellung, Benachrichtigungen, Datenschutz und Sicherheit, Relay und Netze, Telefon und SMS, Daten und Geräte, Zum Testen. Das ⋯ auf dem Startbildschirm enthält nur noch die Orte und zuletzt die Einstellungen.',
  // 3.1.1
  'Check for updates says what stopped an update.': '„Nach Updates suchen“ sagt, was ein Update verhindert hat.',
  'Invite someone is not made from a token for all; it asks you to sign in to the relay first.':
    '„Jemanden einladen“ entsteht nicht mehr aus einem Token für alle; es bittet dich zuerst, dich beim Relay anzumelden.',
  'The relay’s token for all becomes a token of the phone’s own, by itself (needs the relay updated).':
    'Das Token für alle des Relays wird von selbst zu einem eigenen Token dieses Telefons (das Relay braucht dafür ein Update).',
  'A relay that refuses through Tor says why.': 'Ein Relay, das Verbindungen über Tor ablehnt, sagt, warum.',
  // 3.1.0
  'Less battery in the background: the relay, Tor and the nearby radios.': 'Weniger Akkuverbrauch im Hintergrund: Relay, Tor und die Funkverbindungen zu Telefonen in der Nähe.',
  'Erevos no longer closes when you make a sticker from a photo.': 'Erevos schließt sich nicht mehr, wenn du aus einem Foto einen Sticker machst.',
  'Hidden chats’ notices are right.': 'Die Benachrichtigungen der versteckten Chats stimmen.',
  'Hidden chats by holding New chat.': 'Versteckte Chats durch Gedrückthalten von „Neuer Chat“.',
  'A search for contacts on the Phone.': 'Eine Suche nach Kontakten unter „Telefon“.',
  'New chat shows first how to add a contact.': '„Neuer Chat“ zeigt zuerst, wie du einen Kontakt hinzufügst.',
  'A call shows over the screen saver, and the screen wakes.': 'Ein Anruf erscheint über dem Bildschirmschoner, und der Bildschirm geht an.',
  'Erevos in other apps’ Share.': 'Erevos unter „Teilen“ in anderen Apps.',
  'A sound for every new message, also while Erevos shows.': 'Ein Ton für jede neue Nachricht, auch während Erevos offen ist.',
  'The SMS settings say right what holding does.': 'Die SMS-Einstellungen sagen richtig, was das Gedrückthalten bewirkt.',
  // 3.0.0
  'Each icon opens what it names: Erevos, SMS, Phone, Contacts, the widget.': 'Jedes Symbol öffnet, was es nennt: Erevos, SMS, Telefon, Kontakte, das Widget.',
  '**Messages through Tor by default**: Messages, Everything or Nothing.': '**Nachrichten standardmäßig über Tor**: Nachrichten, Alles oder Nichts.',
  '**Texts through Nostr**: three public relays, through Tor, with your own relay as backup after 5 minutes.':
    '**Texte über Nostr**: drei öffentliche Relays, über Tor, mit deinem eigenen Relay als Reserve nach 5 Minuten.',
  // 2.0.3
  'One invite for everything: the relay and the contact together.': 'Eine Einladung für alles: Relay und Kontakt zusammen.',
  'Spam rules for senders and numbers abroad, with the reason.': 'Spam-Regeln für Absender und Nummern aus dem Ausland, mit Begründung.',
  '480 stickers in 20 sets.': '480 Sticker in 20 Sets.',
  'Lighter chats on older phones; QR codes at once.': 'Leichtere Chats auf älteren Telefonen; QR-Codes sofort.',
  'Copy code for one-time codes in SMS.': '„Code kopieren“ für Einmalcodes in SMS.',
  'Locked, Erevos keeps receiving.': 'Auch gesperrt empfängt Erevos weiter.',
  'Faster contacts; the hidden chats’ notice counts only messages.': 'Schnellere Kontakte; die Benachrichtigung der versteckten Chats zählt nur Nachrichten.',
  'The relay tries every address: push, other relays, the LPHL sign-in.': 'Das Relay versucht jede Adresse: Push, andere Relays, die LPHL-Anmeldung.',
  // 2.0.2
  'Swiping on the tabs only changes the tab.': 'Wischen auf den Tabs wechselt nur den Tab.',
  'The icons fill the launcher’s shape.': 'Die Symbole füllen die Form des Launchers aus.',
  // 2.0.1
  'Coloured icons (Erevos red, Phone green, SMS blue, Contacts violet) and a new SMS icon.':
    'Farbige Symbole (Erevos rot, Telefon grün, SMS blau, Kontakte violett) und ein neues SMS-Symbol.',
  'A colour for each icon, and the order of the widget’s buttons.': 'Eine Farbe für jedes Symbol, und die Reihenfolge der Schaltflächen des Widgets.',
  'Swipe to go back, and between tabs.': 'Wischen, um zurückzugehen, und zwischen Tabs.',
  // 2.0.0
  'An update of the WebView no longer closes Erevos.': 'Ein Update der WebView schließt Erevos nicht mehr.',
  'Deleting or blocking a contact gives you a new queue on the relay.': 'Wenn du einen Kontakt löschst oder blockierst, bekommst du eine neue Warteschlange auf dem Relay.',
  'A new contact can take the name of a contact on the phone.': 'Ein neuer Kontakt kann den Namen eines Kontakts auf dem Telefon übernehmen.',
  '**Sign in to the relay with LPHL**, and **invites to the relay**.': '**Beim Relay mit LPHL anmelden**, und **Einladungen zum Relay**.',
  'Permissions in the web app, and more on Android; the web app’s notice says how many came.':
    'Berechtigungen in der Web-App und mehr auf Android; die Benachrichtigung der Web-App sagt, wie viele kamen.',
  'Hidden chats can ring calls while they are closed.': 'Versteckte Chats können Anrufe klingeln lassen, während sie geschlossen sind.',
  'New keys every month in chats, every week in groups.': 'Neue Schlüssel jeden Monat in Chats, jede Woche in Gruppen.',
  'Linked devices work with the phone off.': 'Verknüpfte Geräte funktionieren auch bei ausgeschaltetem Telefon.',
  'A new chat screen; QR codes from a photo; the Phone for small screens.': 'Ein neuer Chat-Bildschirm; QR-Codes aus einem Foto; das Telefon für kleine Bildschirme.',
  'Add as contact inside a group.': '„Als Kontakt hinzufügen“ in einer Gruppe.',
  'Stickers in sets, moving, and your own.': 'Sticker in Sets, animiert, und eigene.',
  'SMS inside the Erevos chat.': 'SMS im Erevos-Chat.',
  'Android updates need the release computer’s signature.': 'Android-Updates brauchen die Signatur des Release-Computers.',
  'An F-Droid build; Serbo-Croatian; new version numbers.': 'Ein Build für F-Droid; Serbokroatisch; neue Versionsnummern.',
  'Much for security: Argon2id, messages encrypted for the relay too, a token for each phone, no link starts a call.':
    'Viel für die Sicherheit: Argon2id, Nachrichten auch für das Relay verschlüsselt, ein Token für jedes Telefon, kein Link startet einen Anruf.',
  // 0.1.16
  'Imports from Telegram and WhatsApp bring photos, videos, voice messages and files.': 'Importe aus Telegram und WhatsApp bringen Fotos, Videos, Sprachnachrichten und Dateien mit.',
  'A phone without a relay talks through a place on a contact’s relay.': 'Ein Telefon ohne Relay spricht über einen Platz auf dem Relay eines Kontakts.',
  // 0.1.14
  'Back to my chats, for hidden chats.': '„Zurück in meine Chats verschieben“, für versteckte Chats.',
  'Erevos receives and rings even after you swipe it away from the recent apps.': 'Erevos empfängt und klingelt auch, nachdem du es aus den letzten Apps weggewischt hast.',
  // 0.1.12
  'Hidden chats can say a message came.': 'Versteckte Chats können melden, dass eine Nachricht kam.',
  'Fixes: menus, QR codes from a photo, Bluetooth on Android 17, long lists.': 'Korrekturen: Menüs, QR-Codes aus einem Foto, Bluetooth unter Android 17, lange Listen.',
  // 0.1.11
  'The Phone without the password, if you allow it; a home screen widget; an SMS and Erevos filter.':
    'Das Telefon ohne Passwort, wenn du es erlaubst; ein Widget für den Startbildschirm; ein Filter für SMS und Erevos.',
  // 0.1.10
  'Links wait for the password; Phone and Contacts icons; the Erevos ID on a contact.': 'Links warten auf das Passwort; Symbole für Telefon und Kontakte; die Erevos-ID bei einem Kontakt.',
  // 0.1.8
  '61 new features: 5 new languages, linked devices, public groups, replies, reactions, polls, send later, Erevos as the phone and contacts app, Tor bridges, the fingerprint, Windows and more.':
    '61 neue Funktionen: 5 neue Sprachen, verknüpfte Geräte, öffentliche Gruppen, Antworten, Reaktionen, Umfragen, später senden, Erevos als Telefon- und Kontakte-App, Tor-Brücken, der Fingerabdruck, Windows und mehr.',
  // 0.1.7 to 0.1.2
  'SMS notices in the background.': 'SMS-Benachrichtigungen im Hintergrund.',
  'The web app comes out with every release.': 'Die Web-App erscheint mit jedem Release.',
  'Greek in the whole app.': 'Griechisch in der ganzen App.',
  'Web Push in the web app.': 'Web Push in der Web-App.',
  'The first signed Android release: encrypted chats, calls, groups, hidden chats, backups, imports, and phones nearby without the internet.':
    'Das erste signierte Android-Release: verschlüsselte Chats, Anrufe, Gruppen, versteckte Chats, Backups, Importe und Telefone in der Nähe ohne Internet.',
  "**Two new sticker sets of 24 moods**: **Tux**, the Linux penguin as he is drawn, and **Aikido**, an aikidoka in keikogi and a wide hakama, who also bows, sits in seiza and rolls.":
    "**Zwei neue Sticker-Sets mit 24 Stimmungen**: **Tux**, der Linux-Pinguin, wie er gezeichnet ist, und **Aikido**, ein Aikidoka in Keikogi und weitem Hakama, der sich auch verbeugt, im Seiza sitzt und rollt.",
  "**A new sticker set, Takis**: a caricature in a dark suit and a purple tie with dots, in 24 moods that move.":
    "**Ein neues Sticker-Set, Takis**: eine Karikatur in dunklem Anzug und lila Krawatte mit Punkten, in 24 Stimmungen, die sich bewegen.",
  "**Photos, files and voice messages with no relay**: when there is no relay between you and your contact and they read on Nostr, a voice message goes through Nostr like a text, a photo up to 3 MB in pieces, and a larger photo, a video or another file, up to 20 MB, to an encrypted file server (Blossom), all through Tor. See [Through Nostr](#nostr).":
    "**Fotos, Dateien und Sprachnachrichten ohne Relay**: Ist kein Relay zwischen dir und deinem Kontakt und liest er auf Nostr, geht eine Sprachnachricht wie ein Text über Nostr, ein Foto bis 3 MB in Stücken, und ein größeres Foto, ein Video oder eine andere Datei, bis 20 MB, an einen verschlüsselten Dateiserver (Blossom), alles über Tor. Siehe [Über Nostr](#nostr).",
  "**More battery saved in the background, if you choose**: under Settings → Notifications → In the background, Only the waste stays the default; And nearby phones also turns off the radios for phones nearby while Erevos is in the background; And sleep also lets the phone sleep, so Erevos looks at your relay about once a minute and a message or a call can be a minute or two late. Android only. See [Chat through a relay](#relay).":
    "**Mehr Akku im Hintergrund gespart, wenn du willst**: Unter Einstellungen → Benachrichtigungen → Im Hintergrund bleibt Nur die Verschwendung die Vorgabe; Und Telefone in der Nähe schaltet auch die Funkverbindungen zu Telefonen in der Nähe aus, solange Erevos im Hintergrund ist; Und Schlaf lässt auch das Telefon schlafen, sodass Erevos etwa einmal pro Minute an deinem Relay nachschaut und eine Nachricht oder ein Anruf ein bis zwei Minuten zu spät kommen kann. Nur Android. Siehe [Chat über ein Relay](#relay).",
  "**A contact you delete no longer comes back from an old ask**: in a group, a member you asked for their contact link, or who asked for yours, and whom you then deleted as a contact before Erevos looked at the relay again, could be added again by that old ask. Deleting them now lets go of it at once. See [Group chats](#groups).":
    "**Ein gelöschter Kontakt kommt nicht mehr durch eine alte Anfrage zurück**: In einer Gruppe konnte ein Mitglied, dessen Kontaktlink du erfragt hattest oder das deinen erfragt hatte und das du dann als Kontakt gelöscht hast, bevor Erevos wieder am Relay nachsah, durch diese alte Anfrage erneut hinzugefügt werden. Das Löschen lässt sie jetzt sofort los. Siehe [Gruppenchats](#groups).",
  "**Every message says which way it went**: hold a message and its menu says whether it went or came through the relay, through Nostr, to a phone nearby or over LoRa. Messages from before say nothing. See [Through Nostr](#nostr).":
    "**Jede Nachricht sagt, welchen Weg sie ging**: Halte eine Nachricht gedrückt, und ihr Menü sagt, ob sie über das Relay, über Nostr, über ein Telefon in der Nähe oder über LoRa ging oder kam. Frühere Nachrichten sagen nichts. Siehe [Über Nostr](#nostr).",
  "**The spam filter reads words as they look**: a scam text that swaps a letter for a look-alike of another alphabet, or hides a mark that shows nothing inside a word, no longer gets past it. See [SMS](#sms).":
    "**Der Spamfilter liest Wörter, wie sie aussehen**: Eine Betrugs-SMS, die einen Buchstaben gegen einen ähnlich aussehenden eines anderen Alphabets tauscht oder ein unsichtbares Zeichen in ein Wort steckt, täuscht ihn nicht mehr. Siehe [SMS](#sms).",
  "**Media, links and files in groups too**: in a group's details, a list of its photos, videos, voice messages, music, files and links, each kind apart under its months, with a calendar, as in a contact's chat. A tap opens or plays; held, each goes to its message. See [Group chats](#groups).":
    "**Medien, Links und Dateien auch in Gruppen**: In den Details einer Gruppe eine Liste ihrer Fotos, Videos, Sprachnachrichten, Musik, Dateien und Links, jede Art für sich unter ihren Monaten, mit Kalender, wie im Chat eines Kontakts. Ein Tippen öffnet oder spielt ab; gehalten geht jedes zu seiner Nachricht. Siehe [Gruppenchats](#groups).",
  "**A relay restart no longer brings a false notice**: after your relay restarted, a hidden chat or a closed space said New message once more for messages it had told of already. Your relay needs an update for it. See [Hidden chats](#hidden).":
    "**Ein Neustart des Relays bringt keine falsche Benachrichtigung mehr**: Nachdem dein Relay neu gestartet war, sagte ein versteckter Chat oder ein geschlossener Bereich noch einmal Neue Nachricht für Nachrichten, die er schon gemeldet hatte. Dein Relay braucht dafür ein Update. Siehe [Versteckte Chats](#hidden).",
  "**Backups to your server through Tor**: on Android, automatic backups sent to your own server now follow the space's choice under Settings → Relay and networks → Tor, as Matrix does, so with Tor the server no longer sees where you are. To a server too says when they go through Tor. See [Backups](#backup).":
    "**Backups auf deinen Server über Tor**: Auf Android folgen automatische Backups auf deinen eigenen Server jetzt der Wahl des Bereichs unter Einstellungen → Relay und Netze → Tor, wie Matrix, sodass der Server mit Tor nicht mehr sieht, wo du bist. Auch auf einen Server sagt, wann sie über Tor gehen. Siehe [Backups](#backup).",
  "**Restore a backup straight from your server**: Restore from a server, under Backups, lists the backups on your server, newest first, and opens the one you choose with its password, with no download by hand, on a new phone too. See [Backups](#backup).":
    "**Ein Backup direkt von deinem Server wiederherstellen**: Von einem Server wiederherstellen, unter Backups, zeigt die Backups auf deinem Server, die neuesten zuerst, und öffnet das gewählte mit seinem Passwort, ohne Herunterladen von Hand, auch auf einem neuen Telefon. Siehe [Backups](#backup).",
  "**Backups to your server from a computer and the web app too**: in the desktop app, automatic backups go to your WebDAV server as on Android; in the web app, Send a backup now sends one there, with a server that lets the web app in. Both can restore from it. Not through Tor. See [Backups](#backup).":
    "**Backups auf deinen Server auch vom Computer und aus der Web-App**: In der Desktop-App gehen automatische Backups wie auf Android auf deinen WebDAV-Server; in der Web-App schickt Jetzt ein Backup senden eines dorthin, bei einem Server, der die Web-App hereinlässt. Beide können von dort wiederherstellen. Nicht über Tor. Siehe [Backups](#backup).",
  "**Check a contact in person with QR codes**: under Safety number in a chat's details, each phone shows a code; take a photo of the code on the other phone, and they of yours. When it matches, the contact is marked Checked in person. Nothing is sent. See [Chat through a relay](#relay).": "**Einen Kontakt persönlich mit QR-Codes prüfen**: Unter Sicherheitsnummer in den Details eines Chats zeigt jedes Telefon einen Code; fotografiere den Code auf dem anderen Telefon und dein Kontakt deinen. Passt er, wird der Kontakt als Persönlich geprüft markiert. Nichts wird gesendet. Siehe [Chat über ein Relay](#relay).",
  "**Up to three home relays**: under Settings → Relay and networks → Home relay, Add another home relay gives a space up to two more, each with a queue of its own. Your contact link and your messages name them in order, and contacts try each while the ones before cannot be reached. See [Home relay](#home-relay).": "**Bis zu drei Heim-Relays**: Unter Einstellungen → Relay und Netze → Heim-Relay gibt Weiteres Heim-Relay hinzufügen einem Bereich bis zu zwei weitere, jedes mit eigener Warteschlange. Dein Kontaktlink und deine Nachrichten nennen sie der Reihe nach, und Kontakte probieren jedes, solange die davor nicht erreichbar sind. Siehe [Heim-Relay](#home-relay).",
  "**Introduce two of your contacts**: in a contact's chat details, Introduce to a contact asks them and another contact of yours, each in your chat with them. Only if both say yes do they become contacts, and neither learns whether the other said no. See [Chat through a relay](#relay).": "**Zwei deiner Kontakte einander vorstellen**: In den Chatdetails eines Kontakts fragt Einem Kontakt vorstellen ihn und einen anderen deiner Kontakte, jeden in deinem Chat mit ihm. Nur wenn beide zustimmen, werden sie Kontakte, und keiner erfährt, ob der andere abgelehnt hat. Siehe [Chat über ein Relay](#relay).",
  "**Bluetooth that cannot be followed**: the random number your phone sends out over Bluetooth for phones nearby to find it changed only when Erevos started again; it now changes every nine to twelve minutes, so someone listening cannot follow your phone from place to place by it. Older Erevos phones still find yours. See [Chat with a nearby phone](#nearby).": "**Bluetooth, dem man nicht folgen kann**: Die Zufallszahl, die dein Telefon über Bluetooth aussendet, damit Telefone in der Nähe es finden, änderte sich nur, wenn Erevos neu startete; jetzt ändert sie sich alle neun bis zwölf Minuten, sodass dir niemand anhand von ihr von Ort zu Ort folgen kann. Telefone mit älterem Erevos finden deins weiterhin. Siehe [Chat mit einem Telefon in der Nähe](#nearby).",
  "**Hidden chats show at once**: as the PIN opens them, their chats and contacts show at once, to read, while what they were receiving in the background ends; before, that could hold them back a long while, as it may go through Tor. See [Hidden chats](#hidden).": "**Versteckte Chats zeigen sich sofort**: Sobald die PIN sie öffnet, zeigen sich ihre Chats und Kontakte sofort zum Lesen, während das Empfangen im Hintergrund endet; vorher konnte das sie lange aufhalten, da es über Tor laufen kann. Siehe [Versteckte Chats](#hidden).",
  "**Your backup password in pieces with friends**: under Settings → Data and devices → Backup pieces, give pieces of it to 3 to 5 contacts; any 2 or 3 of them give it back, one alone shows nothing. Each goes inside the encryption of your chat with them and only their Erevos keeps it; your phone keeps none. See [Backup pieces with friends](#backup-pieces).": "**Dein Backup-Passwort in Teilen bei Freunden**: Unter Einstellungen → Daten und Geräte → Backup-Teile gibst du 3 bis 5 Kontakten Teile davon; beliebige 2 oder 3 geben es zurück, eines allein zeigt nichts. Jedes geht innerhalb der Verschlüsselung deines Chats mit ihnen, und nur ihr Erevos bewahrt es auf; dein Telefon behält keines. Siehe [Backup-Teile bei Freunden](#backup-pieces).",
  "**Panic button**: under Settings → Privacy and security → Panic button, wipe everything Erevos keeps here with one tap, on Android and in the web app. On Android, a panic app such as Ripple can do it too, but only the one you say yes to, checked by its signature. See [Panic button](#panic).": "**Panikknopf**: Unter Einstellungen → Datenschutz und Sicherheit → Panikknopf löschst du mit einem Tippen alles, was Erevos hier aufbewahrt, auf Android und in der Web-App. Auf Android kann das auch eine Panik-App wie Ripple, aber nur die, der du zustimmst, geprüft an ihrer Signatur. Siehe [Panikknopf](#panic).",
  "**Erevos to a phone nearby, with no internet**: under Settings → General → Give Erevos to a phone nearby, this phone serves its Erevos over the same Wi-Fi or its hotspot for ten minutes, with a QR code. A phone without Erevos downloads it in the browser; one with an older Erevos takes it under Updates → From a phone nearby, which installs it only when it is Erevos, signed as that one is. See [Erevos to a phone nearby](#give-app).": "**Erevos an ein Telefon in der Nähe, ohne Internet**: Unter Einstellungen → Allgemein → Erevos an ein Telefon in der Nähe geben bietet dieses Telefon sein Erevos zehn Minuten lang über dasselbe WLAN oder seinen Hotspot an, mit einem QR-Code. Ein Telefon ohne Erevos lädt es im Browser; eines mit älterem Erevos holt es unter Updates → Von einem Telefon in der Nähe, das es nur installiert, wenn es Erevos ist, so signiert wie dieses. Siehe [Erevos an ein Telefon in der Nähe](#give-app).",
  "**Hidden chats with phones nearby**: while hidden chats are open, or receive while closed, they reach a contact's phone nearby over Bluetooth, Wi-Fi Aware, Wi-Fi Direct or the same Wi-Fi, with no internet, as your other chats do. The space never learns that a hidden contact is near, and nothing on the air tells their messages from the space's; other phones never carry them, and they never go over LoRa or by SMS. See [Hidden chats](#hidden).":
    "**Versteckte Chats mit Telefonen in der Nähe**: Solange versteckte Chats offen sind oder geschlossen empfangen, erreichen sie das Telefon eines Kontakts in der Nähe über Bluetooth, Wi-Fi Aware, Wi-Fi Direct oder im selben WLAN, ohne Internet, wie deine anderen Chats. Der Bereich erfährt nie, dass ein versteckter Kontakt in der Nähe ist, und nichts in der Luft unterscheidet ihre Nachrichten von denen des Bereichs; andere Telefone tragen sie nie, und sie gehen nie über LoRa oder per SMS. Siehe [Versteckte Chats](#hidden).",
  "**The same Wi-Fi on Sailfish OS**: Erevos on Sailfish OS finds Erevos phones and computers on the same Wi-Fi or a phone's hotspot and talks with them with no internet, as on a computer. See [On Sailfish OS](#sailfish).":
    "**Dasselbe WLAN unter Sailfish OS**: Erevos unter Sailfish OS findet Telefone und Computer mit Erevos im selben WLAN oder im Hotspot eines Telefons und spricht ohne Internet mit ihnen, wie auf einem Computer. Siehe [Unter Sailfish OS](#sailfish).",
  "**Downloads stop at 100 MB**: a file, a backup from a server or any other download is read as it comes and stopped as soon as it passes 100 MB, or less where the network's files are smaller, such as 20 MB for Nostr files, so a file server a contact names can no longer fill the phone's memory with an answer without end. A backup on a server comes back up to 100 MB; download a larger one and open it with Restore a backup. See [Backups](#backup).":
    "**Downloads enden bei 100 MB**: Eine Datei, ein Backup von einem Server oder jeder andere Download wird gelesen, wie er kommt, und abgebrochen, sobald er 100 MB überschreitet, oder weniger, wo die Dateien des Netzes kleiner sind, etwa 20 MB bei Nostr-Dateien. So kann ein Dateiserver, den ein Kontakt nennt, den Speicher des Telefons nicht mehr mit einer Antwort ohne Ende füllen. Ein Backup auf einem Server kommt bis 100 MB zurück; ein größeres lädst du herunter und öffnest es mit Backup wiederherstellen. Siehe [Backups](#backup).",
  "**Profile pictures on Matrix and XMPP**: contacts and Matrix rooms show their picture in the chat list, and you can set your own on the Matrix and XMPP screens (Choose a photo). Pictures are not encrypted on either network: the server sees them. See [Matrix](#matrix) and [XMPP](#xmpp).":
    "**Profilbilder in Matrix und XMPP**: Kontakte und Matrix-Räume zeigen ihr Bild in der Chatliste, und du kannst dein eigenes auf den Matrix- und XMPP-Bildschirmen setzen (Foto wählen). Die Bilder sind in beiden Netzen nicht verschlüsselt: der Server sieht sie. Siehe [Matrix](#matrix) und [XMPP](#xmpp).",
  "**Run an XMPP group**: a group's admins can set its subject and take people out or bar them, its owner can rename it and make admins, and in a channel the admin sees who is in it and can put them out. See [XMPP](#xmpp).":
    "**Eine XMPP-Gruppe leiten**: Die Admins einer Gruppe setzen den Betreff und können Leute entfernen oder sperren, der Besitzer kann sie umbenennen und Admins ernennen, und in einem Kanal sieht der Admin, wer drin ist, und kann Leute hinauswerfen. Siehe [XMPP](#xmpp).",
  "**Check a Matrix device by QR code**: once both sides accept a check, Erevos shows a code for Element (or another Erevos) to photograph, or photographs theirs, as Element does; comparing emoji stays one tap away. See [Matrix](#matrix).":
    "**Ein Matrix-Gerät per QR-Code prüfen**: Sobald beide Seiten eine Prüfung annehmen, zeigt Erevos einen Code, den Element (oder ein anderes Erevos) fotografiert, oder fotografiert deren Code, wie Element es tut; Emoji vergleichen bleibt einen Tipp entfernt. Siehe [Matrix](#matrix).",
  "**Sign in to Matrix with single sign-on** (Android): when your Matrix server signs people in on its own page, as matrix.org does, Sign in with single sign-on opens it in the browser and comes back to Erevos. See [Matrix](#matrix).":
    "**Bei Matrix mit Single Sign-On anmelden** (Android): Meldet dein Matrix-Server Leute auf seiner eigenen Seite an, wie matrix.org, öffnet „Mit Single Sign-On anmelden“ sie im Browser und kehrt zu Erevos zurück. Siehe [Matrix](#matrix).",
  "**A closed space tells of XMPP messages**: on Android, Say a message came under While this space is closed, on the XMPP screen, has a closed space say \"New message\" when something comes on XMPP while another space is open, never what, from whom or in which chat. Off until you choose it. It needs a relay updated for it and an XMPP server that sends notices to apps that are away; the XMPP server then learns the relay's name, and the relay when messages come. See [XMPP](#xmpp).":
    "**Ein geschlossener Bereich meldet XMPP-Nachrichten**: Auf Android lässt „Neue Nachrichten melden“ unter „Solange dieser Bereich geschlossen ist“ auf dem XMPP-Bildschirm einen geschlossenen Bereich „Neue Nachricht“ sagen, wenn auf XMPP etwas kommt, während ein anderer Bereich offen ist, nie was, von wem oder in welchem Chat. Aus, bis du es wählst. Es braucht ein dafür aktualisiertes Relay und einen XMPP-Server, der Meldungen an Apps schickt, die nicht laufen; der XMPP-Server erfährt dann den Namen des Relays, und das Relay, wann Nachrichten kommen. Siehe [XMPP](#xmpp).",
  "**Linking a computer is clearer**: on a computer, Settings → Data and devices → Linked devices now starts with Link to my phone, with LPHL's relay filled in and Sign in with LPHL under the token, so no token has to be copied from the phone; and it says that the QR code shows once Link to my phone is tapped. See [Linked devices](#devices).":
    "**Einen Computer zu verknüpfen ist klarer**: Auf einem Computer beginnt Einstellungen → Daten und Geräte → Verknüpfte Geräte jetzt mit „Mit meinem Telefon verknüpfen“, mit dem Relay von LPHL schon eingetragen und „Mit LPHL anmelden“ unter dem Token, sodass kein Token vom Telefon kopiert werden muss; und es sagt, dass der QR-Code erscheint, sobald du auf „Mit meinem Telefon verknüpfen“ tippst. Siehe [Verknüpfte Geräte](#devices).",
  "**Delete me from everywhere**: Settings → Privacy and security → Delete me from everywhere deletes what the servers keep for the open space (its queues on the relays with the messages in them, what a relay holds for you to send later, files waiting there, invites nobody used), asks the Nostr relays through Tor to forget the keys your chats read on, and stops the space until you tap Start again. Your phone keeps everything. You can also sign out of Matrix and XMPP and delete the Nostr account made here. See [Delete me from everywhere](#forget).": "**Von überall löschen**: Einstellungen → Datenschutz und Sicherheit → Von überall löschen löscht, was die Server für den offenen Bereich speichern (seine Warteschlangen auf den Relays mit den Nachrichten darin, was ein Relay für dich zum späteren Senden hält, dort wartende Dateien, Einladungen, die niemand benutzt hat), bittet die Nostr-Relays über Tor, die Schlüssel zu vergessen, auf denen deine Chats lesen, und hält den Bereich an, bis du auf Wieder starten tippst. Dein Telefon behält alles. Du kannst dich auch von Matrix und XMPP abmelden und das hier erstellte Nostr-Konto löschen. Siehe [Von überall löschen](#forget).",
  "**Every relay queue on one list**: the queues a space keeps on the relays are gathered in one place, and the checks fail if a new kind of queue is made without being added there, so Delete me from everywhere cannot leave one behind.": "**Jede Relay-Warteschlange auf einer Liste**: Die Warteschlangen, die ein Bereich auf den Relays hat, sind an einer Stelle gesammelt, und die Prüfungen schlagen fehl, wenn eine neue Art Warteschlange entsteht, ohne dort eingetragen zu sein, damit Von überall löschen keine zurücklässt.",
  "**Matrix, XMPP and Nostr on a linked computer**: linking a computer can bring this space's Matrix and XMPP accounts and the key of its Nostr chats over too, each signed in there as a new device of its own; for a computer linked already, tap Send the accounts under it on the phone. A Matrix server seldom lets the phone sign the computer in: the computer then asks for the Matrix password once, and the account's keys come from the phone, so no Security Key or check by emoji is needed. See [Linked devices](#devices).":
    "**Matrix, XMPP und Nostr auf einem verknüpften Computer**: Beim Verknüpfen eines Computers können die Matrix- und XMPP-Konten dieses Bereichs und der Schlüssel seiner Nostr-Chats gleich mit hinüberkommen, jedes dort als eigenes neues Gerät angemeldet; bei einem schon verknüpften Computer tippe auf dem Telefon unter ihm auf „Konten senden“. Ein Matrix-Server lässt das Telefon den Computer nur selten anmelden: Der Computer fragt dann einmal nach dem Matrix-Passwort, und die Schlüssel des Kontos kommen vom Telefon, sodass weder ein Sicherheitsschlüssel noch eine Prüfung per Emoji nötig ist. Siehe [Verknüpfte Geräte](#devices).",
  "**Only the SMS**: with Erevos locked, the SMS icon, the widget's SMS button and the notice of a new SMS ask for the password, then open only the SMS. Anything else, and the orange padlock **Unlock everything**, asks for it again, then opens all of Erevos. See [Password lock](#lock).":
    "**Nur die SMS**: Bei gesperrtem Erevos fragen das SMS-Symbol, die SMS-Taste des Widgets und die Benachrichtigung über eine neue SMS nach dem Passwort und öffnen dann nur die SMS. Alles andere, auch das orange Schloss **Alles entsperren**, fragt erneut danach und öffnet dann ganz Erevos. Siehe [Passwortsperre](#lock).",
  "**Nostr chats with a key brought from another app get their messages again**: Erevos reads where that app said your messages arrive, as that app does, instead of its own three relays, fetches the messages kept there and in older lists of the key, and reads a relay again when it stops sending. Before, such a key could show its chats with no past messages and get no new ones. See [Chats with other Nostr apps](#nostr-chats).":
    "**Nostr-Chats mit einem Schlüssel aus einer anderen App bekommen ihre Nachrichten wieder**: Erevos liest dort, wo diese App angegeben hat, dass deine Nachrichten ankommen, so wie diese App es tut, statt auf seinen eigenen drei Relays, holt die Nachrichten, die dort und in älteren Listen des Schlüssels aufbewahrt werden, und liest ein Relay erneut, wenn es aufhört zu senden. Vorher konnte ein solcher Schlüssel seine Chats ohne frühere Nachrichten zeigen und keine neuen bekommen. Siehe [Chats mit anderen Nostr-Apps](#nostr-chats).",
  "**Backups keep what closed chats need**: a backup now also holds what lets hidden chats ring a call and say a message came while they are closed, and a closed space say one came. So after a restore, on another phone too, **Ring calls when closed**, **Say when a message comes** and **Also while another space is open** go on as they were. See [Backups](#backup).":
    "**Backups behalten, was geschlossene Chats brauchen**: Ein Backup enthält jetzt auch, womit versteckte Chats bei Anrufen klingeln und melden, dass eine Nachricht kam, während sie geschlossen sind, und ein geschlossener Bereich meldet, dass eine kam. So laufen **Klingeln bei Anrufen, wenn geschlossen**, **Melden, wenn eine Nachricht kommt** und **Auch, wenn ein anderer Bereich offen ist** nach einer Wiederherstellung, auch auf einem anderen Telefon, weiter wie zuvor. Siehe [Backups](#backup).",
  "**Open another space from the search**: type another space's password in **Search chats** on the home screen and press Enter: the open space closes, nothing of it stays, and the other opens, as with **Lock now** and its password. It takes as long whatever is typed, and a wrong password, or the open space's own, is just a search. See [Second password](#second).":
    "**Einen anderen Bereich aus der Suche öffnen**: Tippe das Passwort eines anderen Bereichs in **Chats durchsuchen** auf dem Startbildschirm und drücke Enter: Der offene Bereich schließt sich, nichts von ihm bleibt, und der andere öffnet sich, wie mit **Jetzt sperren** und seinem Passwort. Es dauert gleich lang, was auch immer du tippst, und ein falsches Passwort oder das des offenen Bereichs ist nur eine Suche. Siehe [Zweites Passwort](#second).",
  "**A dot for unread messages elsewhere, if you want it**: hidden chats with **Receive while closed** can show a small dot on the magnifier of **Search chats** while they have a message unread (their switch **Dot for unread messages**), and a space set to say a message came while another is open can show one on the padlock at the top of the other spaces' chats (**Dot in the other spaces**). Never how many, nor where; off unless you turn it on. See [Hidden chats](#hidden).":
    "**Ein Punkt für Ungelesenes anderswo, wenn du ihn willst**: Versteckte Chats mit **Empfangen, wenn geschlossen** können einen kleinen Punkt auf der Lupe von **Chats durchsuchen** zeigen, solange sie eine ungelesene Nachricht haben (ihr Schalter **Punkt für Ungelesenes**), und ein Bereich, der meldet, dass eine Nachricht kam, während ein anderer offen ist, kann einen auf dem Schloss über den Chats der anderen Bereiche zeigen (**Punkt in den anderen Bereichen**). Nie wie viele, noch wo; aus, außer du schaltest es ein. Siehe [Versteckte Chats](#hidden).",
  "**Joining takes only the invite**: on a phone with no relay yet, **New chat** shows one way in, **I have an invite**. Signing in with LPHL, **Start without a relay** and the relay's settings are under **For advanced users**, for whoever looks for them. And an invite to your relay gives the relay only a name of random letters and digits for the phone it lets in: the name you type stays on your phone, where your list of invites shows it. See [Chat through a relay](#relay).":
    "**Zum Beitreten reicht die Einladung**: Auf einem Telefon noch ohne Relay zeigt **Neuer Chat** einen Weg hinein, **Ich habe eine Einladung**. Die Anmeldung mit LPHL, **Ohne Relay anfangen** und die Einstellungen des Relays stehen unter **Für Fortgeschrittene**, für wen sie sucht. Und eine Einladung zu deinem Relay gibt dem Relay für das Telefon, das sie hereinlässt, nur einen Namen aus zufälligen Buchstaben und Ziffern: Der Name, den du eingibst, bleibt auf deinem Telefon, wo ihn deine Liste der Einladungen zeigt. Siehe [Chat über ein Relay](#relay).",
  "**Invited phones stay**: on a relay of this version, a phone you invited keeps its access even once yours goes, and so do the phones it invited; taking back an invite cuts off that one phone alone. See [Chat through a relay](#relay).":
    "**Eingeladene Telefone bleiben**: Auf einem Relay dieser Version behält ein Telefon, das du eingeladen hast, seinen Zugang, auch wenn deiner geht, und ebenso die Telefone, die es eingeladen hat; eine Einladung zurückzunehmen sperrt nur dieses eine Telefon aus. Siehe [Chat über ein Relay](#relay).",
  "**Backups bring the phone back as it was**: a backup now holds the photos, files and voice messages too, in files of their own beside it, each sealed and bound to its backup; and the panic password, the settings that go with you, the Phone's quick replies and the calls it turns away, the SMS for later and automatic backups with their server, but not their folder. An SMS for later whose time passed before the restore waits for you to send it or delete it. What stays with each phone, as the fingerprint, the folders and what Android allows, never comes back: after a restore, Android's permissions open for the modules that are on. See [Backups](#backup).":
    "**Backups bringen das Telefon zurück, wie es war**: Ein Backup enthält jetzt auch die Fotos, Dateien und Sprachnachrichten, in eigenen Dateien daneben, jede versiegelt und an ihr Backup gebunden; und das Panik-Passwort, die Einstellungen, die mit dir gehen, die Schnellantworten des Telefons und die Anrufe, die es abweist, die SMS für später und automatische Backups mit ihrem Server, aber ohne ihren Ordner. Eine SMS für später, deren Zeit vor der Wiederherstellung vorbei war, wartet, bis du sie sendest oder löschst. Was bei jedem Telefon bleibt, wie der Fingerabdruck, die Ordner und was Android erlaubt, kommt nie zurück: Nach einer Wiederherstellung öffnen sich die Berechtigungen von Android für die eingeschalteten Module. Siehe [Backups](#backup).",
  "**A newer backup asks for a newer Erevos**: a backup made by a newer Erevos than yours is refused, with nothing changed, and Erevos asks you to update to the latest version first. An Erevos from before 6.0.0 does not open backups from 6.0.0 on: update it, then restore. See [Backups](#backup).":
    "**Ein neueres Backup braucht ein neueres Erevos**: Ein Backup, das ein neueres Erevos als deines gemacht hat, wird abgelehnt, und nichts ändert sich; Erevos bittet dich, zuerst auf die neueste Version zu aktualisieren. Ein Erevos vor 6.0.0 öffnet keine Backups ab 6.0.0: Aktualisiere es, dann stelle wieder her. Siehe [Backups](#backup).",
  "**Shared into the Collection with no plain copy**: a photo or file another app shares with Erevos is encrypted as it comes in, before **Send to** opens, so on its way into the Collection it never lies unencrypted on the phone. It can be up to 4 GB there, and a large one shows how far it is encrypted, with **Cancel**; a chat still takes 100 MB at most. See [Collection](#collection).": "**Ohne unverschlüsselte Kopie in die Sammlung geteilt**: Ein Foto oder eine Datei, die eine andere App mit Erevos teilt, wird schon beim Ankommen verschlüsselt, bevor **Senden an** aufgeht, und liegt so auf dem Weg in die Sammlung nie unverschlüsselt auf dem Telefon. Dort darf sie bis 4 GB groß sein; ein Chat nimmt weiter höchstens 100 MB. Bei einer großen zeigt sich, wie weit sie verschlüsselt ist, mit **Abbrechen**. Siehe [Sammlung](#collection).",
  "**See a file come from the WebDAV server**: a file of the Collection that is not on this device, as after a backup restored on a new phone, shows how much of it has come from the server, and **Cancel** stops it; what came stays, and the next time only the rest comes. Music, videos, PDFs and **Open with another app** fetch it first too, instead of failing. See [Collection](#collection).": "**Sieh zu, wie eine Datei vom WebDAV-Server kommt**: Eine Datei der Sammlung, die nicht auf diesem Gerät ist, etwa nach einer auf einem neuen Telefon wiederhergestellten Sicherung, zeigt, wie viel davon schon vom Server gekommen ist, und **Abbrechen** hält es an; was da ist, bleibt, und beim nächsten Mal kommt nur der Rest. Musik, Videos, PDFs und **Mit anderer App öffnen** holen sie jetzt auch zuerst, statt zu scheitern. Siehe [Sammlung](#collection).",
  "**Backups skip what is on the WebDAV server after a restart too**: that a Collection's copies on its server are complete is kept with it, so a backup made after Erevos starts again still leaves its pieces out, as long as no file was added or deleted since. **The connection works.** now shows in the colour of success, not of a warning. See [Collection](#collection).": "**Sicherungen lassen auch nach einem Neustart weg, was auf dem WebDAV-Server ist**: Dass die Kopien einer Sammlung auf ihrem Server vollständig sind, wird mit ihr gespeichert, sodass eine Sicherung nach einem Neustart von Erevos ihre Teile weiterhin weglässt, solange seitdem keine Datei hinzugefügt oder gelöscht wurde. **Die Verbindung funktioniert.** erscheint jetzt in der Farbe des Erfolgs, nicht einer Warnung. Siehe [Sammlung](#collection).",
  "**Notes from another app**: an app on the phone, as Fasouli for a payment that is coming, can ask to keep a note with its reminder in Chat with myself. Erevos asks you first, in the space you open. See [Getting started](#start).":
    "**Notizen aus einer anderen App**: Eine App auf dem Telefon, wie Fasouli für eine anstehende Zahlung, kann darum bitten, eine Notiz mit ihrer Erinnerung im Chat mit mir selbst zu behalten. Erevos fragt dich zuerst, in dem Bereich, den du öffnest. Siehe [Erste Schritte](#start).",
  "**Payment requests**: another app, as Fasouli, can ask Erevos to send one to a contact: an amount and what it is for, as a card. They tap **Paid** once they paid, and **Mark in Fasouli** then marks it collected there. Erevos moves no money. See [Chat through a relay](#relay).":
    "**Zahlungsanfragen**: Eine andere App wie Fasouli kann Erevos bitten, einem Kontakt eine zu senden: ein Betrag und wofür, als Karte. Der Kontakt tippt **Bezahlt**, sobald bezahlt ist, und **In Fasouli vermerken** vermerkt sie dort als eingenommen. Erevos bewegt kein Geld. Siehe [Chat über ein Relay](#relay).",
  "**Panic tells Fasouli too**: on Android, under Settings → Privacy and security → Panic button → **Tell other apps**, choose the apps Erevos tells as it wipes, as a panic app does: Fasouli then locks itself. Each asks you first. See [Panic button](#panic).":
    "**Panik benachrichtigt auch Fasouli**: Unter Android, in Einstellungen → Privatsphäre und Sicherheit → Panik-Taste → **Andere Apps benachrichtigen**, wählst du die Apps, die Erevos beim Löschen benachrichtigt, wie eine Panik-App: Fasouli sperrt sich dann. Jede fragt dich zuerst. Siehe [Panikknopf](#panic).",
  "**The Collection in the browser and on Sailfish OS**: the web app, on an iPhone's home screen too, and Erevos on Sailfish OS have the Collection now. A file is encrypted a piece at a time as it is read, and if the browser runs out of room nothing of it is kept. Photos, text, music and videos up to 256 MB open in memory only; a PDF is saved to be read elsewhere. See [Collection](#collection).":
    "**Die Sammlung im Browser und auf Sailfish OS**: Die Web-App, auch auf dem Startbildschirm eines iPhones, und Erevos auf Sailfish OS haben jetzt die Sammlung. Eine Datei wird Stück für Stück verschlüsselt, während sie gelesen wird, und hat der Browser keinen Platz mehr, wird nichts von ihr behalten. Fotos, Texte, Musik und Videos bis 256 MB öffnen sich nur im Speicher; ein PDF wird gespeichert, um es woanders zu lesen. Siehe [Sammlung](#collection).",
  "**Large files saved from the Collection on Sailfish OS**: **Save to phone** writes a file of any size to Downloads a piece at a time, as the desktop app now does too, and when the disk has no room left Erevos says so and leaves nothing half-written. See [Collection](#collection).":
    "**Große Dateien aus der Sammlung auf Sailfish OS speichern**: **Auf dem Telefon speichern** schreibt eine Datei jeder Größe Stück für Stück in Downloads, wie jetzt auch die Desktop-App, und wenn auf dem Datenträger kein Platz mehr ist, sagt Erevos das und lässt nichts halb Geschriebenes zurück. Siehe [Sammlung](#collection).",
  "**Sign in with Nextcloud**: a Collection's server and the backups' server can now be your Nextcloud, as LPHL's, the one Fasouli syncs with, without typing a password: tap **Sign in with Nextcloud**, sign in in the browser and grant access. Erevos gets an app password of its own and its own folder there, Erevos/Collection or Erevos/Backups. See [Collection](#collection).":
    "**Mit Nextcloud anmelden**: Der Server einer Sammlung und der Server der Sicherungen können jetzt deine Nextcloud sein, etwa die von LPHL, mit der Fasouli synchronisiert, ohne ein Passwort einzutippen: Tippe auf **Mit Nextcloud anmelden**, melde dich im Browser an und gewähre Zugriff. Erevos bekommt ein eigenes App-Passwort und einen eigenen Ordner dort, Erevos/Collection oder Erevos/Backups. Siehe [Sammlung](#collection).",
  "**Web app and Sailfish OS fixes from the review**: in the web app, each space that turns notifications on gets a push address of its own, from a service worker of its own, so a relay is never given another space's address and it never ties two spaces together; the browser's settings then list one service worker for each such space. A check for a new release that was slow to answer no longer brings back the release just replaced. On Sailfish OS, another app on the phone can no longer make Erevos hold on to memory, nor give orders to the helper that waits at the relay while Erevos is out of sight. See [On an iPhone](#iphone).":
    "**Korrekturen aus der Prüfung in der Web-App und auf Sailfish OS**: In der Web-App bekommt jeder Bereich, der Benachrichtigungen einschaltet, eine eigene Push-Adresse von einem eigenen Service Worker, sodass ein Relay nie die Adresse eines anderen Bereichs bekommt und sie nie zwei Bereiche miteinander verbindet; die Einstellungen des Browsers listen dann einen Service Worker für jeden solchen Bereich. Eine Suche nach einer neuen Version, die spät antwortet, holt die gerade ersetzte Version nicht mehr zurück. Auf Sailfish OS kann eine andere App auf dem Telefon Erevos nicht mehr Speicher festhalten lassen und dem Helfer, der am Relay wartet, solange Erevos nicht zu sehen ist, keine Befehle mehr geben. Siehe [Auf einem iPhone](#iphone).",
  "**Photos of the Collection one after the other**: in a photo, the arrows (on a phone too, while the bars show) or a swipe go to the next or the one before, and **Slideshow** shows them by themselves, one every 4 seconds, till a tap. On a computer, in a browser and on Sailfish OS a photo opens again instead of staying at **Opening the photo…**. See [Collection](#collection).": "**Fotos der Sammlung nacheinander**: in einem Foto führen die Pfeile (auch auf dem Telefon, solange die Leisten zu sehen sind) oder ein Wischen zum nächsten oder vorigen, und **Diashow** zeigt sie von selbst, alle 4 Sekunden eines, bis zu einem Tippen. Auf dem Computer, im Browser und auf Sailfish OS öffnet sich ein Foto wieder, statt bei **Foto wird geöffnet…** zu bleiben. Siehe [Sammlung](#collection).",
  "**Reminders that come again**: a note Fasouli keeps for a scheduled payment now reminds you each time it is due, every month or as the payment repeats, and shows how often. Once you see it, it moves to its next time. See [Getting started](#start).":
    "**Erinnerungen, die wiederkommen**: Eine Notiz, die Fasouli für eine geplante Zahlung anlegt, erinnert dich jetzt jedes Mal, wenn sie fällig ist, jeden Monat oder wie sich die Zahlung wiederholt, und zeigt, wie oft. Sobald du sie gesehen hast, rückt sie zum nächsten Termin vor. Siehe [Getting started](#start).",
  "**Who is online on Matrix and XMPP**: under a contact's name it says, as their server does, **Online**, **Away** or **Do not disturb**, with the words they set, or when they were last online, and their picture in the chat list has a green dot. On Matrix, Erevos no longer says you are online unless you turn on **Say when I am online** on the Matrix screen. See [Matrix](#matrix).":
    "**Wer auf Matrix und XMPP online ist**: Unter dem Namen eines Kontakts steht, wie sein Server es sagt, **Online**, **Abwesend** oder **Nicht stören**, mit den Worten, die er gesetzt hat, oder wann er zuletzt online war, und sein Bild in der Chatliste hat einen grünen Punkt. Auf Matrix sagt Erevos nicht mehr, dass du online bist, außer du schaltest **Sagen, wenn ich online bin** auf dem Matrix-Bildschirm ein. Siehe [Matrix](#matrix).",
  "**Link a computer with one tap**: on the computer, **Linked devices** now shows a small code at once. Scan it with the phone and tap **Link**: the phone gives the computer what it needs through Nostr, end-to-end encrypted, and nothing has to be typed or compared. If Nostr cannot be reached, **Link another way** keeps the old way. See [Linked devices](#devices).":
    "**Einen Computer mit einem Tipp verknüpfen**: Auf dem Computer zeigen die **Verknüpften Geräte** jetzt sofort einen kleinen Code. Scanne ihn mit dem Telefon und tippe auf **Verknüpfen**: Das Telefon gibt dem Computer über Nostr, Ende-zu-Ende-verschlüsselt, was er braucht, und nichts muss eingetippt oder verglichen werden. Ist Nostr nicht erreichbar, bleibt der alte Weg mit **Anders verknüpfen**. Siehe [Verknüpfte Geräte](#devices).",
  '**Choose the name others see**: under Settings → Privacy and security → **My name**, give this space a name that your contacts and your private groups see instead of a code, always encrypted. Hidden chats have a name of their own, in their settings, empty at first. See [Chat through a relay](#relay).':
    '**Wähle den Namen, den andere sehen**: Unter Einstellungen → Datenschutz und Sicherheit → **Mein Name** gibst du diesem Space einen Namen, den deine Kontakte und deine privaten Gruppen statt eines Codes sehen, immer verschlüsselt. Versteckte Chats haben einen eigenen Namen, in ihren Einstellungen, zuerst leer. Siehe [Chat über ein Relay](#relay).',
  "**Folders in Chat with myself**: notes, photos, files and voice messages can now go in folders. The folder button at the top makes one; its tab above the notes then shows only what is in it, and what you write while it is chosen goes into it. Holding a note offers **Move to a folder**; holding a folder's tab renames or deletes it, its notes staying. The folders go to your linked devices with the notes. See [Getting started](#start).":
    "**Ordner im Chat mit mir selbst**: Notizen, Fotos, Dateien und Sprachnachrichten können jetzt in Ordner. Die Ordner-Taste oben legt einen an; sein Tab über den Notizen zeigt dann nur, was darin liegt, und was du schreibst, während er gewählt ist, kommt hinein. Eine Notiz gedrückt halten bietet **In einen Ordner verschieben**; den Tab eines Ordners gedrückt halten benennt ihn um oder löscht ihn, seine Notizen bleiben. Die Ordner gehen mit den Notizen an deine verknüpften Geräte. Siehe [Erste Schritte](#start).",
  "**The battery mode And sleep spares more**: each time it wakes the phone to look, about once a minute, the phone now sleeps again within a second or two when nothing came, not after 25 seconds.":
    "**Die Akkustufe „Und Schlaf“ spart mehr**: Jedes Mal, wenn sie das Telefon zum Nachschauen weckt, etwa einmal pro Minute, schläft das Telefon jetzt innerhalb von ein, zwei Sekunden wieder ein, wenn nichts gekommen ist, nicht erst nach 25 Sekunden.",
  "**Messages come at once while Erevos shows**: Erevos now waits at your relay with the connection open also while it is on the screen, so a message or a call comes the moment it is sent, not at the next look every 3 seconds, and the phone's radio rests in between.":
    "**Nachrichten kommen sofort, während Erevos zu sehen ist**: Erevos wartet jetzt auch dann mit offener Verbindung an deinem Relay, wenn es auf dem Bildschirm ist, sodass eine Nachricht oder ein Anruf in dem Moment kommt, in dem sie gesendet werden, nicht erst beim nächsten Nachschauen alle 3 Sekunden, und der Funk des Telefons ruht dazwischen.",
  "**A new battery mode, And light sleep**: under Settings → Notifications → In the background. The phone may sleep, and what comes to your relay wakes it, so messages and calls still come at once where the network and Android allow it. It is new: if messages come late with it, choose another.":
    "**Eine neue Akkustufe, „Und leichter Schlaf“**: unter Einstellungen → Benachrichtigungen → Im Hintergrund. Das Telefon darf schlafen, und was an deinem Relay ankommt, weckt es, sodass Nachrichten und Anrufe weiterhin sofort kommen, wo Netz und Android es zulassen. Sie ist neu: Kommen Nachrichten damit verspätet, wähle eine andere.",
  "**Chats are saved faster**: a message that comes, is read or is deleted is saved by looking only at its own chat, which shows most with many chats or after a large import. The chat screen is no longer drawn again every 5 seconds.":
    "**Chats werden schneller gespeichert**: Eine Nachricht, die kommt, gelesen oder gelöscht wird, wird gespeichert, indem nur ihr eigener Chat angesehen wird, was sich vor allem bei vielen Chats oder nach einem großen Import zeigt. Der Chat-Bildschirm wird nicht mehr alle 5 Sekunden neu gezeichnet.",
  "**Large imports write less**: the note of the files an import is still writing is kept in small parts, not written whole for every file.":
    "**Große Importe schreiben weniger**: Die Notiz über die Dateien, die ein Import noch schreibt, wird in kleinen Teilen gehalten und nicht für jede Datei ganz geschrieben.",
  "**A text no longer waits for slow Nostr relays**: with Nostr on, a text waited for a Nostr relay to say it took it, up to 20 seconds when none answered, before it went through the relay. Now, when none says so within 4 seconds, it goes through the relay as well at once.":
    "**Eine Nachricht wartet nicht mehr auf langsame Nostr-Relays**: Mit Nostr an wartete eine Nachricht, bis ein Nostr-Relay sagte, dass es sie nahm, bis zu 20 Sekunden, wenn keines antwortete, bevor sie über das Relay ging. Sagt das jetzt keines innerhalb von 4 Sekunden, geht sie sofort auch über das Relay.",
  "**Voice messages in Opus**: on Android 10 and later, in the web app and on a computer, voice messages are recorded as Ogg/Opus, as Telegram and Element send them: as clear as before at half the size, about 240 KB a minute. Every Erevos plays them, Safari on an older iPhone too. See [Chat through a relay](#relay).":
    "**Sprachnachrichten in Opus**: Auf Android 10 und neuer, in der Web-App und auf einem Computer werden Sprachnachrichten als Ogg/Opus aufgenommen, wie Telegram und Element sie senden: so klar wie vorher bei halber Größe, etwa 240 KB pro Minute. Jedes Erevos spielt sie ab, auch Safari auf einem älteren iPhone. Siehe [Chat über ein Relay](#relay).",
  "**Mark all as read**: the ⋮ menu of the chats has it for the part of the list you are on, all messages, SMS, Erevos, Matrix, XMPP or Nostr, and the Matrix, XMPP and Nostr screens have it for their chats. It asks first, then reads each chat as opening it would: those who wrote are told as then. See [Getting started](#start).":
    "**Alle als gelesen markieren**: Das ⋮-Menü der Chats hat es für den Teil der Liste, in dem du bist, alle Nachrichten, SMS, Erevos, Matrix, XMPP oder Nostr, und die Matrix-, XMPP- und Nostr-Bildschirme haben es für ihre Chats. Es fragt zuerst, dann liest es jeden Chat, wie das Öffnen es täte: Wer geschrieben hat, erfährt es wie dann. Siehe [Erste Schritte](#start).",
  "**Answer with video, or voice only**: an incoming call, Erevos, group, XMPP or Matrix, now offers both. You can add video to an Erevos voice call while it goes on, and Flip on a computer moves to your next camera. See [Chat through a relay](#relay).":
    "**Mit Video oder nur mit Stimme annehmen**: Ein eingehender Anruf, Erevos, Gruppe, XMPP oder Matrix, bietet jetzt beides. Du kannst einem Erevos-Sprachanruf Video hinzufügen, während er läuft, und Wechseln auf dem Computer geht zu deiner nächsten Kamera. Siehe [Chat über ein Relay](#relay).",
  "**Voice messages, places, contact cards and pins in SMS**: in an SMS conversation, hold the microphone to send a voice message by MMS. **+** also sends where you are, as an SMS with a map link any phone opens, and a contact from your phone as a contact card. Voice messages, contact cards and map links you receive show as such, to play, save or open. Hold a message down to **Pin for me**, kept only on this phone, or **Select** several to copy, forward or delete them together. See [SMS](#sms).":
    "**Sprachnachrichten, Orte, Kontaktkarten und Anheftungen in SMS**: In einer SMS-Unterhaltung hältst du das Mikrofon gedrückt, um eine Sprachnachricht per MMS zu senden. **+** sendet auch, wo du bist, als SMS mit einem Kartenlink, den jedes Telefon öffnet, und einen Kontakt deines Telefons als Kontaktkarte. Sprachnachrichten, Kontaktkarten und Kartenlinks, die du erhältst, erscheinen als solche, zum Abspielen, Speichern oder Öffnen. Halte eine Nachricht gedrückt für **Für mich anheften**, nur auf diesem Telefon gespeichert, oder für **Auswählen** mehrerer, um sie zusammen zu kopieren, weiterzuleiten oder zu löschen. Siehe [SMS](#sms).",
  "**More in XMPP chats**: voice messages from other XMPP apps now play in the chat and show how long they are; **Sticker** sends your own photo stickers as photos, encrypted as the chat is; groups show who is **owner** or **admin**, and the owner can set the group's **Description**; **Forward** sends one or several messages to another XMPP chat; tapping a quoted reply goes to the message; **Pin for me** keeps a message at the top on this phone only; and **Select** chooses several messages to copy, forward or delete. See [XMPP](#xmpp).":
    "**Mehr in XMPP-Chats**: Sprachnachrichten aus anderen XMPP-Apps werden jetzt im Chat abgespielt und zeigen ihre Länge; **Sticker** sendet deine eigenen Foto-Sticker als Fotos, verschlüsselt wie der Chat; Gruppen zeigen, wer **Inhaber** oder **Admin** ist, und der Inhaber kann die **Beschreibung** der Gruppe setzen; **Weiterleiten** sendet eine oder mehrere Nachrichten in einen anderen XMPP-Chat; ein Tippen auf eine zitierte Antwort geht zur Nachricht; **Für mich anheften** hält eine Nachricht oben, nur auf diesem Telefon; und **Auswählen** wählt mehrere Nachrichten zum Kopieren, Weiterleiten oder Löschen. Siehe [XMPP](#xmpp).",
  "**More in Nostr chats**: tap a reaction to add it or take yours back, pin messages for yourself, select several to copy, forward or delete, send your own photo stickers, and see, vote on and make polls in the Public feed. See [Chats with other Nostr apps](#nostr-chats).":
    "**Mehr in Nostr-Chats**: Tippe auf eine Reaktion, um sie hinzuzufügen oder deine zurückzunehmen, hefte Nachrichten für dich an, wähle mehrere zum Kopieren, Weiterleiten oder Löschen, sende deine eigenen Foto-Sticker und sieh, beantworte und erstelle Umfragen im öffentlichen Feed. Siehe [Chats mit anderen Nostr-Apps](#nostr-chats).",
  "**Matrix groups and stickers**: in a Matrix group, **Members** shows who is in it and who is an admin or moderator, and lets admins rename it, set its subject, make admins, and take people out or bar them. Stickers sent from Element and other Matrix apps now show, and your own stickers made from photos can be sent. **New chat** can find people by name, and **Select** in a message's menu chooses several messages to copy, forward or delete. See [Matrix](#matrix).":
    "**Matrix-Gruppen und Sticker**: In einer Matrix-Gruppe zeigt **Mitglieder**, wer drin ist und wer Admin oder Moderator ist, und lässt Admins sie umbenennen, ihren Betreff setzen, Admins ernennen und Leute entfernen oder sperren. Sticker, die aus Element und anderen Matrix-Apps gesendet werden, erscheinen jetzt, und deine eigenen aus Fotos gemachten Sticker lassen sich senden. **Neuer Chat** findet Leute nach Namen, und **Auswählen** im Menü einer Nachricht wählt mehrere Nachrichten zum Kopieren, Weiterleiten oder Löschen. Siehe [Matrix](#matrix).",
  "**More in your chats and groups**: choose several messages to copy, forward or delete at once; end your polls; reply in threads in groups; give a group a description; and send a contact from your phone as a card. See [Chat through a relay](#relay) and [Group chats](#groups).":
    "**Mehr in deinen Chats und Gruppen**: Wähle mehrere Nachrichten, um sie auf einmal zu kopieren, weiterzuleiten oder zu löschen; beende deine Umfragen; antworte in Gruppen in Threads; gib einer Gruppe eine Beschreibung; und sende einen Kontakt deines Telefons als Karte. Siehe [Chat über ein Relay](#relay) und [Gruppenchats](#groups).",
  "**Ticks**: a text the other phone had, and read, before it showed as sent here (through a slow Nostr relay) now shows as read, not with one tick. Ticks from a contact on another relay no longer stop, and a text that reaches a phone while Erevos is in the background there gets its second tick at that phone's next check.":
    "**Haken**: Ein Text, den das andere Telefon schon hatte und gelesen hatte, bevor er hier als gesendet erschien (über ein langsames Nostr-Relay), erscheint jetzt als gelesen, nicht mit einem Haken. Haken von einem Kontakt auf einem anderen Relay bleiben nicht mehr aus, und ein Text, der ein Telefon erreicht, während Erevos dort im Hintergrund ist, bekommt seinen zweiten Haken bei der nächsten Abfrage dieses Telefons.",
  "**Stickers on other networks**: a built-in sticker sent on Matrix, XMPP, Nostr or by MMS arrives as its picture, made on your device, its words in your language. See [Chat through a relay](#relay).":
    "**Sticker in anderen Netzen**: Ein eingebauter Sticker, den du über Matrix, XMPP, Nostr oder per MMS sendest, kommt als sein Bild an, auf deinem Gerät gemacht, seine Worte in deiner Sprache. Siehe [Chat über ein Relay](#relay).",
  "**One button for all your services**: under the search on the home screen, one button says which service shows, with the messages not read and any service not connected now. Tap it for a window with every service as a card, each with its own number and a dot for its connection; **Add** turns more on, and holding a card moves it or hides it. With no search, the chats with messages not read come first, under **Unread**, then the rest under **Recent**. See [Getting started](#start).":
    "**Eine Schaltfläche für all deine Dienste**: Unter der Suche auf dem Startbildschirm sagt eine Schaltfläche, welcher Dienst zu sehen ist, mit den ungelesenen Nachrichten und jedem Dienst, der gerade nicht verbunden ist. Tippe darauf für ein Fenster mit jedem Dienst als Karte, jede mit ihrer eigenen Zahl und einem Punkt für ihre Verbindung; **Hinzufügen** schaltet weitere ein, und gedrückt halten verschiebt oder blendet eine Karte aus. Ohne Suche kommen zuerst die Chats mit ungelesenen Nachrichten, unter **Ungelesen**, dann die übrigen unter **Zuletzt**. Siehe [Erste Schritte](#start).",
  "**Share an imported chat with the other person**: a Telegram, WhatsApp or Viber chat that goes on with an Erevos contact can now go to them too, from the chat's **Details** or **Settings** → **Data and devices** → **Imported chats**: every message, photo, video, voice message and file, end-to-end encrypted, to them alone, whatever its size. Their Erevos keeps the messages at once and shows them ahead of the new messages, the sides swapped; the files follow in rounds through your relay while both phones run Erevos, each up to 4 GB, as large as an import now keeps. See [Imported chats](#import).":
    "**Einen importierten Chat mit der anderen Person teilen**: Ein Chat aus Telegram, WhatsApp oder Viber, der mit einem Erevos-Kontakt weitergeht, kann jetzt auch an diesen gehen, aus den **Details** des Chats oder unter **Einstellungen** → **Daten und Geräte** → **Importierte Chats**: jede Nachricht, jedes Foto und Video, jede Sprachnachricht und Datei, Ende-zu-Ende-verschlüsselt, nur an diesen Kontakt, ganz gleich, wie groß. Dessen Erevos behält die Nachrichten sofort und zeigt sie vor den neuen Nachrichten, mit vertauschten Seiten; die Dateien folgen in Runden über dein Relay, solange Erevos auf beiden Telefonen läuft, jede bis zu 4 GB, so groß, wie ein Import sie jetzt behält. Siehe [Importierte Chats](#import).",
  "**Tor for your XMPP account, and per chat**: on Android, the XMPP screen, and the one before signing in, chooses **Off** (the default), **As the space** or **Always through Tor** for the account: its connection, the look for its server and its files, never straight when it must not. **Through Tor** under any XMPP chat or group, off by default, sends the whole account only through Tor while on, as one connection carries all its chats. Calls do not go through Tor. Before you send while the account does not go through Tor, before a call and before a file from another server, Erevos says once that your internet address can be seen, and how not to. See [XMPP](#xmpp).":
    "**Tor für dein XMPP-Konto, und pro Chat**: Auf Android wählt der XMPP-Bildschirm, und der vor der Anmeldung, für das Konto **Aus** (die Voreinstellung), **Wie der Bereich** oder **Immer über Tor**: seine Verbindung, die Suche nach seinem Server und seine Dateien, nie direkt, wenn es nicht darf. **Über Tor** unter jedem XMPP-Chat oder jeder Gruppe, standardmäßig aus, schickt das ganze Konto nur über Tor, solange es an ist, da eine Verbindung alle seine Chats trägt. Anrufe gehen nicht über Tor. Bevor du sendest, solange das Konto nicht über Tor geht, vor einem Anruf und vor einer Datei von einem anderen Server sagt Erevos einmal, dass deine Internetadresse gesehen werden kann, und wie nicht. Siehe [XMPP](#xmpp).",
  "**Tor for Messenger and Signal, and per chat**: in Erevos+, the Messenger and Signal screens, and the ones before signing in, choose **Off** (the default), **As the space** or **Always through Tor** for the account. With it, everything of the account goes through Tor, its pictures and files too, and Messenger's sign-in page and Signal's registering, captcha and linking as well: never straight when it must not. **Through Tor** under any of their chats, off by default, sends the whole account only through Tor while on, as each has one connection. Calls do not go through Tor.":
    "**Tor für Messenger und Signal, auch je Chat**: In Erevos+ wählen die Bildschirme von Messenger und Signal, auch vor dem Anmelden, für das Konto **Aus** (Standard), **Wie der Bereich** oder **Immer über Tor**. Damit geht alles des Kontos über Tor, auch seine Bilder und Dateien, ebenso die Anmeldeseite von Messenger und bei Signal Registrieren, Captcha und Verknüpfen: nie direkt, wenn es nicht darf. **Über Tor** unter jedem ihrer Chats, standardmäßig aus, schickt das ganze Konto nur über Tor, solange es an ist, da jedes eine Verbindung hat. Anrufe gehen nicht über Tor.",
  "**Telegram: Tor as every account, and per chat**: on Android, **Tor for this Telegram account**, in Telegram's settings and before signing in, has **Off** (the default), **As the space** and **Always through Tor**, as every account of another network. With Always, or while the space sends Everything through Tor, Telegram is reached only through Tor, signing in too, and never straight, not even when Tor cannot connect. **Through Tor** in a Telegram chat's info sends that chat only through Tor, and with it the whole account, which has one connection. Calls do not go through Tor. See [Telegram (ErevosGram)](#telegram).":
    "**Telegram: Tor wie bei jedem Konto, und pro Chat**: unter Android hat **Tor für dieses Telegram-Konto**, in den Telegram-Einstellungen und schon vor der Anmeldung, **Aus** (so ist es zuerst), **Wie der Bereich** und **Immer über Tor**, wie jedes Konto eines anderen Netzes. Mit Immer, oder solange der Bereich Alles über Tor schickt, erreicht es Telegram nur über Tor, auch bei der Anmeldung, und nie direkt, auch nicht, wenn Tor keine Verbindung bekommt. **Über Tor** in den Infos eines Telegram-Chats schickt diesen Chat nur über Tor, und mit ihm das ganze Konto, das eine Verbindung hat. Anrufe gehen nicht über Tor. Siehe [Telegram (ErevosGram)](#telegram).",
  "**Nostr: Tor as every account, and per chat**: on Android, the **Nostr chats** screen, before a key is made or brought too, has **Off** (the default, also for keys from before), **As the space** and **Always through Tor** for the account: its relays, look-ups and file servers, never straight when it must not (Always, or the space's Everything). **Through Tor** at the foot of a Nostr chat, off by default, sends that chat alone only through Tor, on circuits of its own, whatever the account says; what comes to you follows the account. See [Chats with other Nostr apps](#nostr-chats).":
    "**Nostr: Tor wie bei jedem Konto, und pro Chat**: unter Android hat der Bildschirm **Nostr-Chats**, auch bevor ein Schlüssel gemacht oder mitgebracht ist, **Aus** (der Standard, auch für Schlüssel von vorher), **Wie der Bereich** und **Immer über Tor** für das Konto: seine Relays, Suchen und Dateiserver, nie direkt, wenn es nicht darf (Immer, oder Alles des Bereichs). **Über Tor** unten in einem Nostr-Chat, standardmäßig aus, schickt nur diesen Chat ausschließlich über Tor, auf eigenen Verbindungen, egal was das Konto sagt; was zu dir kommt, folgt dem Konto. Siehe [Chats mit anderen Nostr-Apps](#nostr-chats).",
  "**Telegram warns before your internet address can be seen**: once in each Telegram chat, before the first message, file, sticker, voice message, poll or forward while the account does not go through Tor, with **Through Tor** for that chat to fix it, **Guide** or **Go on**; before every Telegram call, made or answered, as calls never go through Tor; and before joining a group or channel by its link. See [Who sees your internet address](#ip).":
    "**Telegram warnt, bevor deine Internetadresse zu sehen ist**: einmal in jedem Telegram-Chat, vor der ersten Nachricht, Datei, dem ersten Sticker, der ersten Sprachnachricht, Umfrage oder Weiterleitung, solange das Konto nicht über Tor geht, mit **Über Tor** für diesen Chat als Abhilfe, **Anleitung** oder **Weiter**; vor jedem Telegram-Anruf, ob du anrufst oder annimmst, da Anrufe nie über Tor gehen; und bevor du einer Gruppe oder einem Kanal über seinen Link beitrittst. Siehe [Wer deine Internetadresse sieht](#ip).",
  "**Erevos or Erevos+, and betas, in Updates**: on Android, **Updates** now chooses the next update: **Erevos** or **Erevos+**, moving from one to the other with everything kept, and **Beta versions**, to join the betas, which come out first for trying, or leave them. See [Erevos or Erevos+, and betas](#updates).": "**Erevos oder Erevos+, und Betas, unter Updates**: Unter Android wählt **Updates** jetzt das nächste Update: **Erevos** oder **Erevos+**, mit Wechsel von einem zum anderen, bei dem alles bleibt, und **Beta-Versionen**, um bei den Betas mitzumachen, die zuerst zum Ausprobieren erscheinen, oder sie zu verlassen. Siehe [Erevos oder Erevos+, und Betas](#updates).",
  "**Matrix, XMPP and Nostr chats are in Erevos+**: Erevos now has its own chats, the Phone, SMS and the Collection, and Erevos+ has Matrix, XMPP and the chats with other Nostr apps besides. An account you had on them stays on the phone, encrypted, and Erevos says so once; choose **Erevos+** in **Updates** to have it again. Erevos's own messages still go through Nostr relays when no relay of yours takes them. See [Erevos or Erevos+, and betas](#updates).": "**Matrix-, XMPP- und Nostr-Chats sind in Erevos+**: Erevos hat jetzt seine eigenen Chats, das Telefon, SMS und die Sammlung, und Erevos+ hat außerdem Matrix, XMPP und die Chats mit anderen Nostr-Apps. Ein Konto, das du dort hattest, bleibt verschlüsselt auf dem Telefon, und Erevos sagt es einmal; wähle **Erevos+** unter **Updates**, um es wieder zu haben. Erevos' eigene Nachrichten gehen weiterhin über Nostr-Relays, wenn keines deiner Relays sie annimmt. Siehe [Erevos oder Erevos+, und Betas](#updates).",
  "**Radio and TV through Tor**: the Collection's settings on Android have **Play through Tor**, off unless you turn it on. On, stations and channels play only through Tor, so they do not see your IP address; TV may stall for a moment. Off, Erevos says before the first one plays that its server sees your IP address, with a button that turns it on. Before, they always played straight. See [Collection](#collection).": "**Radio und TV über Tor**: Die Einstellungen der Sammlung auf Android haben **Über Tor abspielen**, aus, solange du es nicht einschaltest. Eingeschaltet laufen Radio- und TV-Sender nur über Tor, sie sehen deine IP-Adresse also nicht; TV kann kurz hängen. Ausgeschaltet sagt Erevos, bevor der erste läuft, dass sein Server deine IP-Adresse sieht, mit einem Knopf, der es einschaltet. Vorher liefen sie immer direkt. Siehe [Sammlung](#collection).",
  "**A chat no longer freezes before a message sent for later shows**: a message your contact sends with **Send later** can come before its time, and shows only then. Until then its chat was marked read again and again without end, so it could stop answering: **⋮** opened nothing and **Back** did not leave it until Erevos was closed. Now such a message is read once it shows. See [Chat through a relay](#relay).": "**Ein Chat friert nicht mehr ein, bevor eine später gesendete Nachricht erscheint**: Eine Nachricht, die dein Kontakt mit **Später senden** schickt, kann vor ihrer Zeit ankommen und erscheint erst dann. Bis dahin wurde ihr Chat immer wieder ohne Ende als gelesen markiert, sodass er nicht mehr reagieren konnte: **⋮** öffnete nichts, und **Zurück** verließ ihn nicht, bis Erevos geschlossen wurde. Jetzt wird eine solche Nachricht gelesen, sobald sie erscheint. Siehe [Chat über ein Relay](#relay).",
  "**Choose the part Erevos opens on**: under **All services**, hold any card, **All messages** too, and choose **Opens first**. Erevos's icon in the launcher, and Erevos started with nothing else to open, then open on it; with none chosen, or the chosen one hidden, on **All messages**. Before, the icon always opened the Erevos chats. The widget's buttons still open their own. See [Getting started](#start).": "**Wähle, wo Erevos sich öffnet**: Halte unter **Alle Dienste** eine beliebige Karte gedrückt, auch **Alle**, und wähle **Öffnet zuerst**. Das Symbol von Erevos im Launcher und Erevos, wenn es ohne etwas anderes zu öffnen startet, öffnen sich dann dort; ohne Auswahl, oder wenn die gewählte ausgeblendet ist, bei **Alle**. Vorher öffnete das Symbol immer die Erevos-Chats. Die Tasten des Widgets öffnen weiterhin ihre eigenen. Siehe [Erste Schritte](#start).",
  "**Asked before strangers reach this phone**: an Erevos invite that comes by SMS is answered by itself only from a number in your contacts or one you have written to; from any other, Erevos asks first, as the sender of an SMS can be made up. A contact's invite to a place on their relay now says first that their relay sees your IP address, and is taken only if you go on. See [Who sees your internet address](#ip).": "**Erst fragen, bevor Fremde dieses Telefon erreichen**: Eine Erevos-Einladung, die per SMS kommt, wird nur von einer Nummer in deinen Kontakten oder einer, der du geschrieben hast, von selbst beantwortet; bei jeder anderen fragt Erevos zuerst, denn der Absender einer SMS kann gefälscht sein. Die Einladung eines Kontakts zu einem Platz auf seinem Relay sagt jetzt zuerst, dass sein Relay deine IP-Adresse sieht, und wird nur angenommen, wenn du weitermachst. Siehe [Wer deine Internetadresse sieht](#ip).",
  "**Notices in your language**: Android's own notices and screens, new versions, reminders, birthdays, calls, SMS codes and the contact picker, now speak German, Spanish, French, Italian, Portuguese and Serbo-Croatian too, not only Greek and English. Older Greek subtitles, not saved as UTF-8, now show as Greek on the computer. See [Collection](#collection).": "**Hinweise in deiner Sprache**: Die eigenen Hinweise und Bildschirme von Android, neue Versionen, Erinnerungen, Geburtstage, Anrufe, SMS-Codes und die Kontaktauswahl sprechen jetzt auch Deutsch, Spanisch, Französisch, Italienisch, Portugiesisch und Serbokroatisch, nicht nur Griechisch und Englisch. Ältere griechische Untertitel, die nicht als UTF-8 gespeichert waren, erscheinen auf dem Computer jetzt als Griechisch. Siehe [Sammlung](#collection).",
  "**Video calls on the computer, and the calculator after a wipe**: a video call started or answered on the computer now opens its camera. With the calculator in place of Erevos's icon, once Erevos is wiped by the panic password or **Clear storage**, the calculator opens Erevos as new and gives Erevos's icon back, where before no code opened it any more. See [Appearance](#appearance).": "**Videoanrufe auf dem Computer, und der Taschenrechner nach einer Löschung**: Ein Videoanruf, der auf dem Computer gestartet oder angenommen wird, öffnet jetzt seine Kamera. Wird Erevos bei einem Taschenrechner anstelle des Symbols von Erevos mit dem Panik-Passwort oder mit **Speicher löschen** gelöscht, öffnet der Taschenrechner Erevos als neu und gibt das Symbol von Erevos zurück; vorher öffnete es kein Code mehr. Siehe [Darstellung](#appearance).",
  "**Last seen starts off**: in a new space, **Last seen** is now off until you turn it on, so no contact sees when you last had Erevos open, and you see no one's either. A space you already have keeps it as it was. See [Chat through a relay](#relay).": "**Zuletzt online beginnt aus**: In einem neuen Bereich ist **Zuletzt online** jetzt aus, bis du es einschaltest; so sieht kein Kontakt, wann du Erevos zuletzt offen hattest, und du siehst auch niemandes. Ein Bereich, den du schon hast, behält es, wie es war. Siehe [Chat über ein Relay](#relay).",
  "**A chat with a big file no longer closes Erevos**: on Android, opening a chat that held a large file, or one shared in many pieces, could close Erevos at once. Now it opens. See [Chat through a relay](#relay).": "**Ein Chat mit einer großen Datei schließt Erevos nicht mehr**: Unter Android konnte das Öffnen eines Chats mit einer großen Datei, oder einer in vielen Teilen geteilten, Erevos sofort schließen. Jetzt öffnet er sich. Siehe [Chat über ein Relay](#relay).",
  "**A hidden service stays quiet**: a service you hide in the **Services** window, Messenger, Matrix, SMS or any other, no longer sends notifications or counts on Erevos's icon, as a muted chat. It stays connected and tells again once you show it. Telegram, whose folders can stand on home of their own, keeps telling. See [Getting started](#start).": "**Ein versteckter Dienst bleibt still**: Ein Dienst, den du im Fenster **Dienste** versteckst, Messenger, Matrix, SMS oder ein anderer, sendet keine Benachrichtigungen mehr und zählt nicht mehr in der Zahl am Erevos-Symbol, wie ein stummgeschalteter Chat. Er bleibt verbunden und meldet sich wieder, sobald du ihn zeigst. Telegram, dessen Ordner als eigene Dienste auf dem Startbildschirm stehen können, meldet sich weiter. Siehe [Getting started](#start).",
  "**Screenshots in hidden chats too, if you want**: hidden chats now follow **Screenshots** in **Privacy and security**: on, as it starts, they stay out of screenshots and the recent apps; turned off, screenshots work in them as in the other chats. Before, hidden chats always kept them out. See [Hidden chats](#hidden).": "**Bildschirmfotos auch in versteckten Chats, wenn du willst**: Versteckte Chats folgen jetzt **Bildschirmfotos** unter **Datenschutz und Sicherheit**: an, wie es beginnt, bleiben sie aus Bildschirmfotos und den letzten Apps heraus; aus, funktionieren Bildschirmfotos dort wie in den anderen Chats. Vorher blieben versteckte Chats immer heraus. Siehe [Versteckte Chats](#hidden).",
  "**Messenger signs in on facebook.com, and opens Facebook**: in Erevos+, Messenger now signs in on Facebook's own page. **Open Facebook** on the Messenger screen shows Facebook itself with the same sign-in: its Messenger links come back to Erevos's chats, and other links open in your browser without Facebook's tracking marks and never through Tor, so the site sees your internet address. An account signed in on messenger.com before signs out and in again once to open Facebook.":
    "**Messenger meldet sich auf facebook.com an und öffnet Facebook**: In Erevos+ meldet sich Messenger jetzt auf Facebooks eigener Seite an. **Facebook öffnen** auf dem Messenger-Bildschirm zeigt Facebook selbst mit derselben Anmeldung: Messenger-Links dort führen zurück zu den Chats von Erevos, und andere Links öffnen sich in deinem Browser ohne Facebooks Tracking-Markierungen und nie über Tor, sodass die Website deine Internetadresse sieht. Ein Konto, das früher auf messenger.com angemeldet wurde, meldet sich einmal ab und wieder an, um Facebook zu öffnen.",
  "**Messenger, Signal and Session chats send more, and stay read**: in Erevos+, **+** in their chats sends a photo from your photos or the camera, a file or a sticker, and the microphone records a voice message. Your own messages show their words, where before some came empty; tapping a person with no Messenger chat yet opens a new one; and chats you mark read no longer come back unread.":
    "**Messenger-, Signal- und Session-Chats senden mehr und bleiben gelesen**: In Erevos+ sendet **+** in ihren Chats ein Foto aus deinen Fotos oder von der Kamera, eine Datei oder einen Sticker, und das Mikrofon nimmt eine Sprachnachricht auf. Deine eigenen Nachrichten zeigen ihre Worte, wo früher manche leer kamen; ein Tippen auf eine Person ohne Messenger-Chat öffnet einen neuen; und als gelesen markierte Chats werden nicht wieder ungelesen.",
  "**Every copy carries its licences**: the Android app, the computer and Sailfish apps and the web app now carry the file NOTICES.txt, with Erevos's licence, AUTHORS.md and every package Erevos is built from, each with its licence text. See [Licence](#licence).": "**Jede Kopie enthält ihre Lizenzen**: die Android-App, die Computer- und Sailfish-Apps und die Web-App enthalten jetzt die Datei NOTICES.txt mit der Lizenz von Erevos, AUTHORS.md und jedem Paket, aus dem Erevos gebaut ist, jeweils mit seinem Lizenztext. Siehe [Lizenz](#licence).",
  "**A ready list of radio stations**: **Add a station** in the Collection's Radio now adds a country's most listened stations from Radio Browser at once, up to 100, with **Add the stations of this country**; the country is the phone's, and **Change** picks another. See [Collection](#collection).": "**Eine fertige Liste von Radiosendern**: **Sender hinzufügen** im Radio der Sammlung fügt jetzt die meistgehörten Sender eines Landes aus Radio Browser auf einmal hinzu, bis zu 100, mit **Sender dieses Landes hinzufügen**; das Land ist das des Telefons, und **Ändern** wählt ein anderes. Siehe [Sammlung](#collection).",
  "**A new look to start with**: Erevos, newly installed, starts in Glass (Panes), Modernist, System, My color in sky blue, the phone's letters and square messages. A look you chose before stays as it was. See [Appearance](#appearance).": "**Ein neues Aussehen zum Start**: Ein neu installiertes Erevos beginnt mit Glass (Scheiben), Modernist, System, Meine Farbe in Himmelblau, der Schrift des Telefons und eckigen Nachrichten. Ein vorher gewähltes Aussehen bleibt, wie es war. Siehe [Aussehen](#appearance).",
  "**Modules names only what Erevos has**: under **Settings** → **General**, **Modules** no longer lists Nostr, Matrix and XMPP, which are in Erevos+.": "**Module nennt nur, was Erevos hat**: Unter **Einstellungen** → **Allgemein** nennt **Module** nicht mehr Nostr, Matrix und XMPP, die in Erevos+ sind.",
  "**The guide tells only of what Erevos has**: in Erevos, the user guide no longer speaks of Matrix, XMPP and the chats with other Nostr apps, which are in Erevos+. See [Erevos or Erevos+, and betas](#updates).": "**Die Anleitung nennt nur, was Erevos hat**: In Erevos spricht die Anleitung nicht mehr von Matrix, XMPP und den Chats mit anderen Nostr-Apps, die in Erevos+ sind. Siehe [Erevos oder Erevos+, und Betas](#updates).",
  "**Meeting someone in one tap**: **New chat** now starts with two big buttons, **Scan their QR code** and **Show your QR code**; one of you scanning the other is enough, and the rest is under them. See [Chat through a relay](#relay).": "**Jemanden mit einem Tippen treffen**: **Neuer Chat** beginnt jetzt mit zwei großen Knöpfen, **Ihren QR-Code scannen** und **Deinen QR-Code zeigen**; es reicht, wenn einer von euch den anderen scannt, der Rest steht darunter. Siehe [Chat über ein Relay](#relay).",
  "**The panic button, found at once**: it is first, in red, in the **⋯** menu of the home screen, and holding down the lock at the top of the home screen opens it. See [Panic button](#panic).": "**Der Panikknopf, sofort gefunden**: Er steht zuerst, in Rot, im Menü **⋯** des Startbildschirms, und wer das Schloss oben auf dem Startbildschirm gedrückt hält, öffnet ihn. Siehe [Panikknopf](#panic).",
  "**New chat looks the same every time**: the two big buttons are always at the top; **How you connect now** shows only while something is missing, and says it in plain words; **Your contact link** and **Invite someone** are rows, with no second QR code button. See [Chat through a relay](#relay).": "**Neuer Chat sieht immer gleich aus**: die zwei großen Knöpfe sind immer oben; **So bist du jetzt verbunden** erscheint nur, solange etwas fehlt, und sagt es in einfachen Worten; **Dein Kontaktlink** und **Jemanden einladen** sind Zeilen, ohne zweiten QR-Code-Knopf. Siehe [Chat über ein Relay](#relay).",
  "**One scan is all**: where your relay lets your phone invite, **Show your QR code** shows an invite for one person, so a phone new to Erevos joins your relay by itself as it scans it, typing nothing, and you are contacts at once; for someone else, tap **New QR code**. And with a relay, its queue is made by itself: **Create my relay queue** is there only to try again, should that fail. See [Chat through a relay](#relay).": "**Ein Scan genügt**: wo dein Relay deinem Handy das Einladen erlaubt, zeigt **Deinen QR-Code zeigen** eine Einladung für eine Person, sodass ein Handy, das neu bei Erevos ist, beim Scannen von selbst deinem Relay beitritt, ohne etwas einzutippen, und ihr seid sofort Kontakte; für jemand anderen tippst du auf **Neuer QR-Code**. Und mit einem Relay wird dessen Warteschlange von selbst angelegt: **Meine Relay-Warteschlange anlegen** ist nur noch da, um es erneut zu versuchen, falls das scheitert. Siehe [Chat über ein Relay](#relay).",
  "**Video calls take about half the data**: a video call over the internet goes through the call relay, so that neither side sees the other's address; its picture is now held to 1 Mbps, which on a phone looks much the same. A call on the same network is not held back.": "**Videoanrufe brauchen etwa halb so viele Daten**: ein Videoanruf übers Internet läuft über das Anruf-Relay, damit keine Seite die Adresse der anderen sieht; sein Bild ist jetzt auf 1 Mbit/s begrenzt, was auf dem Handy fast genauso aussieht. Ein Anruf im selben Netz wird nicht gebremst.",
  "**A stranger's message shows only its words**: a message request, from someone who has only your contact link, shows only what it says until you accept it. Its photos and files wait, not taken, and its links show no preview. See [Chat through a relay](#relay).": "**Die Nachricht eines Fremden zeigt nur ihre Worte**: Eine Nachrichtenanfrage, von jemandem, der nur deinen Kontaktlink hat, zeigt nur, was sie sagt, bis du sie annimmst. Ihre Fotos und Dateien warten ungeladen, und ihre Links zeigen keine Vorschau. Siehe [Chat über ein Relay](#relay).",
  "**Photos sent as files say nothing of where they were taken**: a photo sent with **File** (JPEG, PNG, GIF or WebP) goes without where and when it was taken and the phone, as a photo does; a GIF sent as a photo keeps moving, now without its hidden notes.": "**Als Datei gesendete Fotos verraten nicht, wo sie aufgenommen wurden**: Ein Foto, das du mit **Datei** sendest (JPEG, PNG, GIF oder WebP), geht ohne Ort, Zeit und Telefon, wie ein Foto; ein als Foto gesendetes GIF bewegt sich weiter, jetzt ohne seine versteckten Notizen.",
  "**A word of care over a stranger's first messages**: if a message request asks for a code, a PIN, a password or money, promises easy money, or its name looks like one of your contacts', **Be careful** says so above it. Erevos looks for this on your phone only, and blocks nothing. See [Chat through a relay](#relay).": "**Ein Wort der Vorsicht über den ersten Nachrichten eines Fremden**: Fragt eine Nachrichtenanfrage nach einem Code, einer PIN, einem Passwort oder Geld, verspricht sie leichtes Geld, oder ähnelt ihr Name dem eines deiner Kontakte, sagt **Vorsicht** es darüber. Erevos sucht das nur auf deinem Telefon und blockiert nichts. Siehe [Chat über ein Relay](#relay).",
  "**Tor finds its own way through**: under **Bridges**, **Automatic** tries Tor straight, then the obfs4 bridges, then Snowflake, then your own, until one connects, and remembers for 30 days the one that worked on Wi-Fi and on mobile data. **My network is watched** makes it never try straight, and **Check my connection** says whether Tor connects, and how, never your address. See [Through Tor](#tor).": "**Tor findet seinen Weg selbst**: Unter **Brücken** versucht **Automatisch** Tor direkt, dann die obfs4-Brücken, dann Snowflake, dann deine eigenen, bis eine Verbindung steht, und merkt sich 30 Tage, was im WLAN und in mobilen Daten funktioniert hat. **Mein Netz wird überwacht** lässt es nie direkt versuchen, und **Meine Verbindung prüfen** sagt, ob Tor sich verbindet und wie, nie deine Adresse. Siehe [Über Tor](#tor).",
  "**The bar at the top stays**: on the home screen, the bar with Erevos and its buttons no longer scrolls away with the list, and in SMS chats, as in those of the other networks, the name of the chat, its calls and who is online stay at the top while the messages scroll, as in Erevos's own chats.": "**Die Leiste oben bleibt**: auf dem Startbildschirm scrollt die Leiste mit Erevos und seinen Schaltflächen nicht mehr mit der Liste weg, und in SMS-Chats, wie in denen der anderen Netze, bleiben der Name des Chats, seine Anrufe und wer online ist oben stehen, während die Nachrichten scrollen, wie in Erevos’ eigenen Chats.",
  "**A simpler field in Matrix and XMPP chats**: under it there is only **+**, for photos, files and the rest, and the microphone; the chat's settings are under **⋯** at the top.": "**Ein einfacheres Feld in Matrix- und XMPP-Chats**: darunter gibt es nur noch **+**, für Fotos, Dateien und den Rest, und das Mikrofon; die Einstellungen des Chats sind oben unter **⋯**.",
  "**Adding a contact with 8 digits**: **Pair with a code** on **New chat** lets one phone show a code of 8 digits and the other type it, said aloud or read off the screen, and you are each other's contacts, with no QR code or link to pass. The code never leaves the phones, and whoever guesses gets 3 tries. See [Chat through a relay](#relay).": "**Einen Kontakt mit 8 Ziffern hinzufügen**: **Mit einem Code koppeln** in **Neuer Chat** lässt ein Telefon einen Code aus 8 Ziffern zeigen und das andere ihn eintippen, laut gesagt oder vom Bildschirm gelesen, und ihr seid gegenseitig Kontakte, ohne QR-Code oder Link weiterzugeben. Der Code verlässt die Telefone nie, und wer rät, hat 3 Versuche. Siehe [Chat über ein Relay](#relay).",
  "**A voice not your own**: in a contact's chat details, **Change my voice** sends your voice messages in that chat **Deeper** or **Higher**, as long as you spoke. The change is made on your phone before the message goes, so your own voice never leaves it. On Android 10 and later, and in browsers that make Opus themselves. See [Chat through a relay](#relay).": "**Eine Stimme, die nicht deine ist**: In den Details des Chats mit einem Kontakt schickt **Meine Stimme ändern** deine Sprachnachrichten in diesem Chat **Tiefer** oder **Höher**, so lang, wie du gesprochen hast. Die Änderung geschieht auf deinem Telefon, bevor die Nachricht geht, deine eigene Stimme verlässt es also nie. Auf Android 10 und neuer und in Browsern, die selbst Opus erzeugen. Siehe [Chat über ein Relay](#relay).",
  "**A word of care under a short password**: setting the password of a space or the PIN of hidden chats, Erevos now says when it is short: someone who breaks into the phone's own security could guess it on computers of their own. A phrase of 4 or 5 words is far safer. It still takes a short one. See [Password lock](#lock).": "**Ein Wort der Vorsicht unter einem kurzen Passwort**: Beim Festlegen des Passworts eines Bereichs oder der PIN versteckter Chats sagt Erevos jetzt, wenn es kurz ist: Wer die Sicherheit des Telefons selbst knackt, könnte es auf eigenen Computern erraten. Ein Satz aus 4 oder 5 Wörtern ist viel sicherer. Ein kurzes nimmt es weiterhin. Siehe [Passwortsperre](#lock).",
  "**Groups that end**: a public group can now be a burner group, for one event. Under **It ends**, choose after a day, 3 days or 7 days, and when its time is up every member's Erevos deletes it, with its messages, photos and files, and its link stops working. See [public groups](#public-groups).": "**Gruppen, die enden**: Eine öffentliche Gruppe kann jetzt eine Wegwerfgruppe sein, für einen Anlass. Wähle unter **Endet** nach einem Tag, 3 Tagen oder 7 Tagen, und ist ihre Zeit um, löscht das Erevos jedes Mitglieds sie mit ihren Nachrichten, Fotos und Dateien, und ihr Link funktioniert nicht mehr. Siehe [Öffentliche Gruppen](#public-groups).",
  "**A photo to see once**: under **+** in a chat or a group, **Photo to see once** sends a photo that never shows in the chat, and **Camera, to see once** one you take then. They see it once, on its own, kept out of screenshots where the phone allows, and as it closes it is deleted from their phone. It cannot be forwarded or saved. See [Chat through a relay](#relay).": "**Ein Foto zum einmaligen Ansehen**: unter **+** in einem Chat oder einer Gruppe sendet **Foto zum einmaligen Ansehen** ein Foto, das nie im Chat erscheint, und **Kamera, zum einmaligen Ansehen** eines, das du gerade aufnimmst. Sie sehen es einmal für sich, wo das Telefon es erlaubt ohne Bildschirmfotos, und beim Schließen wird es von ihrem Telefon gelöscht. Es lässt sich weder weiterleiten noch speichern. Siehe [Chat über ein Relay](#relay).",
  "**Threads in a contact's chat too**: hold a message and choose **Reply in thread**, as in a group. The thread shows alone and what you send there answers it; **n answers in the thread** under a message opens it. See [Chat through a relay](#relay).": "**Threads auch im Chat mit einem Kontakt**: Halte eine Nachricht gedrückt und wähle **Im Thread antworten**, wie in einer Gruppe. Der Thread erscheint allein, und was du dort sendest, antwortet darauf; **n Antworten im Thread** unter einer Nachricht öffnet ihn. Siehe [Chat über ein Relay](#relay).",
  "**A voice message in words**: hold a voice message and choose **In words**, and your phone writes out what was said, in about a hundred languages, Greek among them. The first time it downloads a speech model of 268 MB, once you say so; then everything is done on your phone, and neither the sound nor its words leave it. On Android. See [Chat through a relay](#relay).": "**Eine Sprachnachricht in Worten**: Halte eine Sprachnachricht gedrückt und wähle **In Worten**, und dein Telefon schreibt auf, was gesagt wurde, in etwa hundert Sprachen, Griechisch darunter. Beim ersten Mal lädt es, wenn du es sagst, ein Sprachmodell von 268 MB; danach geschieht alles auf deinem Telefon, und weder der Ton noch seine Worte verlassen es. Auf Android. Siehe [Chat über ein Relay](#relay).",
  "**Translate a message**: hold a message and choose **Translate**, and your phone translates it into your language, between Greek, English, German, Spanish, French and Italian. The first time for a language it downloads its translation models, of 60 to 95 MB each, once you say so; then everything is done on your phone, and neither the message nor its translation leave it. On Android. See [Chat through a relay](#relay).": "**Eine Nachricht übersetzen**: Halte eine Nachricht gedrückt und wähle **Übersetzen**, und dein Telefon übersetzt sie in deine Sprache, zwischen Griechisch, Englisch, Deutsch, Spanisch, Französisch und Italienisch. Beim ersten Mal für eine Sprache lädt es, wenn du es sagst, ihre Übersetzungsmodelle von je 60 bis 95 MB; danach geschieht alles auf deinem Telefon, und weder die Nachricht noch ihre Übersetzung verlassen es. Auf Android. Siehe [Chat über ein Relay](#relay).",
  "**Phones nearby carry for each other from the start**: **Carry messages for others**, under **Nearby, with no internet** on **New chat**, is now on until you turn it off, so a message that cannot reach its relay finds more phones to take it there. What this phone carries is sealed: it cannot read it, nor tell who it is from or for. See [Chat with a nearby phone](#nearby).": "**Telefone in der Nähe nehmen von Anfang an füreinander mit**: **Nachrichten für andere mitnehmen**, unter **In der Nähe, ohne Internet** in **Neuer Chat**, ist jetzt an, bis du es ausschaltest, sodass eine Nachricht, die ihr Relay nicht erreicht, mehr Telefone findet, die sie dorthin bringen. Was dieses Telefon mitnimmt, ist verschlüsselt: Es kann es nicht lesen und nicht sagen, von wem oder für wen es ist. Siehe [Chat mit einem Telefon in der Nähe](#nearby).",
  "**Last seen is when they closed Erevos**: with **Say when I open and close Erevos** on, closing Erevos, or its hidden chats, now tells those you told while it was open when it closed, so their **last seen** is that time, not when they last heard from you. And you show online only while the chats they talk to you in are open: not while your hidden chats are open instead. See [Chat through a relay](#relay).": "**Zuletzt online ist, wann Erevos geschlossen wurde**: mit **Sagen, wenn ich Erevos öffne und schließe** an erfahren beim Schließen von Erevos, oder seiner verborgenen Chats, die, denen es gesagt wurde, solange es offen war, jetzt, wann es schloss, so dass ihr **Zuletzt online** diese Zeit zeigt, nicht wann sie zuletzt von dir hörten. Und du erscheinst nur online, solange die Chats offen sind, in denen sie mit dir schreiben: nicht, während stattdessen deine verborgenen Chats offen sind. Siehe [Chat über ein Relay](#relay).",
  "**Sign in at another relay**: under **Sign in with LPHL** on New chat, **Sign in at another relay…** takes another relay's address, and the card signs in there with the accounts that relay takes; one that takes none says so, and its operator can give you an invite. See [Chat through a relay](#relay).": "**Bei einem anderen Relay anmelden**: Unter **Mit LPHL anmelden** in Neuer Chat nimmt **Bei einem anderen Relay anmelden…** die Adresse eines anderen Relays, und die Karte meldet dich dort mit den Konten an, die dieses Relay annimmt; eines, das keine annimmt, sagt es, und sein Betreiber kann dir eine Einladung geben. Siehe [Chat über ein Relay](#relay).",
  "**Post-quantum, all the way**: between two phones on this Erevos, every message of a chat is now also locked with a fresh ML-KEM key, a new one every few dozen messages, not only at the start. So someone who records your messages today and has a quantum computer one day still cannot read them. By itself, with nothing to turn on; not in groups.": "**Post-Quanten-Schutz durchgehend**: Zwischen zwei Telefonen mit diesem Erevos wird jetzt jede Nachricht eines Chats zusätzlich mit einem frischen ML-KEM-Schlüssel verschlüsselt, alle paar Dutzend Nachrichten ein neuer, nicht nur am Anfang. Wer deine Nachrichten heute aufzeichnet und eines Tages einen Quantencomputer hat, kann sie trotzdem nicht lesen. Von selbst, nichts einzuschalten; nicht in Gruppen.",
  "**The Collection asks for your password**: where the space has a password, the Collection asks for it each time it opens, and again after Erevos was away more than 30 seconds; a fingerprint or face works too. See [Collection](#collection).": "**Die Sammlung fragt nach deinem Passwort**: Hat der Bereich ein Passwort, fragt die Sammlung jedes Mal danach, wenn sie sich öffnet, und wieder, wenn Erevos länger als 30 Sekunden weg war; Fingerabdruck oder Gesicht gehen auch. Siehe [Collection](#collection).",
  "**Messenger in its case**: in Erevos+, Messenger can now be used in its case instead of by Erevos: Meta's own Messenger page, as on a computer, closed in by Erevos with the same sign-in. Only Meta's sites load in it, links out open in your browser without Facebook's tracking marks, nothing of the sign-in stays in it once closed, and calls work in it. Choose it on the Messenger screen under **How Messenger is used here**; its chats are then not in Erevos's lists and Erevos does not notify of them. Through Tor, if Messenger goes through Tor, and then without calls.":
    "**Messenger in seiner Hülle**: in Erevos+ kann Messenger jetzt in seiner Hülle statt durch Erevos genutzt werden: Metas eigene Messenger-Seite, wie am Computer, von Erevos mit derselben Anmeldung eingeschlossen. Nur Metas Seiten laden darin, Links nach draußen öffnen sich in deinem Browser ohne Facebooks Tracking-Marken, nichts von der Anmeldung bleibt darin, wenn sie geschlossen ist, und Anrufe funktionieren darin. Wähle es auf dem Messenger-Bildschirm unter **Wie Messenger hier genutzt wird**; seine Chats sind dann nicht in den Listen von Erevos, und Erevos benachrichtigt nicht über sie. Über Tor, wenn Messenger über Tor geht, und dann ohne Anrufe.",
  "**Messenger chats you read stay read**: a Messenger chat you marked read right after Erevos+ started, while Messenger was still connecting, no longer comes back as unread; a chat whose last message is yours, sent from Messenger's own app or the web, is read; and encrypted chats you read in Messenger's app or on the web are read here too.":
    "**Gelesene Messenger-Chats bleiben gelesen**: ein Messenger-Chat, den du gleich nach dem Start von Erevos+ als gelesen markiert hast, während Messenger noch verband, wird nicht wieder ungelesen; ein Chat, dessen letzte Nachricht von dir ist, gesendet aus der Messenger-App oder dem Web, ist gelesen; und verschlüsselte Chats, die du in der Messenger-App oder im Web gelesen hast, sind auch hier gelesen.",
  "**Messenger in its case fits the phone, and Facebook's feed is a tap away**: in Erevos+, Messenger in its case is now laid out at the phone's width, so it reads without zooming in, and shows under Erevos's own bar, in its colours, with **←** back to Erevos and **Facebook** to see Facebook's feed in the same page. Facebook also has a card of its own in the **Services** window, beside Messenger. See [Messenger](#messenger).":
    "**Messenger in seiner Hülle passt aufs Telefon, und der Feed von Facebook ist einen Tipp entfernt**: in Erevos+ ist Messenger in seiner Hülle jetzt auf die Breite des Telefons gelegt, sodass es ohne Vergrößern lesbar ist, und zeigt sich unter der eigenen Leiste von Erevos, in seinen Farben, mit **←** zurück zu Erevos und **Facebook**, um den Feed von Facebook in derselben Seite zu sehen. Facebook hat auch eine eigene Karte im Fenster **Dienste**, neben Messenger. Siehe [Messenger](#messenger).",
  "**Messenger in its case asks for the PIN once**: in Erevos+, what Meta's page keeps now stays in the case between openings, apart from every other page, so Meta knows your phone again and no longer asks for the PIN of your encrypted chats each time you open it. It goes when you sign out of Messenger, or when another account opens the case. See [Messenger](#messenger).":
    "**Messenger in seiner Hülle fragt nur einmal nach der PIN**: In Erevos+ bleibt, was Metas Seite speichert, jetzt zwischen den Öffnungen in der Hülle, getrennt von jeder anderen Seite, sodass Meta dein Telefon wiedererkennt und nicht mehr bei jedem Öffnen nach der PIN deiner verschlüsselten Chats fragt. Es verschwindet, wenn du dich von Messenger abmeldest oder ein anderes Konto die Hülle öffnet. Siehe [Messenger](#messenger).",
  "**Messenger in its case wears your whole look**: in Erevos+, Meta's own Messenger page in its case now takes your look: its colours, dark or light as Erevos is, the shape of your bubbles (round, square or a line), your text size, your style's letters, and what lies behind your screens (a wallpaper, Neon's grid, Paper's lines and the others), and it changes with your look even while it is open. A photo of your own stays in Erevos: there the page shows a soft gradient instead. Where Meta changes its page, parts of it may keep Meta's look. See [Messenger](#messenger).":
    "**Messenger in seiner Hülle trägt dein ganzes Aussehen**: In Erevos+ nimmt Metas eigene Messenger-Seite in ihrer Hülle jetzt dein Aussehen an: seine Farben, dunkel oder hell wie Erevos, die Form deiner Blasen (rund, eckig oder eine Linie), deine Textgröße, die Schrift deines Stils und was hinter deinen Bildschirmen liegt (ein Hintergrund, das Gitter von Neon, die Linien von Paper und die anderen), und sie ändert sich mit deinem Aussehen, auch während sie offen ist. Ein eigenes Foto bleibt in Erevos: Dort zeigt die Seite stattdessen einen sanften Verlauf. Wo Meta seine Seite ändert, können Teile davon Metas Aussehen behalten. Siehe [Messenger](#messenger).",
  "**Messenger in its case tells you of new messages**: in Erevos+, when you use Messenger in its case, Erevos now tells you of its new messages as it does of other chats, even if you never opened the case. A chat with messages not read shows on home until it is read, and tapping it opens it in the case; while the case is open, Erevos tells of nothing, as the page shows it. See [Messenger](#messenger).":
    "**Messenger in seiner Hülle meldet neue Nachrichten**: In Erevos+ benachrichtigt dich Erevos jetzt über neue Messenger-Nachrichten, wenn du Messenger in seiner Hülle nutzt, wie bei anderen Chats, auch wenn du die Hülle nie geöffnet hast. Ein Chat mit ungelesenen Nachrichten steht auf der Startseite, bis er gelesen ist, und ein Tippen öffnet ihn in der Hülle; solange die Hülle offen ist, benachrichtigt Erevos nicht, da die Seite es zeigt. Siehe [Messenger](#messenger).",
};
